  "cardInfo": {
    "swordsman": {
      "icon": "❯",
      "desc": "단단한 씨앗 몸에서 자란 큰 칼잎으로 정면 전선을 밀어붙이는 기본 근접병입니다."
    },
    "pikeman": {
      "icon": "▲",
      "desc": "긴 가시줄기를 뻗어 근중거리에서 적을 밀어내고 돌진 접근을 끊습니다."
    },
    "archer": {
      "icon": "❖",
      "desc": "탄성 잎활에서 단단한 씨앗탄을 날려 후방에서 안정적으로 화력을 누적합니다."
    },
    "fireant": {
      "icon": "♨",
      "desc": "산성 씨앗탄으로 소형 적을 집중 사냥하며, 연구 후 일정 확률로 평타 대신 좁은 산성 브레스를 분사합니다."
    },
    "skirmisher": {
      "icon": "✦",
      "desc": "등의 포자낭을 압축 분사해 이동하면서도 빠른 포자탄을 연속 발사합니다."
    },
    "shellbug": {
      "icon": "⬣",
      "desc": "값싼 전열 병사로, 연구 후 교전 중 자리를 잡고 웅크리면 고정 방어력으로 잔딜에 강해집니다."
    },
    "stingbug": {
      "icon": "⌁",
      "desc": "짧은 사거리에서 강하게 찌르며, 연구 후 이동 없이 공격을 이어갈수록 공격속도가 누적되는 경량 공격병입니다."
    },
    "dandelion": {
      "icon": "✹",
      "desc": "민들레 씨앗처럼 빠르게 떠밀리며 빈 공간과 후열을 노리는 초고속 경량병입니다."
    },
    "thornfruit": {
      "icon": "✺",
      "desc": "HP는 낮지만 기본 고정 방어력으로 잔딜을 버티며, 연구 후 빠른 연타를 가시 폭발로 역카운터합니다."
    },
    "kickhopper": {
      "icon": "⌃",
      "desc": "큰 뒷다리로 적 하나를 걷어 올려 짧게 에어본시키고 공격 선딜을 끊는 근접 제어병입니다."
    },
    "tank": {
      "icon": "⬢",
      "desc": "여러 겹의 거대 씨앗껍질로 원거리 화력을 흡수하며 전선을 고정하는 정예 전열입니다."
    },
    "rogue": {
      "icon": "↯",
      "desc": "벼룩처럼 도약해 후열에 달라붙고, 연구 후 착지 충격으로 단일 피해와 주변 에어본을 줍니다."
    },
    "mage": {
      "icon": "✺",
      "desc": "꽃술에 압축한 폭발성 꽃가루를 터뜨려 밀집 진형을 원형 범위로 무너뜨립니다."
    },
    "lancer": {
      "icon": "♢",
      "desc": "왕사슴벌레의 가속을 축적한 뒤 거대한 턱으로 후열과 전선을 들이받는 정예 돌격병입니다."
    },
    "medic": {
      "icon": "◍",
      "desc": "이슬줄기로 마나를 소모해 아군을 회복하고 주변 은신 생물을 감지합니다."
    },
    "mantis": {
      "icon": "◖",
      "desc": "잎사귀와 동화해 은신 정찰하고 낫 앞다리의 매복 첫타로 후열을 찌르는 베일 사마귀입니다."
    },
    "pillbug": {
      "icon": "◌",
      "desc": "빛나는 폭낭을 품고 돌진해 자폭하며, 연구 후 그림자벼룩과 같은 도약으로 접근 성공률을 높입니다."
    },
    "rootstalker": {
      "icon": "╫",
      "desc": "구근 몸체를 지면에 고정한 뒤 땅속 뿌리에서 직선 가시를 연속으로 솟구칩니다."
    },
    "chainflower": {
      "icon": "⌁",
      "desc": "꽃 전류가 첫 대상에서 가까운 적으로 연쇄되어 밀집 진형을 갉아먹습니다."
    },
    "guardshroom": {
      "icon": "☂",
      "desc": "주변의 보호막 없는 아군 여러 명에게 주기적으로 1회 타격 보호막을 부여하고 대상마다 마나를 사용합니다."
    },
    "sporeherd": {
      "icon": "❉",
      "desc": "마나를 사용해 포자병을 일정 수까지 소환하며 연구 후 포자병이 도약합니다."
    },
    "clawhunter": {
      "icon": "⋔",
      "desc": "자체 시야보다 먼 적도 아군이 확보한 시야를 활용해 갈고리로 후열을 끌어와 진형을 무너뜨립니다."
    },
    "siege": {
      "icon": "◉",
      "desc": "뿌리 지지대를 전개한 뒤 초장거리에서 무거운 철갑씨앗탄 한 발을 좁고 강하게 꽂습니다."
    },
    "rocket": {
      "icon": "✾",
      "desc": "봉선화 씨방 4개에서 고각 씨앗로켓을 연속 발사해 서로 다른 지점을 연쇄 폭격합니다."
    },
    "shelltitan": {
      "icon": "⬡",
      "desc": "거대한 껍질과 충격파로 전선을 밀어붙이는 정예 거신입니다."
    },
    "swarmbug": {
      "icon": "⁙",
      "desc": "이동 중에는 땅속으로 파고들어 공격을 피하고, 사거리 안에서 솟아올라 대량으로 달라붙는 군락 병종입니다."
    },
    "aegisbeetle": {
      "icon": "◉",
      "desc": "빠른 전기 아크로 지속 피해를 주며, 충전된 마나를 소모해 주변 적 투사체를 직접 요격하는 지원 병종입니다."
    },
    "burrowbeast": {
      "icon": "⌄",
      "desc": "잠복한 뒤 실제 지하 좌표로 빠르게 후방까지 이동하고, 분출하면서 주변 피해·에어본을 주는 근접 광역 생물입니다."
    },
    "deepthorn": {
      "icon": "♜",
      "desc": "땅속 거대 뿌리를 대상 위치에서 솟구쳐 좁은 범위를 강타하고 주변 지상 유닛을 공중으로 띄우는 제어 거수입니다."
    },
    "flowerbee": {
      "icon": "✤",
      "desc": "지상군 위를 넘어 곧장 합류하는 기본형 근접 공중 전투병입니다."
    },
    "sporefly": {
      "icon": "⁙",
      "desc": "개체는 약하지만 많은 수가 지상군과 겹쳐 달라붙는 물량형 공중 근접병입니다."
    },
    "gustmayfly": {
      "icon": "≋",
      "desc": "극단적인 비행 속도로 먼 전선에 빠르게 합류하는 속도형 공중 근접병입니다."
    },
    "lanternmoth": {
      "icon": "✧",
      "desc": "넓은 시야와 Detection으로 은신을 밝히고 장거리 포병의 관측을 돕는 원거리 공중 유틸입니다."
    },
    "sporemoth": {
      "icon": "☁",
      "desc": "공중에서 지상 밀집 병력에 포자탄을 떨어뜨리는 지상 전용 광역 폭격기입니다."
    },
    "hunterwasp": {
      "icon": "⌁",
      "desc": "빠른 근접 전투로 지상·공중 적에게 달라붙는 정예 비행병입니다."
    },
    "sailwing": {
      "icon": "◒",
      "desc": "큰 돛날개로 주변 아군 지상·공중 병력의 이동속도를 상시 높이는 기동 지원체입니다."
    },
    "ancientmistray": {
      "icon": "〰",
      "desc": "자신과 같은 종류를 제외한 주변 아군 유닛을 지속 클로킹하는 거대 공중 지원체입니다."
    },
    "hivecarrier": {
      "icon": "◈",
      "desc": "고속 선회·부상 귀환을 반복하는 공생 비행충을 운용하며, 격추된 공생충은 마나를 소비해 재생하는 거대 군락 모함입니다."
    },
    "carriermite": {
      "icon": "·",
      "desc": "군락모함에서 출격하는 공생 비행충입니다."
    }
  },
