function purchaseCost(kind){if(kind==='cap'){let next=state.capTier+1;if(next>CONFIG.progression.capTierByZone[state.maxZone])return null;return[CONFIG.progression.capCosts[next],CONFIG.progression.capGas[next]]}const d=CONFIG.upgrades[kind];if(!d||state.upgrades[kind]>=CONFIG.progression.levelsPerZone*(state.maxZone+1))return null;const l=state.upgrades[kind];return[Math.ceil(d.baseM*Math.pow(d.growth,l)/CONFIG.economy.costStep)*CONFIG.economy.costStep,Math.ceil(d.baseG*Math.pow(d.growth,l)/CONFIG.economy.costStep)*CONFIG.economy.costStep]}
function buy(kind){const c=purchaseCost(kind);if(!c||state.minerals<c[0]||state.gas<c[1])return false;state.minerals-=c[0];state.gas-=c[1];state.stats.spentM+=c[0];state.stats.spentG+=c[1];if(kind==='cap')state.capTier++;else{state.upgrades[kind]++;if(kind==='health'){const old=1+(state.upgrades.health-1)*CONFIG.economy.healthPerLevel,newScale=1+state.upgrades.health*CONFIG.economy.healthPerLevel;for(const u of state.units)if(u.team==='friendly'){const ratio=u.hp/u.maxHp;u.maxHp*=newScale/old;u.hp=u.maxHp*ratio}state.mother.hp+=CONFIG.mother.hpPerLevel;state.mother.maxHp=maxMotherHP()}}save();uiClock=CONFIG.render.uiInterval;return true}
function setCard(slot,type){if(!Number.isInteger(slot)||slot<0||slot>=state.cards.length||!slotOpen(slot)||type!==null&&(!friendlyTypes.includes(type)||!unlocked(type)))return false;if(state.cards[slot].type===type)return true;if(type!==null&&state.cards.filter((c,i)=>i!==slot&&c.type===type).length>=CONFIG.production.maxCopies)return false;state.cards[slot]={type,progress:0,blocked:''};save();uiClock=CONFIG.render.uiInterval;return true}
function defeat(player=WorldPlayers.byAccount(-1)){return PlayerLifecycle.defeat(player,null)}
function recover(player=WorldPlayers.byAccount(-1)){return bloomInTick?PlayerLifecycle.recover(player):false}
function snapshot(){return JSON.parse(JSON.stringify(state))}
function save(){if(bloomInTick||bloomInitializing){bloomPersistenceRequested=true;return true;}try{localStorage.setItem(CONFIG.saveKey,JSON.stringify({...state,units:state.units.filter(u=>u.hp>0)}));return true}catch{return false}}
let load;
const canvas=(globalThis.BLOOM_HEADLESS ? null : ($('view'))),ctx=(globalThis.BLOOM_HEADLESS ? null : (BloomWebGL.create(canvas))),mini=(globalThis.BLOOM_HEADLESS ? null : ($('mini').getContext('2d')));
function hashRandom(seed){let n=seed;return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296}}
function ellipse(c,x,y,rx,ry,a,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,a,0,Math.PI*2);c.fill()}

function drawNest(c,x,y,level,scale=1){c.save();c.translate(x,y);c.scale(scale,scale);let size=35+level*8;ellipse(c,0,12,size*1.45,size*.68,0,'#18382735');for(let i=0;i<7;i++){let a=i*Math.PI*2/7;ellipse(c,Math.cos(a)*size*.6,Math.sin(a)*size*.38,size*.38,size*.8,a,'#405d38');ellipse(c,Math.cos(a)*size*.5,Math.sin(a)*size*.32,size*.3,size*.65,a,'#95b67a')}ellipse(c,0,0,size*.75,size*.5,0,'#d4dfb0');ellipse(c,0,-6,size*.55,size*.4,0,'#647e49');ellipse(c,0,-9,size*.26,size*.2,0,'#dcefba');for(let i=0;i<level;i++){let a=i*2.399;ellipse(c,Math.cos(a)*size,Math.sin(a)*size*.7,9,13,a,'#d1daa2')}c.restore()}
function drawMother(source=WorldView.leader()){const u=source;cshadow(u.x,u.y,CONFIG.mother.size*1.2);ctx.save();const bounce=u.moveSpeed>0?Math.sin(u.movePhase||0)*CONFIG.combat.motherWalkBounce:0;ctx.translate(u.x,u.y-bounce);const squash=1+(u.moveSpeed>0?Math.sin(u.movePhase||0)*CONFIG.combat.poseSquash:0)+(u.flash>0?CONFIG.combat.hitSquash:0);ctx.scale(squash,1/squash);const t=state.time,level=Math.floor(state.capTier/3),size=CONFIG.mother.size;ctx.rotate(Math.sin(t)*.04);for(let i=0;i<8;i++){let a=i*Math.PI/4;ellipse(ctx,Math.cos(a)*size*.72,Math.sin(a)*size*.58,size*.3,size*.67,a+Math.PI/2,'#334f35');ellipse(ctx,Math.cos(a)*size*.7,Math.sin(a)*size*.56,size*.23,size*.6,a+Math.PI/2,'#a8c991')}ellipse(ctx,0,0,size*.85,size*.74,0,u.flash>0?'#fff7d9':'#d9e9c0');ellipse(ctx,-2,-4,size*.58,size*.5,0,'#7fa184');ellipse(ctx,-4,-8,size*.39,size*.31,0,'#c4e5ca');ellipse(ctx,-7,-10,size*.14,size*.12,0,'#f1f8d7');for(let i=0;i<level+1;i++){let a=i*2.399+t*.1;ellipse(ctx,Math.cos(a)*size*.78,Math.sin(a)*size*.65,4,7,a,'#e9f1bb')}ctx.restore();ctx.strokeStyle='#f1f8d480';ctx.lineWidth=1;ctx.beginPath();ctx.arc(u.x,u.y,size+8,0,Math.PI*2);ctx.stroke()}
function cshadow(x,y,r){ellipse(ctx,x+3,y+r*.45,r,r*.45,0,'#1b332326')}
function drawUnit(source,options={}){
 if(source.hp<=0)return;
 const u=source,d=unitDef(u.type),r=unitVisualRadius(u)*CONFIG.render.spriteScale;
 const extent=options.preculled?null:unitVisualExtent(u),cull=Math.max(CONFIG.render.unitCullMargin,extent??0);
 if(!options.preculled&&!projectionVisible(u,cull))return;
 if(u.team==='enemy'&&u.pendingMelee){const p=u.pendingMelee,ready=clamp(1-p.left/p.total,0,1);ctx.save();ctx.strokeStyle='#ff947d';ctx.lineWidth=1.5+ready;ctx.globalAlpha=.35+.5*ready;ctx.beginPath();if(d.projectile){indicatorGroundLine(ctx,u.x,u.y,p.aimX,p.aimY,true);ctx.stroke();terrainCirclePath(p.aimX,p.aimY,10)}else{indicatorGroundArc(ctx,u.x,u.y,effectiveRange(source)+CONFIG.control.meleeSlack+12,effectiveRange(source)+CONFIG.control.meleeSlack+12,u.angle-.7,u.angle+.7,true,false)}ctx.stroke();ctx.restore()}
 const visible=!d.stealth||detected(source,'friendly')||u.reveal>bloomRenderWorld().time;ctx.globalAlpha=visible?1:CONFIG.combat.stealthOpacity;cshadow(u.x,u.y,r*.8);
 if(u.elite){ctx.strokeStyle='#f9dda2';ctx.lineWidth=2;ctx.beginPath();indicatorGroundArc(ctx,u.x,u.y+5,r+11,(r+11)*.7);ctx.stroke()}
 const basic=CONFIG.combat.poseTypes.includes(u.type),walk=basic&&u.moveSpeed>0?Math.min(1,u.moveSpeed/(effectiveSpeed(u)*CONFIG.motion.speedScale)):0,prep=basic&&u.pendingMelee?1-u.pendingMelee.left/u.pendingMelee.total:0,finish=basic&&!u.pendingMelee?(u.attackPose||0)/CONFIG.combat.attackPoseTime:0,deform=1+CONFIG.combat.poseSquash*(prep-finish)+(basic&&u.flash>0?CONFIG.combat.hitSquash:0),walkSine=walk?Math.sin(u.movePhase||0):0;
 const body=options.bodyPose||projectionBodyPose(u);projectionBillboard(ctx,body.x,body.y,body.z);
 if(window.RallyArt){const feedback=CombatFeedback.sample(u),animationTime=CombatFeedback.animationTime(u,presentationTime())*1000;RallyArt.draw(ctx,u.type,u.team,body.x,body.y,r,WorldProjection.angle(u.angle),animationTime,{factionPalette:WorldView.palette(u),gradeOutline:rarityOutline(u),poseStretch:deform,feedbackX:feedback.sx,feedbackY:feedback.sy,whiteFlash:feedback.white,poseTilt:walkSine*CONFIG.combat.walkTilt,attack:u.attackPose>0&&!u.pendingMelee,phaseOffsetMs:u.id*37,respectOriginalFacing:true,hit:u.flash>0,deployed:u.movement?.deployment.phase==='deployed',cloaked:!visible})}
 else ellipse(ctx,body.x,body.y,r,r,0,u.team==='friendly'?'#96c5f2':'#ea9a8a');
 ctx.restore();ctx.globalAlpha=1;
 if(u.shield&&u.shieldUntil>bloomRenderWorld().time)WorldUI.draw('shield',u,{radius:r});
 if(!options.suppressHealthBar&&u.hp<u.maxHp&&(!d.stealth||visible)){const w=u.elite?CONFIG.render.bossHealthWidth:CONFIG.render.healthBarWidth*(u.permanentRank?permanentGrowthScale(u.permanentRank):1),healthTop=u.permanentRank?(extent??unitVisualExtent(u)):r;WorldUI.draw('health',u,{width:w,extent:healthTop})}
 if(u.elite)WorldUI.draw('label',u,{text:u.boss?CONFIG.zones[u.zone].bossName:'정예 '+d.name,extent:extent??unitVisualExtent(u),gap:21,font:'bold 12px system-ui',color:'#fff0c6'});
}
function render(alpha=1,renderDelta=1/60){const started=performance.now(),world=bloomRenderWorld(),renderMother=combatBasePose(WorldView.leader());if(!renderMother)return;const dpr=Math.min(CONFIG.render.dprMax,devicePixelRatio||1),ww=innerWidth,hh=innerHeight;if(canvas.width!==Math.round(ww*dpr)||canvas.height!==Math.round(hh*dpr)){canvas.width=Math.round(ww*dpr);canvas.height=Math.round(hh*dpr)}view.zoom=moaCameraZoom(renderMother,ww);view.w=ww/view.zoom;view.h=hh/(view.zoom*WorldProjection.K);const worldWidth=worldLimit();const tx=view.w>=worldWidth?worldWidth/2:clamp(renderMother.x,view.w/2,worldWidth-view.w/2),ty=view.h>=CONFIG.world.height?CONFIG.world.height/2:clamp(renderMother.y,view.h/2,CONFIG.world.height-view.h/2);bloomCamera.setCamera({x:view.x,y:view.y*WorldProjection.K,zoom:view.zoom});bloomCamera.follow(tx,ty*WorldProjection.K,Math.max(0,renderDelta)*1000,Math.LN2*1000/CONFIG.render.presentation.cameraResponse);view.x=bloomCamera.camera.x;view.y=bloomCamera.camera.y/WorldProjection.K;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#3a593e';ctx.fillRect(0,0,ww,hh);if(typeof hitfeelApplyWorldShake==='function')hitfeelApplyWorldShake();ctx.scale(view.zoom,view.zoom);ctx.scale(1,WorldProjection.K);ctx.translate(view.w/2-view.x,view.h/2-view.y);
 for(const c of world.camps){if(c.zone>world.maxZone||!c.enabled||c.x<view.x-view.w/2-200||c.x>view.x+view.w/2+200)continue;ctx.strokeStyle=c.boss?'#f3d79444':'#29493630';ctx.lineWidth=c.boss?2:1;ctx.beginPath();ctx.ellipse(c.x,c.y,CONFIG.world.campRadius*(c.boss?1.25:1),CONFIG.world.campRadius*.7,0,0,Math.PI*2);ctx.stroke();if(c.boss&&world.bosses[c.zone]){drawNest(ctx,c.x,c.y,3,.7);ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillStyle='#e2efc1';ctx.fillText('정복한 군락',c.x,c.y+65)}}
 BloomDiagnostics.profileMeasure('render.terrain',drawCampaignWorld);BloomDiagnostics.profileMeasure('render.actors',drawProjectedActors);
 for(const e of presentation.maps.effect.values()){const original=presentation.effectRuntime.sample(e.id,e.generation,presentation.frameNow);if(!original)continue;const f={...original,y:original.y-(original.z||0)*WorldProjection.H/WorldProjection.K,y2:original.y2-(original.z2||0)*WorldProjection.H/WorldProjection.K};let a=f.life/f.maxLife;ctx.globalAlpha=a;ctx.strokeStyle=f.color;ctx.fillStyle=f.color;ctx.lineWidth=CONFIG.render.effectStroke;ctx.beginPath();if(f.kind==='ring'||f.kind==='burst'){const r=Math.max(1,f.r*(1-a));if(f.groundAnchor)terrainCirclePath(original.x,original.y,r);else ctx.arc(f.x,f.y,r,0,Math.PI*2)}else if(f.kind==='hit')ctx.arc(f.x,f.y,Math.max(1,f.r*.25),0,Math.PI*2);else{ctx.moveTo(f.x,f.y);ctx.lineTo(f.x2,f.y2)}ctx.stroke();ctx.globalAlpha=1}
 frameStats.frames++;frameStats.renderMs+=performance.now()-started;
}
function drawMini(){return bloomWithPresentation(()=>{const world=bloomRenderWorld(),leader=bloomRenderUnit(world.local.leaderId);mini.clearRect(0,0,180,104);const w=25,h=18,gap=4;for(let z=0;z<CONFIG.zones.length;z++){let x=4+z*(w+gap),y=43;mini.fillStyle=z>world.maxZone?'#ffffff10':CONFIG.zones[z].accent+'70';mini.fillRect(x,y,w,h);if(world.bosses[z]){mini.fillStyle='#d9f4a0';mini.font='12px system-ui';mini.fillText('✓',x+8,y-8)}if(world.zone===z){mini.strokeStyle='#e5f2c0';mini.lineWidth=2;mini.strokeRect(x-2,y-2,w+4,h+4)}if(z<CONFIG.zones.length-1){mini.strokeStyle='#cde0ba50';mini.beginPath();mini.moveTo(x+w,y+h/2);mini.lineTo(x+w+gap,y+h/2);mini.stroke()}}if(!leader)return;let x=4+leader.x/(CONFIG.world.zoneWidth*CONFIG.zones.length)*(CONFIG.zones.length*(w+gap));mini.fillStyle='#eff9ce';mini.beginPath();mini.arc(x,52,3,0,Math.PI*2);mini.fill()})}
const shortNames={swordsman:'칼잎전사',archer:'씨앗궁수',dandelion:'민들레주자',skirmisher:'포자사수',tank:'껍질수호자',medic:'이슬치유사',mage:'폭발꽃',flowerbee:'꽃벌',rogue:'그림자벼룩',guardshroom:'수호버섯',siege:'철갑씨앗포',shelltitan:'껍질거신'};
function fmt(n){return n>=10000?(n/1000).toFixed(1)+'k':Math.floor(n).toLocaleString('ko-KR')}
function portrait(type){return window.RallyArt?RallyArt.thumbnail(type,'friendly',{size:96}):''}
function toast(text){if(bloomInTick){bloomEmit("toast",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;$('status').textContent=text;$('status').style.opacity='1';toastClock=CONFIG.render.toastTime}
function openModal(kind,html){const same=modalKind===kind;paused=true;modalKind=kind;keys.clear();stick.x=stick.y=0;resetKnob();$('sheet').innerHTML=html;$('modal').classList.add('show');if(!same)$('sheet').scrollTop=0;refreshUI();globalThis.BloomSimulation?.runtime?.controls()}
function bloomFocusWorld(){if(globalThis.BLOOM_HEADLESS)return;const surface=$('view');surface.tabIndex=0;surface.focus({preventScroll:true})}
function closeModal(){if(bloomInTick){bloomEmit("closeModal",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;$('modal').classList.remove('show');modalKind='';paused=false;lastFrame=performance.now();bloomFocusWorld();globalThis.BloomSimulation?.runtime?.controls()}
function sheetHead(title){return`<div class="sheetHead"><div><div class="eyebrow">BLOOM · LIVING FRONTIER</div><h2>${title}</h2></div><button class="close" data-action="close" aria-label="닫기">×</button></div>`}
function showIntro(hasSave){openModal('intro',`<div class="eyebrow">A LIVING WORLD. YOUR GROWING ARMY.</div><h1>BLOOM</h1><p style="font-size:15px;color:#dce9c3;margin:0">군락의 행군</p><div class="introArt"><canvas id="introCanvas" width="540" height="160"></canvas></div><p>작은 모체 하나에서 시작해, 천 인구의 생명 군단으로.<br>이동으로 전선을 이끌고, 부화 카드를 골라 군락을 키우세요.</p><div class="introList"><div><b>01 · 이끈다</b>클릭·탭 / WASD<br>공격은 부대가 자동으로</div><div><b>02 · 키운다</b>6개의 생산 카드<br>자원과 인구를 투자</div><div><b>03 · 뻗는다</b>6개의 연결 구역<br>우두머리와 새 생장점</div></div><button class="primary" data-action="start">${hasSave?'군락 이어하기':'첫 군락 깨우기'} →</button><p class="fine">자동 저장 · 단일 파일 · 네트워크 연결 불필요<br>Rally Frontier의 원본 생물 외형과 공격 규칙을 바탕으로 만든 새로운 싱글플레이 게임.</p>`);let c=$('introCanvas').getContext('2d');drawNest(c,270,95,3,1);['swordsman','tank','archer','medic','flowerbee','shelltitan'].forEach((type,i)=>{let x=75+i*77,y=85+Math.sin(i)*27;if(window.RallyArt)RallyArt.draw(c,type,'friendly',x,y,unitDef(type).size*1.1,0,0,{})})}
function upgradeDescription(kind){if(kind==='attack')return`모든 부대 공격력 +${Math.round(CONFIG.economy.attackPerLevel*100)}%`;if(kind==='health')return`부대 체력 +${Math.round(CONFIG.economy.healthPerLevel*100)}% · 모체 체력 +${CONFIG.mother.hpPerLevel}`;if(kind==='bounty')return`교전 보상 +${Math.round(CONFIG.economy.bountyPerLevel*100)}%`;if(kind==='production')return`부화 리듬 강화 · 속도 보너스 최대 +${Math.round(CONFIG.production.speedMaxBonus*100)}%`;return CONFIG.upgrades[kind].description}
function showMap(){openModal('map',sheetHead('연결된 여섯 군락')+CONFIG.zones.map((z,i)=>`<div class="zoneRow"><div class="badge">${state.bosses[i]?'✓':i+1}</div><div style="flex:1"><b>${z.name}</b> ${i>state.maxZone?'· 미개척':''}<small>${z.species.map(t=>unitDef(t).name).join(' · ')}</small><small>${state.bosses[i]?'정복 완료':z.bossName+' 격파로 전진'} · 인구 ${CONFIG.progression.caps[CONFIG.progression.capTierByZone[i]]}</small></div></div>`).join('')+`<div class="notice">${CONFIG.zones[state.zone].tip}<br>적은 구역 고유의 힘을 유지합니다. 성장한 군단으로 지난 구역을 다시 압도할 수 있어요.</div>`)}
function exportSave(){const data=JSON.stringify({...state,units:state.units.filter(u=>u.hp>0)},null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=CONFIG.saveExportName;a.click();setTimeout(()=>URL.revokeObjectURL(url),CONFIG.render.toastTime*1000);toast('진행 백업 파일을 내려받았어요')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>CONFIG.maxSaveBytes){toast('백업 파일이 너무 커요');return}if(load(await file.text())){save();showPause();toast('백업한 군락을 불러왔어요')}else toast(bloomDiskFailure?.message||'유효한 Bloom 진행 파일이 아니에요')};input.click()}
function showPause(){openModal('pause',sheetHead('잠시 쉬어 가기')+`<p>군락은 이 자리에서 기다립니다.<br>원하는 곳을 클릭/탭하면 이동하고, 두 번 누르면 그쪽으로 굴러요. WASD / 방향키도 사용할 수 있어요.<br>빨간 예고를 보고 옆으로 피하세요.<br>약한 적을 향해 접근하면 모아가 영입할 기회를 잡습니다.<br>적에게서 멀어지면 병력을 회수합니다.</p><button class="primary" data-action="close">계속 행군하기</button><button class="primary" style="background:#ffffff10;color:var(--ink)" data-action="save">진행 저장</button><div class="tabs"><button class="tab" data-action="collection">친구 도감</button><button class="tab" data-action="export">진행 백업 ↓</button><button class="tab" data-action="import">백업 불러오기 ↑</button></div><button class="primary danger" style="background:#ffffff08" data-action="reset-confirm">새 군락 시작</button><p class="fine credit">원본 생물과 전투 데이터: <a href="https://github.com/byh-playground/rally-frontier/tree/f9d4c28289d7b452a51b70d818fcb657eb4f4d47" target="_blank" rel="noopener">Rally Frontier · f9d4c28</a></p>`)}
function showDefeat(){if(bloomInTick){bloomEmit("showDefeat",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;openModal('defeat',`<div class="eyebrow">A NEW SHOOT WILL RISE</div><h2>다시 뿌리내릴 시간</h2><p>모체가 쓰러져 출정 부대를 잃었습니다.<br>해금 · 연구 · 자원 · 정복한 구역은 그대로 남습니다.</p><div class="notice">생장 둥지에서 무료 칼잎 전사 ${CONFIG.mother.starterCount}마리와 다시 시작합니다. 첫 카드는 무료 기본병으로 돌아가요.<br>유료 병종은 자원을 지불해 새로 생산해야 합니다.</div><button class="primary" data-action="recover">생장 둥지에서 다시 시작 →</button>`)}
function showVictory(){if(bloomInTick){bloomEmit("showVictory",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;if(!playing)return;openModal('victory',`<div class="eyebrow">THE FRONTIER IS IN BLOOM</div><h2>군락이 하나로 이어졌어요</h2><p>여섯 생장점이 뿌리를 맞대고, 중심 군락이 깨어났습니다.<br>작은 모체가 시작한 행군은 이제 하나의 생태계가 되었어요.</p><div class="notice">정복 6 / 6 · 현재 인구 ${pop()} / ${cap()}<br>태어난 병력 ${state.stats.produced} · 전투 손실 ${state.stats.losses}<br>최종 인구 한도 1,000까지 성장하고 조합을 더 시험할 수 있습니다.</div><button class="primary" data-action="close">군락 계속 돌보기 →</button>`)}
function resetKnob(){$('knob').style.transform='translate(0px,0px)'}
function bindUI(){GameUI.listen(document,'click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='collection')showCards();if(a==='close')closeModal();if(a==='start'){playing=true;document.body.classList.remove('intro');WorldView.dead()?showDefeat():closeModal();toast(CONFIG.zones[state.zone].tip)}if(a==='save'){save();toast('이 기기에 진행을 저장했어요')}if(a==='export')exportSave();if(a==='import')importSave();if(a==='reset-confirm')openModal('reset',sheetHead('새 군락을 시작할까요?')+'<p>저장된 광물 · 도감 · 모아 성장 · 성장 카드 · 구역 진행이 초기화됩니다.</p><button class="primary danger" data-action="reset">진행 초기화</button><button class="primary" style="background:#ffffff10;color:var(--ink)" data-action="pause">취소</button>');if(a==='pause')showPause();if(a==='reset'){reset();save();closeModal();toast('새 군락이 발아했어요')}});GameUI.handler($('evolveButton'),'onclick',()=>showUpgrades());GameUI.handler($('mapButton'),'onclick',showMap);GameUI.handler($('pause'),'onclick',showPause);
 GameUI.listen(window,'blur',()=>{keys.clear();stick.x=stick.y=0;resetKnob();if(playing&&!paused)showPause();save()});GameUI.listen(document,'visibilitychange',()=>{if(document.hidden){keys.clear();stick.x=stick.y=0;resetKnob();if(playing&&!paused)showPause();save()}});GameUI.listen(window,'pagehide',save);

}
function frame(time){if(!GameUI.active||globalThis.BloomDiagnostics?.fatal)return;try{const elapsed=Math.max(0,(time-lastFrame)/1000||0);lastFrame=time;advanceSimulationClock(elapsed);render(playing&&!paused&&!WorldView.dead()?Math.min(1,accumulator/CONFIG.sim.fixedStep):1,Math.min(elapsed,.1));if(uiClock>=CONFIG.render.uiInterval)refreshUI();if(toastClock>0){toastClock-=Math.min(elapsed,.1);if(toastClock<=0)$('status').style.opacity='0'}if(!globalThis.BloomDiagnostics?.fatal)GameUI.requestFrame()}catch(error){globalThis.BloomDiagnostics?.report(error,{kind:'render.frame',fatal:true})}}
function initializeGameSurface(){if(window.RALLY_ART_CONFIG)CONFIG.art=window.RALLY_ART_CONFIG;reset();let hasSave=false;try{const raw=localStorage.getItem(CONFIG.saveKey);if(raw)hasSave=load(raw)}catch{}bindUI();refreshUI();showIntro(hasSave);window.__army={CONFIG,get state(){return state},get grid(){return grid},get effects(){return effects},get projectiles(){return projectiles},get events(){return events},get paused(){return paused},get playing(){return playing},get input(){return{x:stick.x,y:stick.y,keys:[...keys]}},get performance(){return frameStats},spawn,snapshot,load,save,reset,setCard,buy,purchaseCost,pop,cap,enterZone,recover,defeat,rebuildGrid,findTarget,canTarget,detected,attack,attackPower,damage,area,produce,productionTime,productionSpeed,support,render,refreshUI,showUpgrades,showCards,closeModal,unlockZone,spawnCamp,unitDef,clearEffects(){effects=[];projectiles=[];events=[]},setPaused(v){paused=!!v},setPlaying(v){playing=!!v},get entityCount(){return state.units.length}};GameUI.requestFrame()}


function drawProjectedProjectile(source){const p=presentationPose(source,'projectile');const d=unitDef(p.type)||{};if(p.abilityShot){drawAbilitySeed(p);return}if(p.moaSeed){projectionBillboard(ctx,p.x,p.y,p.z||0);const a=WorldProjection.angle(Math.atan2(p.aimY-p.y,p.aimX-p.x));ellipse(ctx,p.x,p.y,8,4,a,'#d6ff96');ellipse(ctx,p.x-Math.cos(a)*7,p.y-Math.sin(a)*7,5,2,a,'#96dbad88');ellipse(ctx,p.x+Math.cos(a)*2,p.y+Math.sin(a)*2,3,2,a,'#fff8d0');ctx.restore();return}projectionBillboard(ctx,p.x,p.y,p.z||0);ellipse(ctx,p.x,p.y,CONFIG.render.projectileRadius*(p.splash?1.6:1),CONFIG.render.projectileRadius,WorldProjection.angle(Math.atan2(p.aimY-p.y,p.aimX-p.x)),p.team==='friendly'?'#e6f4b0':'#ffc391');ctx.restore()}

;

