canTarget=function(u,t){if(!core.canTarget(u,t)||UnitMovement.isReturning(u)||(t.movement?.homePhase==='return')||lockedParcelAt(t.x,t.y)!==-1)return false;if(u.team==='enemy'&&u.camp>=0){const c=state.camps[u.camp];if(c&&sqdist(t,c)>(u.target?CONFIG.campaign.hunting.leashRadius:CONFIG.campaign.hunting.aggroRadius)**2)return false}return true};
