effectiveRange=function(u){return unitDef(u.type).range+researchEffect(u,'range')};effectiveSpeed=function(u){return unitDef(u.type).speed*(1+researchEffect(u,'speed'))*((u.movement?.homePhase==='return')?CONFIG.campaign.hunting.returnSpeed:1)};
