function addBank(seconds){const c=state.campaign;for(const [key,res]of [['mineral','minerals'],['gas','gas']]){const d=CONFIG.campaign.investments[key],l=c.investments[key],gain=Math.max(0,Math.min(d.capacity*l-c.bank[res],d.rate*l*seconds));c.bank[res]+=gain;c.lifetimeBank[res]+=gain}}
