function researchTotal(){return Object.values(state.campaign.research).reduce((n,r)=>n+r.rank,0)}
function investmentTotal(){return Object.values(state.campaign.investments).reduce((n,r)=>n+r,0)}
function researchCost(type,branch){const r=researchFor(type),choice=CONFIG.campaign.research.choices[type]?.find(c=>c.id===branch);if(!choice||!unlocked(type)||r.branch&&r.branch!==branch||r.rank>=researchLimit())return null;const step=CONFIG.campaign.research.costStep,m=CONFIG.campaign.research.rankGrowth**r.rank;return[Math.ceil(choice.mineral*m/step)*step,Math.ceil(choice.gas*m/CONFIG.campaign.research.gasStep)*CONFIG.campaign.research.gasStep]}
function spend(cost){if(!cost||state.minerals<cost[0]||state.gas<cost[1])return false;state.minerals-=cost[0];state.gas-=cost[1];state.stats.spentM+=cost[0];state.stats.spentG+=cost[1];state.campaign.ledger.investmentM+=cost[0];state.campaign.ledger.investmentG+=cost[1];return true}
function buyResearch(type,branch){const cost=researchCost(type,branch);if(!spend(cost))return false;const r=researchFor(type),choice=CONFIG.campaign.research.choices[type].find(c=>c.id===branch),old=r.rank;r.branch=branch;r.rank++;if(choice.effect==='health')for(const u of state.units)if(u.team==='friendly'&&u.type===type){const ratio=u.hp/u.maxHp;u.maxHp*=(1+choice.perRank*r.rank)/(1+choice.perRank*old);u.hp=u.maxHp*ratio}save();refreshUI();return true}
function investmentCost(kind){const d=CONFIG.campaign.investments[kind],l=state.campaign.investments[kind],step=CONFIG.economy.costStep;return!d||l>=investmentLimit()?null:[Math.ceil(d.baseM*d.growth**l/step)*step,Math.ceil(d.baseG*d.growth**l/CONFIG.campaign.research.gasStep)*CONFIG.campaign.research.gasStep]}
function buyInvestment(kind){if(!spend(investmentCost(kind)))return false;state.campaign.investments[kind]++;save();refreshUI();return true}
function objectiveStatus(){const g=CONFIG.campaign.grounds[nearestGround()],l=state.campaign.ledger;return`${dist(state.mother,basePoint())<CONFIG.world.baseRadius?'둥지 · 회복과 충원':g.name+' · 위험 '+g.danger} | 사냥−충원 ◆ ${signed(l.rewardM-l.productionM)} ◈ ${signed(l.rewardG-l.productionG)}`}
function signed(n){return(n>=0?'+':'−')+fmt(Math.abs(n))}
function costText(c){return c?`◆ ${fmt(c[0])}${c[1]?'<br>◈ '+fmt(c[1]):''}`:'최대 단계'}
function affordable(c){return c&&state.minerals>=c[0]&&state.gas>=c[1]}
function ledgerHTML(){const l=state.campaign.ledger;return`<div class="notice">이번 기록의 사냥 수입 ◆ ${fmt(l.rewardM)} · ◈ ${fmt(l.rewardG)}<br>실제 병력 생산비 ◆ ${fmt(l.productionM)} · ◈ ${fmt(l.productionG)}<br>사냥−충원 ◆ ${signed(l.rewardM-l.productionM)} · ◈ ${signed(l.rewardG-l.productionG)}<br>성장 투자 ◆ ${fmt(l.investmentM)} · ◈ ${fmt(l.investmentG)}<br>전투 손실 ${l.losses}마리 · 잃은 유료 병력 가치 ◆ ${fmt(l.lostM)} · ◈ ${fmt(l.lostG)}<br><small>충원에는 새 부대 편성도 포함됩니다. 손실 가치는 충원비와 중복 차감하지 않습니다. 비축 수입은 별도입니다.</small></div>`}
showMap=function(){openModal('map',sheetHead('한 월드, 뻗어 가는 사냥터')+`<p>위험도는 권장치입니다. 관문에 직접 도착해 자원을 투자하면 구획이 연결됩니다. 이끼밭에서 두 갈래를 자유롭게 선택할 수 있습니다.<br>쓰러진 일반 적은 ${CONFIG.campaign.grounds[0].respawn}–${CONFIG.campaign.grounds.at(-1).respawn}초 뒤 빈자리에서 다시 자랍니다. 모체와 병력에 겹치지 않습니다. 군락장은 별도 재생 시간을 가집니다.</p>`+CONFIG.campaign.grounds.map((g,i)=>{const camps=state.camps.filter(c=>c.ground===i),s=WorldView.data().campaign.groundStats[i],count=g.camps.reduce((n,c)=>n+c.units.reduce((m,u)=>m+u.count,0),0);return`<div class="zoneRow"><div class="badge" style="color:${g.color}">${i+1}</div><div style="flex:1"><b>${g.name} · ${WorldView.data().campaign.parcels[i]?g.danger:'아직 연결되지 않음'}</b><small>${g.habitat} · 권장 ${g.recommended} 인구 + 성장</small><small>${g.description}</small><small>일반 적당 ◆ ${g.rewardM} · ◈ ${g.rewardG} / 개체별 ${g.respawn}초 재생</small><small>적 ${camps.reduce((n,c)=>n+c.remaining,0)} / ${count} · 누적 정리 ${s.clears}회 · 잃은 병력 ${s.losses}마리</small><small>누적 수입 ◆ ${fmt(s.rewardM)} · ◈ ${fmt(s.rewardG)} / 손실 가치 ◆ ${fmt(s.lostM)} · ◈ ${fmt(s.lostG)}</small>${WorldView.data().campaign.parcels[i]?'':`<small>관문에 직접 도착해 연결하세요.</small><small>${parcelRequirement(i)}</small>`}</div></div>`}).join('')+ledgerHTML()+`<div class="notice">${CONFIG.campaign.messages.future}<br>가시 지대 · 뿌리 방벽 · 개화 고지 · 그늘 군락 · 중심 군락은 아직 열리지 않습니다. 장기 전체 인구 1,000은 향후 확장 설정입니다.</div>`)};
showIntro=function(hasSave){openModal('intro',`<div class="eyebrow">BLOOM · LIVING HUNTING GROUNDS</div><h1>BLOOM</h1><p style="font-size:15px;color:#dce9c3;margin:0">군락 외곽 · 반복 전투와 성장</p><div class="introArt"><canvas id="introCanvas" width="540" height="160"></canvas></div><p>감당할 수 있는 무리를 사냥하고, 손실을 채우고,<br>남은 광물과 가스로 군락을 키우세요.<br>강해진 뒤 같은 사냥터를 더 편하게 돌아볼 수 있습니다.</p><div class="introList"><div><b>이끈다</b>클릭·탭 / WASD<br>주변 부대 자동 전투</div><div><b>되돌아온다</b>한 월드 · 분기 구획<br>기존 사냥터 반복 재생</div><div><b>키운다</b>네 병종 생산 · 연구<br>첫 구역 60 인구</div></div><button class="primary" data-action="start">${hasSave?'군락 이어하기':'이끼밭 사냥 시작'} →</button><p class="fine">무료 칼잎 전사로 시작 · 광물 25로 씨앗궁수 생산 해금<br>자동 저장 · 백업 가능 · 오프라인 단일 파일<br>${CONFIG.campaign.messages.future}</p>`);const c=$('introCanvas').getContext('2d');drawNest(c,270,90,3,1);friendlyTypes.forEach((t,i)=>RallyArt.draw(c,t,'friendly',100+i*110,95+(i%2?20:-20),unitDef(t).size*1.5,0,0,{}))};
showVictory=function(){if(bloomInTick){bloomEmit("showVictory",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;toast('사냥터는 계속 재생됩니다. 더 강한 군락을 키워 보세요.')};
showDefeat=function(){if(bloomInTick){bloomEmit("showDefeat",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;openModal('defeat',`<div class="eyebrow">A NEW SHOOT WILL RISE</div><h2>다시 뿌리내릴 시간</h2><p>모체가 쓰러져 출정 부대를 잃었습니다.<br>자원 · 카드 · 연구 · 둥지 투자는 남습니다.</p><div class="notice">둥지에서 무료 칼잎 전사 ${CONFIG.mother.starterCount}마리와 다시 시작합니다. 첫 카드는 무료 기본병으로 돌아갑니다. 이끼밭에서 충원 자금을 다시 모으세요.<br>유료 병종은 시간과 자원을 들여 새로 생산합니다.</div><button class="primary" data-action="recover">둥지에서 재출발 →</button>`)};
function drawCampaignWorld(){const C=CONFIG.campaign;ctx.textAlign='center';for(let i=0;i<C.grounds.length;i++){const g=C.grounds[i];if(g.x+g.rx<view.x-view.w/2||g.x-g.rx>view.x+view.w/2)continue;const open=state.campaign.parcels[i];ctx.fillStyle=open?g.color+'14':'#23382dee';ctx.strokeStyle=open?g.color+'65':'#a9b99caa';ctx.lineWidth=open?2:8;ctx.beginPath();ctx.ellipse(g.x,g.y,g.rx,g.ry,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.font='bold 17px system-ui';ctx.fillStyle=g.color;ctx.fillText(`${i+1} · ${g.name}`,g.x,g.y-g.ry+28);ctx.font='11px system-ui';ctx.fillStyle='#f1f5d3';ctx.fillText(open?`${g.danger} · 권장 ${g.recommended} 인구 · 적당 ◆${g.rewardM} ◈${g.rewardG}`:'잠든 구획 · 지도에서 뿌리를 연결하세요',g.x,g.y-g.ry+48)}for(const c of state.camps){if(!c.enabled)continue;if(Math.abs(c.x-view.x)>view.w/2+200||Math.abs(c.y-view.y)>view.h/2+200)continue;if(c.remaining===0){drawNest(ctx,c.x,c.y,0,.5);ctx.font='12px system-ui';ctx.fillStyle='#eff5d3';ctx.fillText(c.respawn>0?`무리 재생 ${Math.ceil(c.respawn)}초`:'빈자리에서 새 무리 재생',c.x,c.y+48)}else{ctx.font='10px system-ui';ctx.fillStyle='#ffdfb9';ctx.fillText(`${c.remaining}마리 · 사냥 무리`,c.x,c.y+CONFIG.campaign.hunting.labelOffset)}}const b=basePoint();ctx.strokeStyle='#eff5c644';ctx.beginPath();ctx.arc(b.x,b.y,CONFIG.campaign.base.healRadius,0,Math.PI*2);ctx.stroke();drawNest(ctx,b.x,b.y,Math.min(4,1+investmentTotal()),1.2);ctx.font='bold 13px system-ui';ctx.fillStyle='#f1f6d3';ctx.fillText('생장 둥지 · 회복 / 비축 수령',b.x,b.y-80)}
drawMini=function(){return bloomWithPresentation(()=>{const C=CONFIG.campaign,world=bloomRenderWorld(),leader=bloomRenderUnit(world.local.leaderId);mini.clearRect(0,0,180,104);mini.fillStyle='#223d30aa';mini.fillRect(0,0,180,104);const sx=180/C.width,sy=104/C.height;C.grounds.forEach((g,i)=>{mini.fillStyle=world.campaign.parcels[i]?g.color+'55':'#152820';mini.beginPath();mini.ellipse(g.x*sx,g.y*sy,g.rx*sx,g.ry*sy,0,0,Math.PI*2);mini.fill();mini.fillStyle=g.color;mini.font='9px system-ui';mini.fillText(world.campaign.parcels[i]?i+1:'×',g.x*sx-3,g.y*sy+3)});mini.fillStyle='#d9f3ad';mini.fillRect(C.base.x*sx-3,C.base.y*sy-3,6,6);if(!leader)return;mini.fillStyle='#fffbe0';mini.beginPath();mini.arc(leader.x*sx,leader.y*sy,3,0,Math.PI*2);mini.fill()})};
save=function(){if(bloomInTick||bloomInitializing){bloomPersistenceRequested=true;return true;}if(state.campaign)state.campaign.savedAt=Date.now();return core.save()};



function initializeCampaignUI(){Object.assign(window.__army,{researchCost,researchLimit,investmentLimit,buyResearch,researchFor,researchTotal,investmentCost,buyInvestment,investmentTotal,addBank,collectBank,effectiveRange,effectiveSpeed,hasUnitAbility,nurseryRate,worldLimit,updateCampaign,nearestGround,objectiveStatus,unlockSpecies,unlockCost,parcelCost,lockedParcelAt,parcelRequirement,getCampaignDefs:()=>campaignDefs});/* Parcel payment is available only at the physical world gate. */};

function unlockCost(type){const d=CONFIG.campaign.unlocks[type];return !d||unlocked(type)||state.campaign.investments.nursery<d.nursery?null:[d.minerals,d.gas]}
function unlockSpecies(type){if(!spend(unlockCost(type)))return false;state.unlocked.push(type);save();refreshUI();toast(unitDef(type).name+' 생산 해금 · 병력은 시간과 비용을 들여 부화합니다');return true}

function parcelRequirement(i){const p=CONFIG.campaign.parcels[i];return p.from.length?'연결 조건: '+p.from.map(n=>CONFIG.campaign.grounds[n].name).join(' 또는 ')+' · 자원 투자만 필요':'첫 구획'}
function parcelCost(i){if(!Number.isInteger(i)||i<0||i>=CONFIG.campaign.parcels.length||state.campaign.parcels[i])return null;const p=CONFIG.campaign.parcels[i];return p.from.some(n=>state.campaign.parcels[n])?p.cost:null}
function lockedParcelAt(x,y,parcels=state?.campaign?.parcels){if(!parcels)return -1;for(let i=1;i<CONFIG.campaign.grounds.length;i++){if(parcels[i])continue;const g=CONFIG.campaign.grounds[i];if(((x-g.x)/g.rx)**2+((y-g.y)/g.ry)**2<1)return i}return -1}
function keepOutsideLocked(u){const i=lockedParcelAt(u.x,u.y);if(i<0)return;const g=CONFIG.campaign.grounds[i],dx=(u.x-g.x)/g.rx,dy=(u.y-g.y)/g.ry,a=Math.atan2(dy,dx);u.x=g.x+Math.cos(a)*(g.rx+CONFIG.campaign.hunting.boundaryPadding);u.y=g.y+Math.sin(a)*(g.ry+CONFIG.campaign.hunting.boundaryPadding);u.target=0}

;

(function(root){'use strict';
 function create(options={}){
  const api=new BloomGamekitCamera.OrthographicProjection({degrees:40,...options});
  api.project=function(x,y,z=0){return this.projectInto(x,y,z,{})};
  api.ground=function(x,y){return this.groundInto(x,y,{})};
  api.intent=function(x,y){return this.intentInto(x,y,{})};
  api.groundHeight=function(){return 0};
  api.pose=function(x,y,z=0){const groundZ=this.groundHeight(x,y);return{ground:this.project(x,y,groundZ),body:this.project(x,y,groundZ+z),depth:this.depth(y,groundZ+z)}};
  return api;
 }
 root.OrthographicPitch={create};root.WorldProjection=create();
})(globalThis);
const bloomCamera=new BloomGamekitCamera.CameraViewport({projection:WorldProjection});
function bloomSyncCamera(){
 bloomCamera.setViewport({width:Math.max(1,view.w*view.zoom),height:Math.max(1,view.h*view.zoom*WorldProjection.K),dpr:Math.min(CONFIG.render.dprMax,globalThis.devicePixelRatio||1)});
 bloomCamera.setCamera({x:view.x,y:view.y*WorldProjection.K,zoom:view.zoom});
 bloomCamera.setShake(hitfeel.offset.x,hitfeel.offset.y);return bloomCamera;
}

;

'use strict';
/** Drawing-only anchor contract. Live actor inputs are sampled centrally; sampled poses are accepted too.
 * BODY: absolute XYZ + the same melee/bob origin as the sprite, projected once.
 * GROUND: XY footprint sampled against terrain at every path vertex.
 * SCREEN: HUD/minimap/damage collision layout remain in their own pixel space.
 * Paths are allocation-free and bounded to 96 segments (20 world-unit spacing).
 */
function indicatorPoint(x,y,z){return{x,y:y-z*WorldProjection.H/WorldProjection.K}}
function indicatorGroundPoint(x,y){return indicatorPoint(x,y,spatialGround(x,y))}
function indicatorGroundVertex(c,x,y,first=false){const sy=y-spatialGround(x,y)*WorldProjection.H/WorldProjection.K;if(first)c.moveTo(x,sy);else c.lineTo(x,sy)}
function indicatorGroundLine(c,x0,y0,x1,y1,first=false){const n=Math.min(96,Math.max(1,Math.ceil(Math.hypot(x1-x0,y1-y0)/20)));indicatorGroundVertex(c,x0,y0,first);for(let i=1;i<=n;i++)indicatorGroundVertex(c,x0+(x1-x0)*i/n,y0+(y1-y0)*i/n)}
function indicatorGroundArc(c,x,y,rx,ry=rx,a0=0,a1=Math.PI*2,begin=true,close=true){const span=a1-a0,n=Math.min(96,Math.max(Math.ceil(24*Math.abs(span)/(Math.PI*2)),8,Math.ceil(Math.abs(span)*Math.max(rx,ry)/20)));if(begin)c.beginPath();for(let i=0;i<=n;i++){const a=a0+span*i/n;indicatorGroundVertex(c,x+Math.cos(a)*rx,y+Math.sin(a)*ry,i===0&&begin)}if(close)c.closePath()}
function indicatorBodyLabel(p,text,r,offset=17){WorldUI.draw('label',p,{text,extent:r,gap:offset})}
function indicatorDeathPose(d,f=deathSample(d)){if(d.moa)return{x:d.pose.x,y:d.pose.y,z:d.pose.z};const x=d.pose.x+d.dx*f.shift,y=d.pose.y+d.dy*f.shift+f.drop;return{x,y,z:spatialGround(x,y)+d.airLift*(1-f.age/CONFIG.render.death.life)}}

/** Declarative world UI. Call draw(type, sampledSource, props), or register a new
 * type with define(type,{anchor,paint}). Anchor is body/head/ground/point, never a
 * hand-written height subtraction. XYZ is absolute; UI offsets live in billboard
 * units (offsetX/Y) or screen pixels (pixelX/Y). Fixed DOM HUD is not in this layer.
 */
const WorldUI=(()=>{
 const types=new Map();
 function anchor(source,spec={}){
  if(!source)throw new TypeError('WorldUI requires a captured model or explicit point');
  const at=spec.at||'body',p=at==='ground'?{x:source.x,y:source.y,z:spatialGround(source.x,source.y)}:
   at==='point'||!source.type?{x:source.x,y:source.y,z:source.z??spatialGround(source.x,source.y)}:projectionBodyPose(source);
  const extent=at==='head'?(spec.extent??(source.type==='mother'?(source.size||30):source.type?unitVisualExtent(source):0)):0;
  return{x:p.x,y:p.y,z:p.z,offsetX:spec.offsetX||0,
   offsetY:(spec.offsetY||0)-(at==='head'?extent+(spec.gap||0):0),pixelX:spec.pixelX||0,pixelY:spec.pixelY||0};
 }
 function screen(source,spec){const a=anchor(source,spec),p=BloomGamekitHud.resolveAnchorInto(bloomSyncCamera(),{space:'world',x:a.x,y:a.y,z:a.z,offsetX:a.offsetX*view.zoom+a.pixelX,offsetY:a.offsetY*view.zoom+a.pixelY},{});p.depth=WorldProjection.depth(a.y,a.z);return p}
 function begin(c,source,spec){const a=anchor(source,spec),z=Math.max(.0001,view.zoom);projectionBillboard(c,a.x,a.y,a.z);c.translate(a.offsetX+a.pixelX/z,a.offsetY+a.pixelY/z);return a}
 function define(name,definition){if(!definition||typeof definition.paint!=='function')throw TypeError('WorldUI definition needs paint');types.set(name,definition)}
 function draw(name,source,props={}){const d=types.get(name);if(!d)throw TypeError('Unknown world UI: '+name);const spec=typeof d.anchor==='function'?d.anchor(source,props):d.anchor,a=begin(ctx,source,spec);try{d.paint(ctx,a,source,props)}finally{ctx.restore()}}
 const ground={point:indicatorGroundPoint,vertex:indicatorGroundVertex,line:indicatorGroundLine,
  ellipse:indicatorGroundArc,circle(c,source,r){indicatorGroundArc(c,source.x,source.y,r)}};
 return{anchor,screen,begin,define,draw,ground,types:()=>[...types.keys()]};
})();
WorldUI.define('label',{anchor:(s,d)=>({at:d.at||'head',extent:d.extent,gap:d.gap??17,offsetX:d.offsetX,offsetY:d.offsetY,pixelX:d.pixelX,pixelY:d.pixelY}),paint(c,a,s,d){if(d.font)c.font=d.font;if(d.color)c.fillStyle=d.color;c.textAlign=d.align||'center';c.fillText(d.text,a.x,a.y)}});
WorldUI.define('health',{anchor:(s,d)=>({at:'head',extent:d.extent,gap:9}),paint(c,a,s,d){const source=d.source||s;if(source.team==='enemy'){drawJuicedHealthBar(source,a,d.width);return}c.fillStyle='#203325';c.fillRect(a.x-d.width/2,a.y,d.width,CONFIG.render.healthBarHeight);c.fillStyle=source.team==='friendly'?'#bddbf3':'#edbe8b';c.fillRect(a.x-d.width/2,a.y,d.width*Math.max(0,source.hp/source.maxHp),CONFIG.render.healthBarHeight)}});
WorldUI.define('shield',{anchor:{at:'body'},paint(c,a,s,d){c.strokeStyle='#c0ecf2a0';c.lineWidth=1.5;c.beginPath();c.arc(a.x,a.y,d.radius+3,0,Math.PI*2);c.stroke()}});
WorldUI.define('permanent',{anchor:(s,d)=>({at:d.remaining===null?'body':'ground',offsetY:d.extent,pixelY:15}),paint(c,a,s,d){const z=Math.max(.0001,view.zoom),label=`영구 +${d.rank}`+(d.remaining===null?'':` · ${Math.ceil(d.remaining)}초`);c.font=`bold ${11/z}px system-ui`;c.textAlign='center';const w=c.measureText(label).width;c.fillStyle='#123d32ed';c.fillRect(a.x-w/2-4/z,a.y-11/z,w+8/z,15/z);c.fillStyle=CONFIG.permanent.color;c.fillText(label,a.x,a.y)}});
WorldUI.define('deathHealth',{anchor:(s,d)=>({at:'head',extent:d.death.r,gap:9}),paint(c,a,s,d){const record=d.death,f=d.sample,b=record.bar,q=1-healthEase(f.age/CONFIG.render.death.barLife);c.globalAlpha=Math.min(f.alpha,f.barAlpha);const x=a.x-record.width/2;c.fillStyle='#15291feb';c.fillRect(x-1,a.y-1,record.width+2,CONFIG.render.healthJuice.worldHeight+2);c.fillStyle=CONFIG.render.healthJuice.ghost;c.fillRect(x,a.y,record.width*b.ghost*q,CONFIG.render.healthJuice.worldHeight);c.fillStyle=CONFIG.render.healthJuice.red;c.fillRect(x,a.y,record.width*b.fill*q,CONFIG.render.healthJuice.worldHeight)}});
// Compatibility name for the drawing geometry; all world UI resolves in WorldUI.
const WorldIndicators={body:(p)=>WorldUI.anchor(p,{at:'body'}),ground:indicatorGroundPoint,point:indicatorPoint,groundLine:indicatorGroundLine,groundArc:indicatorGroundArc,death:indicatorDeathPose};
function publishWorldIndicators(){Object.assign(window.__army,{WorldUI,WorldIndicators})};

