'use strict';
// Narrow prototype: movement-controlled Moa + four-species conversion collection.
CONFIG.moa={rangedReach:235,rangedWindup:.18,seedSpeed:410,seedRadius:5,attack:28,cooldown:.72,windup:.11,contactSlack:13,reach:18,queryRadius:105,cancelDot:-.45,growthCost:150,growthHp:180,growthAttack:8,growthSize:1.32,conversionGlow:.65,gasExchange:1};
CONFIG.control={inputThreshold:.35,frontDot:Math.cos(50*Math.PI/180),reserveReach:24,reserveCooldown:.2,reserveDuration:.4,reserveRearm:.72,rangedWindup:.4,meleeWindup:.35,meleeSlack:3,shotRadius:3,returnJoinRadius:80};
CONFIG.motion.retreatIntentTime=.15;

const moaPrevious={buy,purchaseCost,killReward,save};

CONFIG.mother.starterCount=0;CONFIG.production.slotZones=[0,0,0,0];CONFIG.production.defaultCards=[...friendlyTypes];
for(const c of CONFIG.campaign.parcels)c.cost=[c.cost[0]+c.cost[1],0];
CONFIG.campaign.population.costs=CONFIG.campaign.population.costs.map((m,i)=>m+CONFIG.campaign.population.gas[i]);CONFIG.campaign.population.gas.fill(0);
for(const d of Object.values(CONFIG.upgrades)){d.baseM+=d.baseG;d.baseG=0}
for(const choices of Object.values(CONFIG.campaign.research.choices))for(const d of choices){d.mineral+=d.gas;d.gas=0}
CONFIG.zones[0].tip='모아를 적 가까이 움직여 보세요. 직접 쓰러뜨리면 선택한 병종이 친구가 됩니다.';
CONFIG.campaign.grounds[0].description='모아 혼자서도 다시 시작할 수 있는 이끼밭. 가까이 다가가 칼잎 친구를 모으세요.';
CONFIG.campaign.grounds[1].description='빠른 민들레와 씨앗궁수를 만날 수 있습니다. 모아가 마지막 일격을 주면 새 친구가 됩니다.';
CONFIG.campaign.grounds[3].description='집중 사격이 위험합니다. 병력을 잃으면 다시 모아야 하니 무리하지 마세요.';
for(const g of CONFIG.campaign.grounds){g.rewardM+=g.rewardG;g.rewardG=0}
function initializeMoa(){const m=state.mother;m.growthStage=state.campaign.moaGrowth;m.size=CONFIG.mother.size*(m.growthStage?CONFIG.moa.growthSize:1);moaSyncLevelHP(m);MoaActor.hydrate(m).initializePrimaryAttack()}
maxMotherHP=function(){return CONFIG.mother.hp+state.upgrades.health*CONFIG.mother.hpPerLevel+(state.campaign?.moaGrowth||0)*CONFIG.moa.growthHp};

// Compatibility fields are inert, retained only so historical saves remain auditable.
produce=function(){};addBank=function(){};collectBank=function(){};buyInvestment=function(){return false};investmentCost=function(){return null};researchLimit=function(){return CONFIG.campaign.research.maxRank};
purchaseCost=function(kind){if(kind==='moaGrowth')return state.campaign.moaGrowth?null:[CONFIG.moa.growthCost,0];if(kind==='production'||kind==='ability')return null;return moaPrevious.purchaseCost(kind)};
buy=function(kind){if(kind!=='moaGrowth')return moaPrevious.buy(kind);if(!spend(purchaseCost(kind)))return false;state.campaign.moaGrowth=1;state.mother.growthStage=1;state.mother.size=CONFIG.mother.size*CONFIG.moa.growthSize;state.mother.maxHp=maxMotherHP();state.mother.hp=Math.min(state.mother.maxHp,state.mother.hp+CONFIG.moa.growthHp);state.mother.convertGlow=CONFIG.moa.conversionGlow*2;addFx('ring',state.mother.x,state.mother.y,0,0,'#f1efb0',85,.8);save();refreshUI();toast('모아가 자랐어요! 몸집 · 체력과 씨앗탄이 강해졌습니다');return true};
function moaPower(){return moaLevelBasePower()}
function conversionEligible(t){return !!(t&&t.team==='enemy'&&!t.elite&&!t.boss&&t.camp>=0&&state.camps[t.camp]?.enabled&&friendlyTypes.includes(t.type)&&state.cards.some(c=>c.type===t.type)&&pop()+unitDef(t.type).supply<=cap())}
function moaContact(t,extra=0){return t&&t.hp>0&&t.team==='enemy'&&!(t.movement?.homePhase==='return')&&lockedParcelAt(t.x,t.y)===-1&&dist(state.mother,t)<=radius(state.mother)+radius(t)+CONFIG.moa.reach+extra}
function moaWithdrawing(t){const m=state.mother,dx=t.x-m.x,dy=t.y-m.y,l=Math.hypot(dx,dy),speed=Math.hypot(m.moveX||0,m.moveY||0);return speed>=CONFIG.control.inputThreshold&&l>0&&((m.moveX||0)*dx+(m.moveY||0)*dy)/l<CONFIG.moa.cancelDot}
function moaFront(t){const m=state.mother,dx=t.x-m.x,dy=t.y-m.y,l=Math.hypot(dx,dy),speed=Math.hypot(m.moveX||0,m.moveY||0);return speed>=CONFIG.control.inputThreshold&&l>0&&((m.moveX||0)*dx+(m.moveY||0)*dy)/(l*speed)>=CONFIG.control.frontDot}
function moaFinisherTarget(){const m=state.mother;let best=null,score=Infinity;near(m.x,m.y,CONFIG.moa.queryRadius+CONFIG.control.reserveReach,'enemy',t=>{if(!moaContact(t,CONFIG.control.reserveReach)||!moaFront(t)||!conversionEligible(t)||t.hp>damageValue(m,t,moaPower())||t.shield>0&&t.shieldUntil>state.time)return;const d=sqdist(m,t);if(d<score){score=d;best=t}});return best}
function moaMovingInput(){return Math.hypot(state.mother.moveX||0,state.mother.moveY||0)>=CONFIG.input.deadzone}

function moaSeedTarget(t){return !!(t&&t.hp>0&&t.team==='enemy'&&!(t.movement?.homePhase==='return')&&lockedParcelAt(t.x,t.y)===-1&&dist(state.mother,t)<=CONFIG.moa.rangedReach)}
function moaReserved(t){const m=state.mother,p=m.finisher;return !!(p&&p.target===t.id&&p.left>0&&m.hp>0&&!state.dead&&moaContact(t,CONFIG.control.reserveReach)&&!moaWithdrawing(t)&&conversionEligible(t))}

killReward=function(t){return moaPrevious.killReward(t)};




function initializeMoaUI(){Object.assign(window.__army,{moaMovingInput,moaPower,moaContact,moaReserved,moaFront,moaFinisherTarget,damageValue,segmentCircle,attack,updateUnit,motherRetreatsFrom,conversionEligible,die,killReward,maxMotherHP,radius,impact,projectile});};
drawMother=function(source=WorldView.leader()){const m=presentationPose(source);drawMoa(ctx,m,presentationTime());const ready=1-clamp((source.primaryAttack.cooldown.leftSeconds||0)/CONFIG.moa.cooldown,0,1);ctx.strokeStyle='#eff8c17a';ctx.lineWidth=2;ctx.beginPath();indicatorGroundArc(ctx,m.x,m.y,m.size+8,m.size+8,-Math.PI/2,-Math.PI/2+Math.PI*2*ready,true,false);ctx.stroke();const id=source.finisher?.target||source.primaryAttack?.pending?.target,t=id&&bloomRenderUnit(id);if(t?.hp>0){const p=presentationPose(t);ctx.strokeStyle=source.finisher?'#e4ff9e':'#eff8c17a';ctx.lineWidth=source.finisher?2:1;ctx.beginPath();terrainCirclePath(p.x,p.y,radius(p)+7);ctx.stroke();if(source.finisher){ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillStyle='#e4ff9e';indicatorBodyLabel(p,'영입',unitVisualExtent(p))}}};

