'use strict';
// Loaded after campaign.js and moa-system.js. Presentation only; no save mutation.
const moaRoster=['swordsman','archer','shellbug','dandelion'];
const moaUIStyle=(globalThis.BLOOM_HEADLESS ? null : (document.createElement('style')));
if (!globalThis.BLOOM_HEADLESS) { moaUIStyle.textContent=`#gas{display:none}.moaCollection{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.moaCollection .unitCard{cursor:default;text-align:center}.moaCollection .unitCard img{float:none;display:block;margin:0 auto 8px}.moaCollection .unitCard strong{display:block;word-break:keep-all;line-height:1.5}.moaCollection .unseen{opacity:.65}.tabs{flex-wrap:wrap}@media(max-width:370px){.introArt{height:130px;margin:12px 0}.introList{gap:3px}.introList div{padding:7px 4px;font-size:9px}.introList b{font-size:10px}}`; }
if (!globalThis.BLOOM_HEADLESS) { document.head.appendChild(moaUIStyle); }
