costText=function(c){return c?`◆ ${fmt(c[0])}`:'최대 단계'};
affordable=function(c){return !!c&&state.minerals>=c[0]};
function moaCollectionCount(type){return Math.max(0,Number(state.campaign.collection?.[type])||0)}
function moaCollectionHTML(){const total=moaRoster.reduce((n,t)=>n+moaCollectionCount(t),0),known=moaRoster.filter(t=>moaCollectionCount(t)>0).length;return`<p>첫 수집 ${known} / 4종 · 누적 전환 ${fmt(total)}마리</p><div class="moaCollection">${moaRoster.map(t=>{const n=moaCollectionCount(t);return`<div class="unitCard ${n?'':'unseen'}"><img alt="" src="${portrait(t)}"><strong>${unitDef(t).name}</strong><span class="tag">${unitDef(t).supply} 인구</span><p>${n?'첫 수집 완료':'아직 만나지 못함'}</p><small>누적 전환 ${fmt(n)}마리</small></div>`}).join('')}</div><details class="compressionDetails"><summary>수집 기록은 어떻게 쌓이나요?</summary><p>모아의 직접 처치 또는 7초 표식이 남은 적을 내 병력이 처치해 영입한 생물을 기록합니다. 도감 기록은 병력을 잃거나 모아가 쓰러져도 남습니다. 씨앗탄의 직접 처치도 전환됩니다. 다음 공격은 공격 가능한 범위에서 한 방에 마무리할 적을 먼저 노립니다. 이동 중에도 자동으로 발사하며, 이동 방향과 관계없이 범위 안의 적을 노립니다. 이미 발사한 씨앗탄은 그대로 날아갑니다. 막타가 가능한 적을 모아가 실제로 공격하기 시작하면 최대 0.95초 동안 아군이 마지막 1체력을 남겨 줍니다. 실제 타격으로 생긴 7초 표식은 다시 맞히면 갱신됩니다. 표식이 있는 동안 내 병력이 처치해도 영입되며, 표식 적에게는 마지막 1체력 보조를 쓰지 않습니다. 대상별 한 번의 보조이며 빗나가거나 취소되면 끝납니다. 영입 시 적의 기본 체력 · 공격력 50%에 성장 카드가 적용됩니다. 네 병종 모두 언제나 전환할 수 있습니다.</p></details>`}
objectiveStatus=function(){const m=state.mother,g=CONFIG.campaign.grounds[nearestGround()],home=dist(m,basePoint())<CONFIG.campaign.base.healRadius;if(m.captureAssist)return '씨앗탄 영입 보조';if(state.units.some(u=>u.hp>0&&u.team==='friendly'&&u.movement.intent==='return'))return '병력 회수 중';return home?'둥지에서 회복':g.name+' · '+g.danger};
ledgerHTML=function(){const l=state.campaign.ledger;return`<div class="notice">사냥으로 모은 광물 ◆ ${fmt(l.rewardM)} · 성장 투자 ◆ ${fmt(l.investmentM)}<br>누적 전환 ${fmt(moaRoster.reduce((n,t)=>n+moaCollectionCount(t),0))}마리 · 전투 손실 ${fmt(l.losses)}마리<br><small>모아와 아군 중 누가 처치해도 광물을 획득합니다. 영입에 성공해도 같은 광물을 얻습니다.</small></div>`};
refreshUI=function(){if(bloomInTick){bloomEmit("refreshUI",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;uiClock=0;$('minerals').textContent=fmt(state.minerals);$('population').textContent=`인구 ${pop()} / ${cap()}`;$('motherHealth').textContent=`${WorldView.data().campaign.moaGrowth?'성장한 모아':'작은 모아'} ${Math.ceil(Math.max(0,WorldView.leader().hp))} / ${maxMotherHP()}`;$('health').firstElementChild.style.width=clamp(WorldView.leader().hp/maxMotherHP()*100,0,100)+'%';$('zoneLabel').textContent='첫 사냥터';$('goal').textContent=objectiveStatus();$('progressTrack').innerHTML=CONFIG.campaign.grounds.map((g,i)=>`<i class="${WorldView.data().campaign.parcels[i]?'open':''}" title="${g.name}"></i>`).join('');drawMini()};
showIntro=function(hasSave){openModal('intro',`<div class="eyebrow">BLOOM · MOA & THE LIVING FRONTIER</div><h1>BLOOM</h1><p style="font-size:15px;color:#dce9c3;margin:0">작은 모아, 함께 자라는 군락</p><div class="introArt"><canvas id="introCanvas" width="540" height="160"></canvas></div><p>작은 모아 혼자 사냥을 시작합니다.<br>모아의 직접 처치와 표식 적의 아군 처치로 동료를 모으고,<br>광물로 병력을, 레벨업으로 모아를 키웁니다.</p><div class="introList"><div><b>이끈다</b>클릭·탭 / WASD<br>공격 예고를 보고 피하기</div><div><b>모은다</b>모아의 직접 처치<br>이동 중에도 자동 발사</div><div><b>자란다</b>계속 뽑는 병력 성장<br>3장 중 1장 · 군단 60 인구</div></div><div class="notice">움직여 공격을 피하는 동안에도 가까운 적에게 씨앗탄을 쏩니다. 한 방에 마무리할 적을 먼저 노립니다. 빨간 예고는 옆으로 피하세요. 영입한 친구의 기본 체력 · 공격력은 적일 때의 50%입니다.</div><button class="primary" data-action="start">${hasSave?'모아와 이어가기':'모아와 첫 사냥'} →</button><p class="fine">자동 저장 · 백업 가능 · 오프라인 단일 파일<br>첫 구역의 다섯 분기 사냥터 · 다음 구역은 아직 열리지 않습니다.</p>`);const art=$('introCanvas'),aw=art.clientWidth,ah=art.clientHeight;art.width=aw*2;art.height=ah*2;const c=art.getContext('2d');c.scale(2,2);if(typeof drawMoa==='function')drawMoa(c,{x:aw/2,y:62,size:28,growthStage:WorldView.data().campaign.moaGrowth||0,hp:1,maxHp:1},0,1);else{c.fillStyle='#e0e5ae';c.beginPath();c.ellipse(aw/2,62,28,32,0,0,Math.PI*2);c.fill();c.fillStyle='#263c34';c.beginPath();c.arc(aw/2-9,59,3,0,Math.PI*2);c.arc(aw/2+9,59,3,0,Math.PI*2);c.fill()}moaRoster.forEach((t,i)=>{if(window.RallyArt)RallyArt.draw(c,t,'friendly',aw*(i+0.5)/4,ah-23,unitDef(t).size*.8,0,0,{})})};
showMap=function(){openModal('map',sheetHead('사냥터 지도')+`<p>이끼밭에서 두 갈래로 뻗어나가세요. 광물을 투자해 구획을 연결하며, 열린 사냥터는 계속 남아 있습니다. 쓰러진 적은 빈자리에서 다시 자랍니다.</p>`+CONFIG.campaign.grounds.map((g,i)=>{const open=WorldView.data().campaign.parcels[i],c=parcelCost(i),s=WorldView.data().campaign.groundStats[i],from=CONFIG.campaign.parcels[i].from;return`<div class="zoneRow"><div class="badge" style="color:${g.color}">${i+1}</div><div style="flex:1"><b>${g.name} · ${open?g.danger:'미연결'}</b><small>${g.habitat} · 권장 ${g.recommended} 인구 + 성장</small><small>체력·공격력 ${regionMultiplier(i).toFixed(2)}배 · 첫 사냥터 대비<br>일반 적당 ◆ ${g.rewardM} · XP ${g.xp} · ${g.respawn}초부터 재생</small>${open?'':`<small>관문에 직접 도착해 연결 · ◆ ${fmt(CONFIG.campaign.parcels[i].cost[0])}${CONFIG.campaign.parcels[i].cost[1]?` · ◈ ${fmt(CONFIG.campaign.parcels[i].cost[1])}`:''}</small><small>연결 조건: ${from.map(n=>CONFIG.campaign.grounds[n].name).join(' 또는 ')}</small>`}</div></div>`}).join('')+`<div class="notice">모아와 아군 중 누가 처치해도 광물을 얻습니다. 모아가 직접 처치하거나 7초 표식 적을 내 병력이 처치하면 인구 한도 안에서 영입됩니다.<br>각 사냥터는 앞 번호 대비 체력·공격력이 ${CONFIG.regionProgression.factor}배입니다. 이동·공격 속도는 그대로예요.<br>Lv.${CONFIG.permanent.capacityLevel}부터 인구 최소 ${CONFIG.permanent.capacityFloor} · 현재 인구 한도 ${cap()} · 다음 구역은 아직 열리지 않습니다.</div>`)};
showDefeat=function(){if(bloomInTick){bloomEmit("showDefeat",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;openModal('defeat',`<div class="eyebrow">MOA WILL GROW AGAIN</div><h2>모아, 다시 한 걸음</h2><p>모아가 쓰러져 함께하던 병력을 잃었습니다.<br>광물 · 도감 · 모아 성장 · 성장 카드 · 연결한 구획은 남습니다.</p><div class="notice">둥지에서 다시 출발합니다. 영구 동료의 부활 자리도 모아 주변으로 옮겨져요. 남은 대기시간이 끝나면 다시 합류합니다.</div><button class="primary" data-action="recover">모아와 다시 출발 →</button>`)};
drawCampaignWorld=function(){const C=CONFIG.campaign;ctx.textAlign='center';for(let i=0;i<C.grounds.length;i++){const g=C.grounds[i];if(g.x+g.rx<view.x-view.w/2||g.x-g.rx>view.x+view.w/2)continue;const open=state.campaign.parcels[i];ctx.fillStyle=open?g.color+'14':'#23382dee';ctx.strokeStyle=open?g.color+'65':'#a9b99caa';ctx.lineWidth=open?2:8;ctx.beginPath();ctx.ellipse(g.x,g.y,g.rx,g.ry,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.font='bold 17px system-ui';ctx.fillStyle=g.color;ctx.fillText(`${i+1} · ${g.name}`,g.x,g.y-g.ry+28);ctx.font='11px system-ui';ctx.fillStyle='#f1f5d3';ctx.fillText(open?`${g.danger} · 권장 ${g.recommended} 인구 · 광물 ◆${g.rewardM}`:'잠든 구획 · 지도에서 뿌리를 연결하세요',g.x,g.y-g.ry+48)}for(const c of state.camps){if(!c.enabled||Math.abs(c.x-view.x)>view.w/2+200||Math.abs(c.y-view.y)>view.h/2+200)continue;if(c.remaining===0){if(!c.spawned||!c.regrowth?.length)continue;drawNest(ctx,c.x,c.y,0,.5);ctx.font='12px system-ui';ctx.fillStyle='#eff5d3';ctx.fillText(c.respawn>0?`무리 재생 ${Math.ceil(c.respawn)}초`:'빈자리에서 새 무리 재생',c.x,c.y+48)}else{ctx.font='10px system-ui';ctx.fillStyle='#ffdfb9';ctx.fillText(`${c.remaining}마리 · 사냥 무리`,c.x,c.y+CONFIG.campaign.hunting.labelOffset)}}const b=basePoint();ctx.strokeStyle='#eff5c644';ctx.beginPath();ctx.arc(b.x,b.y,CONFIG.campaign.base.healRadius,0,Math.PI*2);ctx.stroke();drawNest(ctx,b.x,b.y,state.campaign.moaGrowth?2:1,1.2);ctx.font='bold 13px system-ui';ctx.fillStyle='#f1f6d3';ctx.fillText('모아의 둥지 · 안전하게 회복',b.x,b.y-80)};

;

'use strict';
// Moa-local ground-body constraints. Desired joystick velocity is never inertial;
// only an actual combat impulse survives release. All work runs on fixed ticks.
CONFIG.moaPhysics={motherMass:6,massReferenceRadius:14,minMass:.45,massByClass:{light:1,medium:1.25,heavy:1.7},motherBodyScale:.86,unitBodyScale:.7,passes:4,maxPairCorrection:12,motherCorrectionBudget:22,slop:.08,impulseDrag:11,impulseStopSpeed:.6,maxImpulseSpeed:300,bashImpulse:190,growthImpulsePower:1,enemyPushScale:10,contactDecay:10,contactLean:.10,contactSquash:.055,contactStrengthDistance:8};
function moaBodyRadius(u){return radius(u)*(u.type==='mother'?CONFIG.moaPhysics.motherBodyScale:CONFIG.moaPhysics.unitBodyScale)}
function moaBodyMass(u){const p=CONFIG.moaPhysics;if(u.type==='mother')return p.motherMass*(radius(u)/CONFIG.mother.size)**2;const d=unitDef(u.type);return Math.max(p.minMass,(radius(u)/p.massReferenceRadius)**2*(p.massByClass[d.sizeClass]||1))}
// Simulation state is plain, enumerable actor data. Shared domain operations
// act on that state directly; serialization does not need an alternate shape.
class ImpactMotion {
 static state(actor){return actor.impact||(actor.impact={velocity:{x:0,y:0}})}
 static setVelocity(actor,x,y){const v=this.state(actor).velocity;v.x=x;v.y=y}
 static reset(actor){this.setVelocity(actor,0,0)}
 static add(actor,x,y){const p=CONFIG.moaPhysics,v=this.state(actor).velocity;let vx=(v.x||0)+x,vy=(v.y||0)+y,s=Math.hypot(vx,vy);if(s>p.maxImpulseSpeed){vx*=p.maxImpulseSpeed/s;vy*=p.maxImpulseSpeed/s}this.setVelocity(actor,vx,vy)}
 static removeInward(actor,nx,ny){const velocity=actor.impact?.velocity;if(!velocity)return;const v=velocity.x*nx+velocity.y*ny;if(v<0)this.setVelocity(actor,velocity.x-nx*v,velocity.y-ny*v)}
 static integrate(actor,dt,move){
  const v=actor.impact?.velocity;if(!v||!dt||!v.x&&!v.y)return;
  const p=CONFIG.moaPhysics,decay=Math.exp(-p.impulseDrag*dt),travel=(1-decay)/p.impulseDrag;
  move((v.x||0)*travel,(v.y||0)*travel);this.setVelocity(actor,v.x*decay,v.y*decay);
  if(Math.hypot(v.x,v.y)<p.impulseStopSpeed)this.reset(actor);
 }
}
class BodyContact {
 static state(actor){return actor.body||(actor.body={contact:0,lean:{x:0,y:0}})}
 static set(actor,contact,x,y){const body=this.state(actor);body.contact=contact;body.lean.x=x;body.lean.y=y}
 static reset(actor){this.set(actor,0,0,0)}
 static note(actor,nx,ny,strength){const body=this.state(actor),s=clamp(strength/CONFIG.moaPhysics.contactStrengthDistance,0,1);if(s>body.contact)this.set(actor,s,-nx*s,-ny*s)}
 static decay(actor,factor){const body=this.state(actor);this.set(actor,(body.contact||0)*factor,(body.lean.x||0)*factor,(body.lean.y||0)*factor)}
}
function resetMoaBody(u){ImpactMotion.reset(u);BodyContact.reset(u)}
function addMoaImpulse(u,x,y){if(!u||u.hp<=0)return;ImpactMotion.add(u,x,y)}
function noteMoaContact(nx,ny,strength,owner=state.mother){BodyContact.note(owner,nx,ny,strength)}
function removeInwardImpulse(u,nx,ny){ImpactMotion.removeInward(u,nx,ny)}
function boundMoaBody(u){return constrainWorld(u)}
function integrateMoaImpulse(u,dt){ImpactMotion.integrate(u,dt,(dx,dy)=>ThemedTerrain.move(u,dx,dy,moaBodyRadius(u)))}
function moveMoaBody(dt,ix,iy,owner=state.mother){const m=owner;
 if(!m.moveRoll(dt)){if(ix||iy)m.angle=Math.atan2(iy,ix);if(!(m.stun>0))bloomMoaSweptMove(m,ix*moaWalkSpeed(weaponOwnerGrowth(m))*dt,iy*moaWalkSpeed(weaponOwnerGrowth(m))*dt,moaBodyRadius(m),!!WorldPlayers.forEntity(m)?.navigation?.goal||!!WorldPlayers.forEntity(m)?.auto?.enabled)}
 m.stun=Math.max(0,(m.stun||0)-dt);integrateMoaImpulse(m,dt);constrainWorld(m);
}
function moaBashImpulse(t){
 const m=state.mother,p=CONFIG.moaPhysics;if(!t||t.hp<=0||m.hp<=0||unitDef(t.type)?.layer==='AIR')return;
 let dx=t.x-m.x,dy=t.y-m.y,l=Math.hypot(dx,dy);if(!l){dx=Math.cos(m.angle);dy=Math.sin(m.angle);l=1}const nx=dx/l,ny=dy/l,J=p.bashImpulse*(radius(m)/CONFIG.mother.size)**p.growthImpulsePower;
 addMoaImpulse(t,nx*J/moaBodyMass(t),ny*J/moaBodyMass(t));addMoaImpulse(m,-nx*J/moaBodyMass(m),-ny*J/moaBodyMass(m));noteMoaContact(nx,ny,p.contactStrengthDistance);
}
// Refresh only the fine grid after all AI/knockback/conversion/regrowth movement.
// Its prior-tick buckets are not conservative for moving bodies. No global scan
// inside a contact query, no neighbor truncation, and no RNG in the solver.
function refreshMoaContactGrid(){
 collisionGrid.forEach(list=>{list.length=0});maxCollisionGround=maxCollisionAir=0;
 for(const u of state.units){if(u.hp<=0)continue;const r=moaBodyRadius(u);if(unitDef(u.type).layer==='AIR')maxCollisionAir=Math.max(maxCollisionAir,r);else maxCollisionGround=Math.max(maxCollisionGround,r);const k=Math.floor(u.x/CONFIG.sim.collisionCell)+Math.floor(u.y/CONFIG.sim.collisionCell)*collisionColumns;let list=collisionGrid.get(k);if(!list)collisionGrid.set(k,list=[]);list.push(u)}
}
function reindexMoaContact(u,oldKey){const k=Math.floor(u.x/CONFIG.sim.collisionCell)+Math.floor(u.y/CONFIG.sim.collisionCell)*collisionColumns;if(k===oldKey)return;const old=collisionGrid.get(oldKey),i=old?.indexOf(u)??-1;if(i>=0)old.splice(i,1);let list=collisionGrid.get(k);if(!list)collisionGrid.set(k,list=[]);list.push(u)}
const moaContactCandidates=[];
function solveMoaContacts(owner=state.mother,prepared=false){
 const m=owner,p=CONFIG.moaPhysics;if(m.hp<=0)return;const mr=moaBodyRadius(m),mm=moaBodyMass(m);let budget=p.motherCorrectionBudget;
 if(!prepared)refreshMoaContactGrid();boundMoaBody(m);
 for(let pass=0;pass<p.passes;pass++){
  moaContactCandidates.length=0;nearLocal(m.x,m.y,mr+maxCollisionGround+p.maxPairCorrection,null,u=>{if(u!==m&&unitDef(u.type).layer!=='AIR')moaContactCandidates.push(u)});
  // Stable pair order even when corrections move a unit to a different grid cell.
  for(const player of WorldPlayers.all())if(player.leader!==m&&player.leader.hp>0&&dist(m,player.leader)<mr+moaBodyRadius(player.leader)+p.maxPairCorrection)moaContactCandidates.push(player.leader);moaContactCandidates.sort((a,b)=>a.id-b.id);let contacts=0;
  for(const u of moaContactCandidates){
   let dx=u.x-m.x,dy=u.y-m.y,l=Math.hypot(dx,dy),limit=mr+moaBodyRadius(u);if(l>=limit-p.slop)continue;
   if(!l){const a=u.id*CONFIG.sim.goldenAngle;dx=Math.cos(a);dy=Math.sin(a);l=1}else{dx/=l;dy/=l}
   const depth=limit-(Math.hypot(u.x-m.x,u.y-m.y)),correction=Math.min(p.maxPairCorrection,Math.max(0,depth-p.slop)),um=moaBodyMass(u),mx=m.x,my=m.y,ux=u.x,uy=u.y,key=Math.floor(u.x/CONFIG.sim.collisionCell)+Math.floor(u.y/CONFIG.sim.collisionCell)*collisionColumns;
   const md=Math.min(budget,correction*um/(mm+um));m.x-=dx*md;m.y-=dy*md;boundMoaBody(m);budget=Math.max(0,budget-Math.hypot(m.x-mx,m.y-my));
   // A wall takes the blocked body's share; the other body carries the remainder.
   const movedM=(mx-m.x)*dx+(my-m.y)*dy,ud=correction-movedM;u.x+=dx*ud;u.y+=dy*ud;boundMoaBody(u);
   const movedU=(u.x-ux)*dx+(u.y-uy)*dy,remaining=Math.min(budget,Math.max(0,correction-movedM-movedU));if(remaining){const x=m.x,y=m.y;m.x-=dx*remaining;m.y-=dy*remaining;boundMoaBody(m);budget=Math.max(0,budget-Math.hypot(m.x-x,m.y-y))}
   if(u.type!=='mother')reindexMoaContact(u,key);noteMoaContact(dx,dy,depth,m);
   // Only remove closing impact velocity. Desired tangential movement is intact.
   const closing=((m.impact?.velocity.x||0)-(u.impact?.velocity.x||0))*dx+((m.impact?.velocity.y||0)-(u.impact?.velocity.y||0))*dy;if(closing>0){const J=closing/(1/mm+1/um);addMoaImpulse(m,-dx*J/mm,-dy*J/mm);addMoaImpulse(u,dx*J/um,dy*J/um)}contacts++;
  }
  if(!contacts)break;
 }
 boundMoaBody(m);
}
const moaPhysicsCore={initializeMoa,push};
initializeMoa=function(){moaPhysicsCore.initializeMoa();resetMoaBody(state.mother);state.mother.stun=0;for(const u of state.units)resetMoaBody(u)};

// Existing enemy melee/shove paths already call push once. Route just their Moa
// target through mass-scaled impulse; do not add a second kick in damage().
push=function(t,x,y,amount){if(t.type!=='mother')return moaPhysicsCore.push(t,x,y,amount);if(t.hp<=0)return;const a=Math.atan2(t.y-y,t.x-x),p=CONFIG.moaPhysics,J=amount*p.enemyPushScale*p.motherMass/moaBodyMass(t);addMoaImpulse(t,Math.cos(a)*J,Math.sin(a)*J);noteMoaContact(-Math.cos(a),-Math.sin(a),Math.abs(amount))};
function publishMoaPhysics(){Object.assign(window.__army,{moaBodyRadius,moaBodyMass,solveMoaContacts,addMoaImpulse,boundMoaBody,moaBashImpulse,push})};

;

/** Bloom presentation contract, adapted from Rally RenderStateStore f9d4c282:
 * Declarative continuous fields, stable identity + source generation, shortest angles,
 * target-to-target discontinuity detection and lifecycle pruning. No gameplay writes.
 * Fixed simulation uses CONFIG.sim.tickRate; RAF samples presentation independently.
 */
CONFIG.render.presentation={snapDistance:160,cameraResponse:7.07};
CONFIG.sim.maxBacklog=2;
const {RenderObject,PresentationRuntime,snapshotRenderModel}=BloomGamekitInterpolation;
