  residentBoss:this.STEP,rivalLeader:this.STEP,rivalRecruit:this.STEP,rivalOwner:this.STEP,rivalColor:this.STEP,
  reveal:this.STEP,rectIdle:this.STEP,'movement.homePhase':this.STEP,'movement.deployment.phase':this.STEP,
