  'primaryAttack.pending.left':this.COUNTDOWN_SECONDS,'primaryAttack.pending.total':this.STATE_KEY,'primaryAttack.pending.angle':this.STEP,
  'primaryAttack.pending.target':this.STATE_KEY,'primaryAttack.pending.ranged':this.STATE_KEY,
  'pendingMelee.left':this.COUNTDOWN_SECONDS,'pendingMelee.total':this.STATE_KEY,'pendingMelee.target':this.STATE_KEY,'pendingMelee.aimX':this.STEP,'pendingMelee.aimY':this.STEP,
  'body.contact':this.DECAY,'body.lean.x':this.LINEAR,'body.lean.y':this.LINEAR,
  'sprout.aim':this.ANGLE,'sprout.recoil':this.DECAY,'sprout.kick':this.DECAY,'sprout.seedKind':this.STEP,
