  'roll.cooldown.leftMs':this.COUNTDOWN_MS,'roll.invulnerability.leftMs':this.COUNTDOWN_MS,permanentDiedAt:this.STEP,
  'attackController.phase':this.STATE_KEY,'attackController.pattern':this.STATE_KEY,
