 for(const e of presentation.maps.unit.values())if(e.epoch===presentation.epoch){dependency(e.source.finisher?.target);dependency(e.source.captureAssist?.target);for(const mark of e.source.moaRecruitMarks||[])dependency(mark.ownerId)}
