 const revivals=[];for(const account of Object.values(state.rarityAccounts||{}))for(const record of account.active){const point=ruiRevivalPoint(record);if(point)revivals.push({point:snapshotRenderModel(BloomPointRender,point),grade:record.grade,respawnAt:record.respawnAt})}
