'use strict';
// One permanent growth decision: a persisted, distinct three-card offer.
// This layer deliberately leaves the existing combat/contact/rendering pipeline intact.
const GROWTH={schema:2,costs:[50,100,175,250,350],costStep:25,costPlateau:650,seed:0x6d2b79f5};
const GROWTH_CARDS=[
 {id:'bash',name:'단단한 씨앗탄',icon:'✦',max:CONFIG.sim.integerLimit,desc:'모아의 씨앗탄 피해 강화',kind:'mother'},
 {id:'rhythm',name:'빠른 생장박동',icon:'↯',max:8,desc:'모아의 공격 간격 단축',kind:'mother'},
 {id:'attack',name:'날카로운 군단',icon:'⚔',max:4,desc:'모든 아군의 공격력 +15%',kind:'army'},
 {id:'health',name:'튼튼한 군락',icon:'♥',max:4,desc:'아군 체력 +14% · 모아 최대 체력 +180',kind:'army'},
 {id:'bounty',name:'광물 수집가',icon:'◆',max:4,desc:'광물 획득량 +20%',kind:'army'},
 {id:'stem',name:'긴 활줄기',type:'archer',max:3,desc:'씨앗궁수의 사거리 +25',effect:'range',per:25},
 {id:'crouch',name:'웅크린 성채',type:'shellbug',max:3,desc:'가만히 선 껍질딱정벌레의 갑각 +2',effect:'armor',per:2},
 {id:'wind',name:'바람타기',type:'dandelion',max:3,desc:'민들레 기동력 +8% · 비전투 가속 활성화',effect:'speed',per:.08},
 {id:'edge',name:'겹칼잎',type:'swordsman',max:3,desc:'칼잎 전사의 공격력 +18%',effect:'attack',per:.18}
];
GROWTH_CARDS.push({id:'vital',name:'깊은 생명뿌리',icon:'♥',max:CONFIG.sim.integerLimit,kind:'mother'}, {id:'renew',name:'다시 돋는 새싹',icon:'✚',max:CONFIG.sim.integerLimit,kind:'mother'}, {id:'reach',name:'멀리 나는 씨앗',icon:'◎',max:8,kind:'mother'});
const growthCore={initializeMoa,maxMotherHP,save,refreshUI,showIntro,showMap,showDefeat,researchEffect,hasUnitAbility,moaPower};

function newGrowth(){return{schema:GROWTH.schema,choices:0,rng:(bloomSeed ^ 0x9e3779b9) >>> 0,ranks:{},draft:null,serial:0}}
function growthState(){return state.campaign.growthCards}
function growthRank(id){return growthState()?.ranks[id]||0}
function growthCostAt(n){return GROWTH.costs[n]??Math.min(GROWTH.costPlateau,400+Math.max(0,n-5)*GROWTH.costStep)}
function growthCost(){return growthCostAt(growthState()?.choices||0)}
function growthSoftRank(n){return n<=1000?n:1000+Math.sqrt(n-1000)}
function growthVitalBonus(g=state.campaign?.growthCards){return 60*growthSoftRank(g?.ranks?.vital||0)}
function growthBashBonus(n=growthRank('bash')){return 8*growthSoftRank(n)}
function growthRecovery(n=growthRank('renew')){return .4*Math.sqrt(n)}
function growthInterval(n=growthRank('rhythm')){return CONFIG.moa.cooldown/(1+.15*n)}
function growthCardEffect(c){const n=growthRank(c.id),num=n=>Number(n.toFixed(2));if(c.id==='bash')return `씨앗탄 피해 ${num(growthCore.moaPower()+growthBashBonus(n))} → ${num(growthCore.moaPower()+growthBashBonus(n+1))}`;if(c.id==='vital')return `모아 최대 체력 ${num(maxMotherHP())} → ${num(maxMotherHP()+60*(growthSoftRank(n+1)-growthSoftRank(n)))}`;if(c.id==='renew')return `초당 체력 재생 ${num(growthRecovery(n))} → ${num(growthRecovery(n+1))} / 초`;if(c.id==='rhythm')return `모아 공격 간격 ${num(growthInterval(n))} → ${num(growthInterval(n+1))}초`;if(c.id==='reach')return `모아 씨앗탄 사거리 ${235+n*12} → ${235+(n+1)*12}`;return c.desc}
maxMotherHP=function(){return growthCore.maxMotherHP()+growthVitalBonus()};
initializeMoa=function(){CONFIG.moa.rangedReach=typeof growthReach==='function'?growthReach():235+12*growthRank('reach');return growthCore.initializeMoa()};
function validGrowth(g){if(!g||g.schema!==GROWTH.schema||!Number.isInteger(g.choices)||g.choices<0||g.choices>CONFIG.sim.integerLimit||!Number.isInteger(g.rng)||g.rng<0||g.rng>4294967295||g.serial!==g.choices+(g.draft?1:0)||!g.ranks||typeof g.ranks!=='object')return false;let sum=0;for(const [id,n]of Object.entries(g.ranks)){const d=GROWTH_CARDS.find(d=>d.id===id);if(!d||!Number.isInteger(n)||n<1||n>d.max)return false;sum+=n}if(sum!==g.choices)return false;if(g.draft){const d=g.draft;if(d.serial!==g.serial||d.cost!==growthCostAt(g.choices)||!Array.isArray(d.ids)||d.ids.length!==3||new Set(d.ids).size!==3||d.ids.some(id=>!GROWTH_CARDS.some(c=>c.id===id&&(g.ranks[id]||0)<c.max)))return false}return true}



researchEffect=function(u,effect){if(u.team!=='friendly')return 0;return GROWTH_CARDS.reduce((sum,d)=>sum+(d.type===u.type&&d.effect===effect?d.per*growthRank(d.id):0),0)};
hasUnitAbility=function(u){return u.team==='enemy'||u.type==='shellbug'&&growthRank('crouch')>0||u.type==='dandelion'&&growthRank('wind')>0};
moaPower=function(){return growthCore.moaPower()+growthBashBonus()};

// All species stay available; roster tiles are a collection view, never a loadout.
setCard=function(){return false};buy=function(){return false};buyResearch=function(){return false};purchaseCost=function(){return null};researchCost=function(){return null};
conversionEligible=function(t){return !!(t&&t.team==='enemy'&&!t.elite&&!t.boss&&t.camp>=0&&state.camps[t.camp]?.enabled&&friendlyTypes.includes(t.type)&&pop()+unitDef(t.type).supply<=cap())};
function growthTransaction(change){const backup=snapshot();try{change();if(!save())throw Error('storage');return true}catch{state=backup;rebuildGrid();resetPresentation();toast('저장 공간을 확인해 주세요. 광물과 선택은 바뀌지 않았어요.');return false}}
function growthMilestone(){const g=growthState(),next=Math.max(cap(),CONFIG.progression.caps[Math.min(5,g.choices+1)]);return`선택하면 인구 ${cap()}${next>cap()?' → '+next:' 유지'}${!state.campaign.moaGrowth?' · '+(3-g.choices)+'번 더 선택하면 모아 성장':''}`}
showCards=function(){if(bloomInTick){bloomEmit("showCards",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;openModal('collection',sheetHead('함께 모은 친구들')+moaCollectionHTML())};
