refreshUI=function(){if(bloomInTick){bloomEmit("refreshUI",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;growthCore.refreshUI();if(!growthState())return;const c=growthCost(),b=$('evolveButton');b.textContent=state.minerals>=c?'성장 선택 ✦ · ◆ '+fmt(c):'성장 ✦ · ◆ '+fmt(c);b.classList.toggle('ready',c!==null&&state.minerals>=c)};
