function initializeGrowthUI(){Object.assign(window.__army,{GROWTH,GROWTH_CARDS,growthCost,growthCostAt,growthCardEffect,growthVitalBonus,growthRecovery,growthInterval,maxMotherHP,growthRank,conversionEligible,moaPower,researchEffect,hasUnitAbility,setCard,buy,buyResearch,purchaseCost,researchCost,showUpgrades,showCards,load,reset,refreshUI});const joy=$('joystick');GameUI.listen(joy,'pointermove',e=>{if(paused){keys.clear();stick.x=stick.y=0;resetKnob();e.stopImmediatePropagation()}},true)};

