'use strict';
// Captured regional baselines are immutable; card multipliers remain separate.
CONFIG.challenge={schema:1,enemyHp:1.35,enemyAttack:1.45,recruitFraction:.5,motherHp:260,motherHealthPerCard:60,motherGrowthHp:80};
CONFIG.mother.hp=CONFIG.challenge.motherHp;CONFIG.mother.hpPerLevel=CONFIG.challenge.motherHealthPerCard;CONFIG.moa.growthHp=CONFIG.challenge.motherGrowthHp;
GROWTH_CARDS.find(c=>c.id==='health').desc=`아군 체력 +14% · 모아 최대 체력 +${CONFIG.mother.hpPerLevel}`;
const challengeCore={attackPower,drawMother};
function recruitScale(u,kind){return (kind==='hp'?u.recruitHpScale:u.recruitAttackScale)||1}

