drawMother=function(source=WorldView.leader()){challengeCore.drawMother(source);const m=source,p=m.primaryAttack?.pending;if((source.hp<=0)||!p?.ranged)return;const pose=presentationPose(m),a=p.angle,k=1-clamp(p.left/p.total,0,1),x=pose.x+Math.cos(a)*(m.size+4),y=pose.y+Math.sin(a)*(m.size+4);ellipse(ctx,x,y,4+k*6,3+k*3,a,'#eaffad');ctx.strokeStyle='#d9ffa888';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,12-k*5,0,Math.PI*2);ctx.stroke()};
