// Persistent five-room world. Camp records are retained only as typed population
// slot ledgers so historical saves, rewards and capture accounting remain intact.
CONFIG.rectWorld={schema:2,minSpawnDistance:380,attempts:16,cue:.8,grace:1.2,wall:20,gateWidth:180,wanderRadius:60,wanderMin:3,wanderMax:6,wanderSpeed:.35,gateReach:150,spawnSearchBudget:4,spawnCommitBudget:2,fillInterval:.22,localAggro:[120,210,230,250,250],spawnSeparation:[140,60,60,60,60],
 population:[[15,15],[12,4,12,8,4],[16,8,18,6],[15,9,9,18,12,9],[1,21,16,18]],
 rooms:[{x:48,y:48,w:852,h:1604},{x:900,y:48,w:850,h:802},{x:900,y:850,w:850,h:802},{x:1750,y:48,w:802,h:1052},{x:1750,y:1100,w:802,h:552}],
 gates:[{a:0,b:1,x:900,y:450,vertical:true},{a:0,b:2,x:900,y:1250,vertical:true},{a:1,b:3,x:1750,y:450,vertical:true},{a:2,b:3,x:1750,y:975,vertical:true},{a:3,b:4,x:2150,y:1100,vertical:false}]};

for(let gi=0;gi<CONFIG.campaign.grounds.length;gi++){let n=0;for(const camp of CONFIG.campaign.grounds[gi].camps)for(const member of camp.units)member.count=CONFIG.rectWorld.population[gi][n++];}
for(const d of campaignDefs){const ci=Number(d.sourceId.split('-').pop());d.members=CONFIG.campaign.grounds[d.ground].camps[ci].units.map(m=>({...m}));}
const rectCore={moveToward,push,projectile,moaContact,moaSeedTarget,drawCampaignWorld,drawMini,refreshUI,showMap,showIntro};
let rectWalls=[],rectWallKey='';
let rectFriendState=null,rectFriendTime=-1,rectFriendMask=0;
// Per-tick broad phase: empty remote rooms need no per-enemy grid query.
// Bits are only added during this tick as allies cross/spawn, never removed,
// so a stale positive merely falls back to the original exact local query.
function rectFriendlyRoomMask(){if(rectFriendState!==state||rectFriendTime!==state.time){rectFriendState=state;rectFriendTime=state.time;rectFriendMask=1<<regionAt(state.mother.x,state.mother.y);for(const u of state.units)if(u.team==='friendly'&&u.hp>0)rectFriendMask|=1<<regionAt(u.x,u.y)}return rectFriendMask}
function regionAt(x,y){return CONFIG.rectWorld.rooms.findIndex(r=>x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h)}
nearestGround=function(p=state.mother){return Math.max(0,regionAt(p.x,p.y))};
lockedParcelAt=function(x,y,parcels=state?.campaign?.parcels){const i=regionAt(x,y);return i<0?-1:parcels?.[i]?-1:i};
function worldWalls(){const parcels=state?.campaign?.parcels||[true,false,false,false,false],key=parcels.join('');if(key===rectWallKey)return rectWalls;rectWallKey=key;const h=CONFIG.rectWorld.wall/2;rectWalls=[];function line(x1,y1,x2,y2,gates=[]){const vertical=x1===x2,start=vertical?y1:x1,end=vertical?y2:x2;let cursor=start;for(const g of gates.filter(g=>parcels[g.a]&&parcels[g.b]).sort((a,b)=>(vertical?a.y-b.y:a.x-b.x))){const p=vertical?g.y:g.x,half=CONFIG.rectWorld.gateWidth/2;if(p-half>cursor)add(cursor,p-half);cursor=p+half}if(cursor<end)add(cursor,end);function add(a,b){rectWalls.push(vertical?{x:x1-h,y:a,w:2*h,h:b-a}:{x:a,y:y1-h,w:b-a,h:2*h})}}
 const G=CONFIG.rectWorld.gates,R=CONFIG.rectWorld.rooms;
 // Derive each unique shared boundary from the room geometry. A horizontal
 // seam stops at its actual room edge; gates are cut only into their own edge.
 const segments=new Map();for(const r of R)for(const e of [[r.x,r.y,r.x+r.w,r.y],[r.x,r.y+r.h,r.x+r.w,r.y+r.h],[r.x,r.y,r.x,r.y+r.h],[r.x+r.w,r.y,r.x+r.w,r.y+r.h]]){const vertical=e[0]===e[2],key=(vertical?'v':'h')+':'+(vertical?e[0]:e[1]);if(!segments.has(key))segments.set(key,[]);segments.get(key).push(e)}
 for(const edges of segments.values()){const vertical=edges[0][0]===edges[0][2],axis=vertical?1:0;edges.sort((a,b)=>a[axis]-b[axis]);let e=edges[0].slice();for(let i=1;i<=edges.length;i++){const n=edges[i];if(n&&n[axis]<=e[axis+2])e[axis+2]=Math.max(e[axis+2],n[axis+2]);else{line(...e,G.filter(g=>g.vertical===vertical&&(vertical?g.x===e[0]&&g.y>=e[1]&&g.y<=e[3]:g.y===e[1]&&g.x>=e[0]&&g.x<=e[2])));if(n)e=n.slice()}}};return rectWalls}
function wallHit(ax,ay,bx,by,pad=0){let best=null;const dx=bx-ax,dy=by-ay;for(const w of worldWalls()){const loX=w.x-pad,hiX=w.x+w.w+pad,loY=w.y-pad,hiY=w.y+w.h+pad;if(Math.max(ax,bx)<loX||Math.min(ax,bx)>hiX||Math.max(ay,by)<loY||Math.min(ay,by)>hiY)continue;let entry=-Infinity,exit=Infinity,nx=0,ny=0;for(const [a,d,lo,hi,axis]of [[ax,dx,loX,hiX,0],[ay,dy,loY,hiY,1]]){if(Math.abs(d)<1e-10){if(a<=lo||a>=hi){exit=-Infinity;break}continue}let t1=(lo-a)/d,t2=(hi-a)/d,n=d>0?-1:1;if(t1>t2)[t1,t2]=[t2,t1];if(t1>entry){entry=t1;nx=axis?0:n;ny=axis?n:0}exit=Math.min(exit,t2)}if(entry<=exit&&exit>0&&entry>=-1e-8&&entry<=1&&(!best||entry<best.t))best={t:Math.max(0,entry),nx,ny}}return best}
function wallClear(a,b,pad=0){return !wallHit(a.x,a.y,b.x,b.y,pad)}
function pointClear(x,y,pad){return !worldWalls().some(w=>x>w.x-pad&&x<w.x+w.w+pad&&y>w.y-pad&&y<w.y+w.h+pad)&&regionAt(x,y)>=0&&lockedParcelAt(x,y)<0}
function safeRoomPoint(i,x,y,pad){const r=CONFIG.rectWorld.rooms[Math.max(0,i)],h=CONFIG.rectWorld.wall/2+pad+1;return{x:clamp(x,r.x+h,r.x+r.w-h),y:clamp(y,r.y+h,r.y+r.h-h)}}
function constrainWorld(u){if(!u)return;const r=moaBodyRadius(u),tx=u.x,ty=u.y,checkpoint=u.spatial?.constrained;let x=checkpoint?.x,y=checkpoint?.y;
 if(!Number.isFinite(x)||!Number.isFinite(y)||!ThemedTerrain.bodyClear(u,x,y,r)){const p=ThemedTerrain.safePoint(tx,ty,r);x=p.x;y=p.y;SpatialPosition.constrain(u,x,y);spatialUnit(u,true);return}
 u.x=x;u.y=y;ThemedTerrain.move(u,tx-x,ty-y,r);
 if(u.team==='friendly'&&rectFriendState===state&&rectFriendTime===state.time)rectFriendMask|=1<<Math.max(0,regionAt(u.x,u.y));
}
boundMoaBody=constrainWorld;keepOutsideLocked=constrainWorld;
function nextRoomGate(from,to){if(from<0||to<0||from===to)return null;const open=state.campaign.parcels,branch=open[1]?1:2;const next=[[-1,1,2,branch,branch],[0,-1,0,3,3],[0,0,-1,3,3],[branch,1,2,-1,4],[3,3,3,3,-1]][from][to];return CONFIG.rectWorld.gates.find(g=>open[g.a]&&open[g.b]&&(g.a===from&&g.b===next||g.b===from&&g.a===next))||null}
moveToward=function(u,x,y,speed,dt){if(u.team==='friendly'){const from=regionAt(u.x,u.y),to=regionAt(state.mother.x,state.mother.y);if(from!==to){const g=nextRoomGate(from,to);if(g){const other=g.a===from?g.b:g.a,r=CONFIG.rectWorld.rooms[other],cross=moaBodyRadius(u)+CONFIG.rectWorld.wall+24; // stage at gate center before crossing, never diagonal-cut a jamb
 if(g.vertical){x=g.x+(r.x>=g.x?cross:-cross);y=g.y;if(Math.abs(u.y-g.y)>CONFIG.rectWorld.gateWidth/2-moaBodyRadius(u)-15&&Math.abs(u.x-g.x)<cross+20)x=g.x+(u.x<g.x?-cross:cross)}else{x=g.x;y=g.y+(r.y>=g.y?cross:-cross);if(Math.abs(u.x-g.x)>CONFIG.rectWorld.gateWidth/2-moaBodyRadius(u)-15&&Math.abs(u.y-g.y)<cross+20)y=g.y+(u.y<g.y?-cross:cross)}}else{const p=safeRoomPoint(to,x,y,moaBodyRadius(u));x=p.x;y=p.y}}}
 const moved=rectCore.moveToward(u,x,y,speed,dt);constrainWorld(u);return moved};
push=function(u,x,y,n){rectCore.push(u,x,y,n);constrainWorld(u)};

spawnCamp=function(c){if(!c.enabled||c.spawned||!rivalRoomActive(c.ground))return;c.spawned=true;c.cycles++;c.regrowth=[];let slot=0;for(const m of c.members)for(let n=0;n<m.count;n++)c.regrowth.push({type:m.type,boss:!!m.boss,left:slot++*CONFIG.rectWorld.fillInterval,cued:false});c.remaining=0};
function validRegrowSpot(c,q,p,other=q){const C=CONFIG.rectWorld,r=q.variant==='rival'?CONFIG.mother.size:unitDef(q.type).size*(q.boss?CONFIG.combat.eliteSize:1),room=CONFIG.rectWorld.rooms[rivalSpawnRoom(c,q)];if(!p||p.x<room.x+r+20||p.x>room.x+room.w-r-20||p.y<room.y+r+20||p.y>room.y+room.h-r-20||!pointClear(p.x,p.y,r+18)||dist(p,state.mother)<C.minSpawnDistance||dist(p,basePoint())<CONFIG.campaign.base.healRadius+r+30)return false;for(const g of C.gates)if(dist(p,g)<C.gateWidth/2+r+22)return false;let clear=true;const spacing=C.spawnSeparation[rivalSpawnRoom(c,q)];near(p.x,p.y,Math.max(r+100,spacing),null,u=>{if(dist(p,u)<Math.max(spacing,r+radius(u)+24)){clear=false;return false}});if(!clear)return false;for(const camp of state.camps)for(const slot of camp.regrowth||[])if(slot!==other&&slot.cued&&dist(p,slot.point)<Math.max(spacing,r+unitDef(slot.type).size+28))return false;return true}
regrowSpot=function(c,q){const r=CONFIG.rectWorld.rooms[c.ground],pad=unitDef(q.type).size+32;for(let n=0;n<CONFIG.rectWorld.attempts;n++){const p={x:r.x+pad+random()*(r.w-pad*2),y:r.y+pad+random()*(r.h-pad*2)};if(validRegrowSpot(c,q,p))return p}return null};
regrowCamps=function(dt){const activeRooms=rivalActiveRooms();let searches=CONFIG.rectWorld.spawnSearchBudget,commits=CONFIG.rectWorld.spawnCommitBudget;for(const c of state.camps){if(!c.enabled||!c.spawned)continue;const g=CONFIG.campaign.grounds[c.ground];for(let i=(c.regrowth?.length||0)-1;i>=0;i--){const q=c.regrowth[i];if(q.variant!=='rival'&&!(activeRooms&(1<<c.ground))){if(q.cued){q.cued=false;delete q.point;q.left=0}continue}q.left=Math.max(0,q.left-dt);if(q.left>0)continue;if(q.cued){if(commits<=0)continue;commits--;if(!validRegrowSpot(c,q,q.point)){q.cued=false;delete q.point;q.left=.3;continue}const p=q.point;spawn(q.type,'enemy',p.x,p.y,{zone:0,camp:c.id,boss:q.boss,elite:q.boss,hpScale:g.hp*(q.boss?g.bossHp/CONFIG.combat.eliteHp[0]:1),attackScale:g.attack*(q.boss?g.bossAttack/CONFIG.combat.eliteAttack:1)});c.remaining++;c.spawnSerial=(c.spawnSerial||0)+1;c.regrowth.splice(i,1);rebuildGrid();continue}if(searches<=0)continue;searches--;const p=regrowSpot(c,q);if(p){q.cued=true;q.point=p;q.left=CONFIG.rectWorld.cue}else q.left=.5}c.respawn=c.regrowth?.length?Math.min(...c.regrowth.map(q=>q.left)):0}};
canTarget=function(u,t){if(!core.canTarget(u,t)||UnitMovement.isReturning(u)||(t.movement?.homePhase==='return')||lockedParcelAt(t.x,t.y)>=0||!wallClear(u,t))return false;if(u.team==='enemy'){if(state.time<(u.aggroAt||0)||regionAt(t.x,t.y)!==(state.camps[u.camp]?.ground??regionAt(u.homeX,u.homeY)))return false;const room=state.camps[u.camp]?.ground??0;if(!u.target&&state.time-u.combat>3&&dist(u,t)>CONFIG.rectWorld.localAggro[room])return false;const home={x:u.homeX??u.hx,y:u.homeY??u.hy};if(sqdist(t,home)>CONFIG.campaign.hunting.leashRadius**2)return false}return true};
findTarget=function(u){return UnitMovement.isReturning(u)?null:core.findTarget(u)};

const rectSpeed=effectiveSpeed;effectiveSpeed=function(u){return rectSpeed(u)*(u.team==='enemy'&&u.rectIdle?CONFIG.rectWorld.wanderSpeed:1)};
moaContact=function(t,extra=0){return rectCore.moaContact(t,extra)&&wallClear(state.mother,t)};moaSeedTarget=function(t){return rectCore.moaSeedTarget(t)&&wallClear(state.mother,t)};

projectile=function(u,t,...args){if(!wallClear(u,t))return;return rectCore.projectile(u,t,...args)};
function projectileWallBlocked(p,nx,ny){return !!wallHit(p.x,p.y,nx,ny,p.shotRadius||CONFIG.render.projectileRadius)}

// Validate every old schema through the original loader before moving any body.
// The immutable typed ledgers are unchanged; new positions are validated separately.

// Reach is measured from Moa's footprint; a larger body can still reach the door.
function gateDestination(g){const room=regionAt(state.mother.x,state.mother.y);return room===g.a?g.b:room===g.b?g.a:-1}
function reachableClosedGate(g){
 if((!bloomInTick&&(!playing||paused||modalKind))||state.dead||state.mother.hp<=0)return false;
 const m=state.mother,room=regionAt(m.x,m.y),to=gateDestination(g),r=moaBodyRadius(m);
 if(to<0||!state.campaign.parcels[room]||state.campaign.parcels[to]||!CONFIG.campaign.parcels[to].from.includes(room))return false;
 if(dist(g,m)>Math.max(CONFIG.rectWorld.gateReach,r+CONFIG.rectWorld.wall+60))return false;
 if(Math.abs(g.vertical?m.y-g.y:m.x-g.x)>CONFIG.rectWorld.gateWidth/2)return false;
 // Check the approach on our side, not through the closed door or another wall.
 const q={x:g.x,y:g.y},side=CONFIG.rectWorld.rooms[room];
 if(g.vertical)q.x+=(side.x+side.w/2<g.x?-1:1)*(CONFIG.rectWorld.wall/2+2);
 else q.y+=(side.y+side.h/2<g.y?-1:1)*(CONFIG.rectWorld.wall/2+2);
 return wallClear(m,q);
}
function nearClosedGate(){return CONFIG.rectWorld.gates.find(reachableClosedGate)}
function canUnlockParcelHere(i){return Number.isInteger(i)&&CONFIG.rectWorld.gates.some(g=>gateDestination(g)===i&&reachableClosedGate(g))}
const gateButton=(globalThis.BLOOM_HEADLESS ? null : (document.createElement('button')));if (!globalThis.BLOOM_HEADLESS) { gateButton.id='gateButton'; }
if (!globalThis.BLOOM_HEADLESS) { gateButton.style.cssText='position:fixed;transform:translate(-50%,-100%);z-index:4;max-width:180px;min-height:44px;display:none;background:#253d2ff2;border:1px solid #e0d18f;padding:7px 11px;border-radius:11px;color:#fff5c7;font:bold 12px system-ui;line-height:1.4;touch-action:manipulation'; }
if (!globalThis.BLOOM_HEADLESS) { document.body.appendChild(gateButton); }
function updateGateButton(){
 const g=nearClosedGate();gateButton.style.display='none';if(!g)return;
 const to=gateDestination(g),cost=parcelCost(to),p=WorldUI.screen(g,{at:'ground',pixelY:-26});
 // Keep the control attached to the door, never relocate it into a global HUD.
 if(p.x<8||p.x>innerWidth-8||p.y<70||p.y>innerHeight-90)return;
 gateButton.textContent='연결 ◆ '+fmt(cost[0])+(cost[1]?' · ◈ '+fmt(cost[1]):'');
 gateButton.setAttribute('aria-label',CONFIG.campaign.grounds[to].name+' 관문 '+gateButton.textContent);
 gateButton.disabled=!affordable(cost);gateButton.style.left=p.x+'px';gateButton.style.top=p.y+'px';gateButton.style.display='block';
}
refreshUI=function(){if(bloomInTick){bloomEmit("refreshUI",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;rectCore.refreshUI();updateGateButton()};
const gateRender=render;render=function(...args){gateRender(...args);updateGateButton()};
drawCampaignWorld=function(){const world=bloomRenderWorld();ctx.textAlign='center';CONFIG.rectWorld.rooms.forEach((r,i)=>{const g=CONFIG.campaign.grounds[i],open=world.campaign.parcels[i];ctx.fillStyle=open?g.color+'18':'#12291ef2';ctx.fillRect(r.x,r.y,r.w,r.h);WorldUI.begin(ctx,{x:r.x+r.w/2,y:r.y+42},{at:'ground'});ctx.fillStyle=open?g.color:'#758777';ctx.font='bold 17px system-ui';ctx.fillText(`${i+1} · ${g.name}`,r.x+r.w/2,r.y+42);ctx.font='11px system-ui';ctx.fillText(open?`${g.danger} · 정원 ${g.camps.reduce((n,c)=>n+c.units.reduce((s,u)=>s+u.count,0),0)}마리`:'관문을 연결해 탐험하세요',r.x+r.w/2,r.y+62);ctx.restore()});for(const w of world.walls){ctx.fillStyle='#425944';ctx.fillRect(w.x,w.y,w.w,w.h);ctx.strokeStyle='#9ba77a';ctx.lineWidth=2;ctx.strokeRect(w.x,w.y,w.w,w.h)}for(const g of CONFIG.rectWorld.gates){const open=world.campaign.parcels[g.a]&&world.campaign.parcels[g.b];WorldUI.begin(ctx,g,{at:'ground'});ctx.fillStyle=open?'#c6e09e':'#d4b97b';ctx.font='bold 12px system-ui';ctx.fillText(open?'열린 관문':'Lv.'+(CONFIG.rarity.gateLevels[g.b]||1),g.x,g.y-12);ctx.restore();if(open){ctx.strokeStyle='#bddd9255';ctx.lineWidth=2;ctx.strokeRect(g.x-(g.vertical?20:85),g.y-(g.vertical?85:20),g.vertical?40:170,g.vertical?170:40)}}for(const c of world.camps)for(const q of c.regrowth||[]){if(!q.point)continue;const p=q.point,k=1-q.left/CONFIG.rectWorld.cue;ctx.save();ctx.strokeStyle=q.variant==='rival'?CONFIG.rivalMoa.color:'#e4f3a8';ctx.lineWidth=q.variant==='rival'?4:2;ctx.beginPath();terrainCirclePath(p.x,p.y,(q.variant==='rival'?30:18)+12*k);ctx.stroke();ctx.fillStyle='#d5ee9977';ctx.beginPath();terrainCirclePath(p.x,p.y,5+9*k);ctx.fill();ctx.restore()}const b=world.local.basePoint;ctx.strokeStyle='#eff5c644';ctx.beginPath();terrainCirclePath(b.x,b.y,CONFIG.campaign.base.healRadius);ctx.stroke();drawNest(ctx,b.x,b.y,world.campaign.moaGrowth?2:1,1.2);WorldUI.begin(ctx,b,{at:'ground'});ctx.font='bold 13px system-ui';ctx.fillStyle='#f1f6d3';ctx.fillText('모아의 둥지 · 회복',b.x,b.y-80);ctx.restore()};
