drawMini=function(){return bloomWithPresentation(()=>{const world=bloomRenderWorld(),leader=bloomRenderUnit(world.local.leaderId);mini.clearRect(0,0,180,104);const sx=180/CONFIG.campaign.width,sy=104/CONFIG.campaign.height;CONFIG.rectWorld.rooms.forEach((r,i)=>{mini.fillStyle=world.campaign.parcels[i]?CONFIG.campaign.grounds[i].color+'66':'#13251b';mini.fillRect(r.x*sx,r.y*sy,r.w*sx,r.h*sy)});mini.fillStyle='#dbe4b1';for(const w of world.walls)mini.fillRect(w.x*sx,w.y*sy,Math.max(1,w.w*sx),Math.max(1,w.h*sy));if(!leader)return;mini.fillStyle='#fffbe0';mini.beginPath();mini.arc(leader.x*sx,leader.y*sy,3,0,Math.PI*2);mini.fill()})};
showMap=function(){rectCore.showMap();const p=$('sheet').querySelector('p');if(p)p.textContent='다섯 직사각형 구획은 관문으로만 연결됩니다. 모아가 관문에 직접 도착한 뒤 필요한 자원을 내면 영구 개방됩니다. 지도에서는 연결할 수 없습니다. 새 적은 모아가 있는 구획의 먼 빈자리에서만 자랍니다. 멀어진 적도 사라지지 않습니다.'};
function publishRegionGeometry(){Object.assign(window.__army,{regionAt,worldWalls,wallHit,wallClear,constrainWorld,nextRoomGate,regrowSpot,regrowCamps,validRegrowSpot,projectileWallBlocked,nearClosedGate,canUnlockParcelHere,spawnCamp,spawn,canTarget,findTarget,updateUnit,moveToward,load,reset,moaContact,moaSeedTarget,damage,projectile,boundMoaBody,showMap,drawCampaignWorld,drawMini})};

