'use strict';
// Local, event-driven retaliation. No threat tables or broadcast chain.
CONFIG.retaliation={memory:6,targetLock:1,assistRadius:[180,220,240,260,260],helpers:[1,2,2,3,3],lostSight:2,healDelay:2,reengageRadius:280,reengageDelay:3};
const retaliationCore={impact};
let retaliationImpact=null;
function enemyRoom(u){return state.camps[u.camp]?.ground??regionAt(u.homeX??u.hx,u.homeY??u.hy)}
function enemyHome(u){return{x:u.homeX??u.hx,y:u.homeY??u.hy}}
function combatIdentity(u){return !!(u&&u.hp>0&&idMap.get(u.id)===u)}
function retaliationTarget(u,t,visible=true){return combatIdentity(t)&&core.canTarget(u,t)&&lockedParcelAt(t.x,t.y)<0&&regionAt(t.x,t.y)===enemyRoom(u)&&sqdist(t,enemyHome(u))<=CONFIG.campaign.hunting.leashRadius**2&&(!visible||wallClear(u,t))}
function clearRetaliation(u){delete u.aggro;u.target=0;u.pendingMelee=null;UnitMovement.returnHome(u,false);u.rectIdle=false;u.query=CONFIG.sim.targetInterval}
function enemyReturn(u,hard=false){let a=u.aggro;if(!a)a=u.aggro={until:0,lock:0,token:u.id,called:true,lastDamage:-99,seen:state.time,x:u.x,y:u.y,reengageAt:0};if(!(u.movement?.homePhase==='return'))a.reengageAt=state.time+CONFIG.retaliation.reengageDelay;a.hard=!!(a.hard||hard);a.search=false;UnitMovement.returnHome(u,true);u.target=0;u.pendingMelee=null;const h=enemyHome(u);u.hx=h.x;u.hy=h.y}
function callNearbyAssist(v,t){const C=CONFIG.retaliation,a=v.aggro;a.called=true;if(v.boss)return;const room=enemyRoom(v),candidates=[];near(v.x,v.y,C.assistRadius[room],'enemy',h=>{if(!sameFaction(h,v)||h===v||h.boss||(h.movement?.homePhase==='return')||h.target||h.aggro||enemyRoom(h)!==room||!wallClear(v,h)||!retaliationTarget(h,t))return;candidates.push(h)});candidates.sort((a,b)=>sqdist(v,a)-sqdist(v,b)||a.id-b.id);for(const h of candidates.slice(0,C.helpers[room]))engageEnemy(h,t,a.token,true)}
function engageEnemy(v,t,token=0,assisted=false,notify=true){if(v.rivalOwner||!retaliationTarget(v,t))return false;const C=CONFIG.retaliation,h=enemyHome(v);let a=v.aggro;if((v.movement?.homePhase==='return')){if(a?.hard||state.time<(a?.reengageAt||0)||sqdist(v,h)>C.reengageRadius**2||sqdist(t,h)>C.reengageRadius**2)return false;UnitMovement.returnHome(v,false)}const fresh=!a;if(fresh)a=v.aggro={until:state.time+C.memory,lock:0,token:token||v.id,called:assisted,lastDamage:-99,seen:state.time,x:t.x,y:t.y,reengageAt:0,hard:false,search:false};a.until=state.time+C.memory;const current=idMap.get(v.target);if(current&&v.target!==t.id&&state.time<a.lock&&retaliationTarget(v,current))return true;if(v.target!==t.id){v.pendingMelee=null;a.lock=state.time+C.targetLock}v.target=t.id;v.query=CONFIG.sim.targetInterval;v.combat=state.time;a.seen=state.time;a.x=t.x;a.y=t.y;a.search=false;v.rectIdle=false;if(notify&&!a.called)callNearbyAssist(v,t);if(fresh)addFx('ring',v.x,v.y,0,0,'#f3bb7a',radius(v)+9,.25);return true}
canTarget=function(u,t){if(!core.canTarget(u,t)||UnitMovement.isReturning(u)||lockedParcelAt(t.x,t.y)>=0||!wallClear(u,t))return false;if(u.team!=='enemy')return true;if(!retaliationTarget(u,t,false))return false;if(u.aggro&&state.time<u.aggro.until)return !u.aggro.search;if(state.time<(u.aggroAt||0))return false;return dist(u,t)<=CONFIG.rectWorld.localAggro[enemyRoom(u)]};
findTarget=function(u){return UnitMovement.isReturning(u)||u.aggro?.search?null:core.findTarget(u)};
// The impact point governs hit LOS; the living projectile owner governs retaliation.
impact=function(p){const old=retaliationImpact;retaliationImpact=p;try{return retaliationCore.impact(p)}finally{retaliationImpact=old}};


