function stepAbilityProjectile(p,dt){p.life-=dt;if(p.life<=0){finishAbilityShot(p);return}let t=idMap.get(p.target);if(p.homing){if(!t||t.hp<=0||!factionsHostile(projectileOwner(p),t)||lockedParcelAt(t.x,t.y)>=0){finishAbilityShot(p);return}p.angle=Math.atan2(t.y-p.y,t.x-p.x);p.aimX=t.x;p.aimY=t.y}const travel=Math.min(p.speed*dt,Math.max(0,p.range-p.progress)),ax=p.x,ay=p.y,bx=ax+Math.cos(p.angle)*travel,by=ay+Math.sin(p.angle)*travel,wall=wallHit(ax,ay,bx,by,p.shotRadius),end=wall?Math.max(0,wall.t-1e-6):1,hits=[];function consider(e){if(!e||e.hp<=0||!factionsHostile(projectileOwner(p),e)||p.hitIds.includes(e.id)||lockedParcelAt(e.x,e.y)>=0)return;const at=abilityCircleEntry(ax,ay,bx,by,e,p.shotRadius);if(at!==null&&at<=end&&wallClear({x:ax,y:ay},e))hits.push({e,at})}if(p.homing)consider(t);else near((ax+bx)/2,(ay+by)/2,travel/2+abilityTargetPadding,null,consider);if(!p.homing)for(const player of WorldPlayers.all())consider(player.leader);hits.sort((a,b)=>a.at-b.at||a.e.id-b.e.id);for(const h of hits){if(h.e.hp<=0)continue;p.x=ax+(bx-ax)*h.at;p.y=ay+(by-ay)*h.at;p.hitIds.push(h.e.id);p.lastVictim={id:h.e.id,x:p.x,y:p.y};const target=p.target;p.target=h.e.id;impact(p);p.target=target;p.remaining--;if(p.remaining<=0){abilityDescendants(p,h.e);p.progress+=travel*h.at;finishAbilityShot(p);return}}p.x=ax+(bx-ax)*end;p.y=ay+(by-ay)*end;p.progress+=travel*end;if(wall||p.progress>=p.range-1e-6)finishAbilityShot(p);}
