function initializeStartUI(){
 GameUI.handler($('pause'),'onclick',showPause);
 // These state changes precede the existing action handler. A confirmed reset
 // from the home settings must actually start play, not leave a closed menu.
 GameUI.listen(document,'click',e=>{const b=e.target.closest('button');if(b?.dataset.action==='reset'){playing=true;document.body.classList.remove('intro')}},true);
 GameUI.listen(document,'click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ux==='help')showGameHelp();if(b.dataset.ux==='settings')showGameSettings();if(['start','reset'].includes(b.dataset.action)&&!WorldView.data().campaign.permanents.instructionSeen){bloomQueue('tutorialAck');toast('클릭·탭으로 이동 · 두 번 누르면 구르기 · 공격은 자동이에요');toastClock=3}if(b.dataset.action==='save')startUXHasSave=true;});
 Object.assign(window.__army,{showIntro,showPause,showGameHelp,showGameSettings,closeModal,refreshUI,load});
};

