'use strict';
// Session-only steering. Uses ordinary fixed-tick motion, attacks and rewards.
CONFIG.autoHunt={queryIntervalMs:BLOOM_TIME.autoHunt.queryMs,rangeInset:18,stopBand:8,idleMs:BLOOM_TIME.autoHunt.idleMs};
const autoHuntCore={refreshUI};
const autoHunt={enabled:false,room:-1,target:0,query:0,status:'off',moving:false,idleMs:BLOOM_TIME.autoHunt.idleMs};
function refreshAutoHunt(){if(bloomInTick){bloomEmit("refreshAutoHunt",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;
 const b=$('autoHuntButton');if(!b)return;
 const active=WorldView.auto().enabled;b.dataset.active=String(active);
 b.textContent=paused&&!BloomSimulation.multiplayer?'일시정지':active?(WorldView.auto().target?'AUTO · 사냥':'AUTO · 대기'):'수동';
 b.title='목표까지 수동 이동 · 도착 후 0.7초 뒤 자동 사냥';
 b.setAttribute('aria-label',b.textContent);
}
function setAutoHunt(enabled){
 if(enabled&&(state.dead||state.mother.hp<=0||regionAt(state.mother.x,state.mother.y)<0))return false;
 autoHunt.enabled=!!enabled;autoHunt.room=enabled?regionAt(state.mother.x,state.mother.y):-1;
 autoHunt.target=0;autoHunt.query=0;autoHunt.moving=false;autoHunt.status=enabled?'waiting':'off';
 if(enabled){const m=state.mother,r=CONFIG.rectWorld.rooms[autoHunt.room];autoHunt.edgeX=Math.min(m.x-r.x,r.x+r.w-m.x);autoHunt.edgeY=Math.min(m.y-r.y,r.y+r.h-m.y)}
 refreshAutoHunt();return true;
}
function autoHuntValid(t){return !!(t&&regionAt(t.x,t.y)===autoHunt.room&&moaSeedTarget(t,true))}
function autoHuntSelect(){
 const m=state.mother,r=CONFIG.rectWorld.rooms[autoHunt.room];let best=null,score=Infinity;
 // One spatial query covers every corner of the occupied room, regardless of zoom.
 const reach=Math.hypot(Math.max(Math.abs(m.x-r.x),Math.abs(m.x-r.x-r.w)),Math.max(Math.abs(m.y-r.y),Math.abs(m.y-r.y-r.h)))+1;
 near(m.x,m.y,reach,'enemy',t=>{if(!autoHuntValid(t))return;const d=sqdist(m,t);if(d<score||d===score&&t.id<(best?.id??Infinity)){best=t;score=d}});
 autoHunt.target=best?.id||0;autoHunt.query=bloomSeconds(CONFIG.autoHunt.queryIntervalMs);
 return best;
}
// undefined leaves manual-mode targeting alone; null means wait for our target.
function autoHuntPrimaryTarget(){if(!autoHunt.enabled)return undefined;const t=idMap.get(autoHunt.target);return autoHuntValid(t)&&moaSeedTarget(t)?t:null}
function autoHuntInput(dt){
 const m=state.mother;if(regionAt(m.x,m.y)!==autoHunt.room){setAutoHunt(false);return{x:0,y:0}}
 autoHunt.query-=dt;let t=idMap.get(autoHunt.target);
 if(autoHunt.query<=0||autoHunt.target&&!autoHuntValid(t))t=autoHuntSelect();
 if(!t){autoHunt.moving=false;autoHunt.status='waiting';return{x:0,y:0}}
 const distance=dist(m,t),stop=Math.max(1,CONFIG.moa.rangedReach-CONFIG.autoHunt.rangeInset);
 if(distance<=stop||!autoHunt.moving&&distance<=stop+CONFIG.autoHunt.stopBand){autoHunt.moving=false;autoHunt.status='attacking';return{x:0,y:0}}
 const p=safeRoomPoint(autoHunt.room,t.x,t.y,moaBodyRadius(m)),dx=p.x-m.x,dy=p.y-m.y,length=Math.hypot(dx,dy);
 const travel=Math.min(length,Math.max(0,distance-stop)),speed=CONFIG.motion.motherSpeed*Math.max(dt,CONFIG.sim.fixedStep);
 autoHunt.moving=travel>0;autoHunt.status=travel>0?'moving':'attacking';
 return length?{x:dx/length*Math.min(1,travel/speed),y:dy/length*Math.min(1,travel/speed)}:{x:0,y:0};
}
// Keep knockback and the contact solver inside the pinned room, including open
// gates. This is a body constraint, not a teleport or an alternative movement path.

function resetIdleAuto(){autoHunt.idleMs=CONFIG.autoHunt.idleMs;setAutoHunt(!state.dead&&state.mother.hp>0)}




refreshUI=function(){if(bloomInTick){bloomEmit("refreshUI",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;autoHuntCore.refreshUI();refreshAutoHunt()};
