'use strict';
// Real Screen Wake Lock only. No synthetic input/media or device setting changes.
// A single async pump serializes request/release, including stale request results.
const screenAwake={wanted:false,revision:0,attempt:-1,held:null,busy:false,status:'off',pageHidden:false};
const screenAwakeCore={refreshAutoHunt,closeModal};
function screenAwakeEligible(){return !!(WorldView.auto().enabled&&playing&&!WorldView.dead()&&WorldView.leader().hp>0&&(!paused||['growth','ability'].includes(modalKind))&&!screenAwake.pageHidden&&document.visibilityState==='visible')}
function renderScreenAwake(){}
function syncScreenAwake(retry=false){
 const wanted=screenAwakeEligible();
 if(wanted!==screenAwake.wanted||retry){screenAwake.wanted=wanted;screenAwake.revision++;if(!wanted)screenAwake.status='off'}
 if(!screenAwake.busy)void pumpScreenAwake();
 renderScreenAwake();
}
async function pumpScreenAwake(){
 if(screenAwake.busy)return;screenAwake.busy=true;
 try{
  for(;;){
   if(screenAwake.held&&!screenAwake.wanted){const old=screenAwake.held;screenAwake.held=null;try{await old.release()}catch{}continue}
   if(!screenAwake.wanted||screenAwake.held||screenAwake.attempt===screenAwake.revision)break;
   const rev=screenAwake.revision;screenAwake.attempt=rev;
   if(!window.isSecureContext){screenAwake.status='insecure';break}
   if(!navigator.wakeLock||typeof navigator.wakeLock.request!=='function'){screenAwake.status='unsupported';break}
   screenAwake.status='pending';renderScreenAwake();
   try{
    const lock=await navigator.wakeLock.request('screen');
    // OFF/background/restart while the promise was pending must not leak a lock.
    if(rev!==screenAwake.revision||!screenAwakeEligible()){try{await lock.release()}catch{}continue}
    if(lock.released){screenAwake.status='released';break}
    screenAwake.held=lock;screenAwake.status='active';
    lock.addEventListener('release',()=>{if(screenAwake.held!==lock)return;screenAwake.held=null;screenAwake.status=screenAwake.wanted?'released':'off';renderScreenAwake()},{once:true});
   }catch(e){if(rev===screenAwake.revision&&screenAwake.wanted)screenAwake.status='denied'}
  }
 }finally{screenAwake.busy=false;renderScreenAwake()}
}
refreshAutoHunt=function(){if(bloomInTick){bloomEmit("refreshAutoHunt",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;screenAwakeCore.refreshAutoHunt();syncScreenAwake()};
closeModal=function(){if(bloomInTick){bloomEmit("closeModal",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;const result=screenAwakeCore.closeModal();syncScreenAwake();return result};
function initializeScreenAwakeUI(){
 GameUI.cleanup(()=>{screenAwake.pageHidden=true;syncScreenAwake()});
 GameUI.listen(document,'visibilitychange',()=>syncScreenAwake());
 GameUI.listen(window,'pagehide',()=>{screenAwake.pageHidden=true;syncScreenAwake()});
 GameUI.listen(window,'pageshow',()=>{screenAwake.pageHidden=false;syncScreenAwake(true)});
 Object.defineProperty(window.__army,'screenAwake',{get:()=>({wanted:screenAwake.wanted,status:screenAwake.status,held:!!screenAwake.held,busy:screenAwake.busy})});
 Object.assign(window.__army,{syncScreenAwake,closeModal});syncScreenAwake();
};

