// change: entity statistics, local physics, respawn rules and time stay intact.
CONFIG.huntingSpace={schema:1,width:4100,height:2400,terrainTileWidth:1024,
 rooms:[{x:48,y:48,w:1000,h:2304},{x:1048,y:48,w:1250,h:1152},{x:1048,y:1200,w:1250,h:1152},{x:2298,y:48,w:1754,h:1502},{x:2298,y:1550,w:1754,h:802}],
 gates:[{a:0,b:1,x:1048,y:600,vertical:true},{a:0,b:2,x:1048,y:1800,vertical:true},{a:1,b:3,x:2298,y:600,vertical:true},{a:2,b:3,x:2298,y:1375,vertical:true},{a:3,b:4,x:3175,y:1550,vertical:false}],
 packPitch:380,packRadius:170,clusterFromRoom:1};
