attackPower=function(u){return eliteCore.attackPower(u)*(isEncounterElite(u)?CONFIG.eliteEncounter.basicDamage:1)};
killReward=function(u,...args){const r=eliteCore.killReward(u,...args);return isEncounterElite(u)?r.map(n=>Math.round(n*CONFIG.eliteEncounter.reward)):r};
