'use strict';
// Shared fixed-tick movement policy. Hunting only changes owned permanent allies.
CONFIG.permanentHunt={queryInterval:.3,claimedDistancePenalty:130,reservedDistancePenalty:100000};
const permanentHuntCore={findTarget,canTarget,showMap,showCards};
const companionPolicies={hunt:{hunting:true,returning:false},follow:{hunting:false,returning:false},return:{hunting:false,returning:true}};
