 for(const t of I.candidates){if(!canTarget(u,t))continue;const n=(I.claims.get(t.id)||0)-(I.owners.get(u.id)===t.id?1:0),s=dist(u,t)+Math.max(0,n)*C.claimedDistancePenalty+(moaReserved(t)?C.reservedDistancePenalty:0);if(s<score||s===score&&t.id<(best?.id??Infinity)){score=s;best=t}}
