// Rivals keep the enemy art channel but have independent combat identities.
CONFIG.rivalMoa={schema:2,chance:.005,baseHP:180,baseAttack:28,reward:8,query:.35,huntRadius:720,windup:.3,travelQuery:2,minFarmTime:20,minFarmKills:8,readyHealth:.75,retreatHealth:.35,color:'#df9fe8'};
