function rivalColorIndex(id){let h=(id^0x9e3779b9)>>>0;h=Math.imul(h^(h>>>16),0x21f0aaad);h=Math.imul(h^(h>>>15),0x735a2d97);return ((h^(h>>>15))>>>0)%RIVAL_PALETTES.length}
