function factionId(u){return u?.playerId?'player:'+u.playerId:u?.factionId|| (u?.team==='friendly'?'player':u?.rivalOwner?'rival:'+u.rivalOwner:'wild')}
function sameFaction(a,b){return !!a&&!!b&&factionId(a)===factionId(b)}
