function rivalCapacity(u){return effectiveCapacity({capTier:Math.min(CONFIG.campaign.population.maxTier,u.rival.growth.choices),campaign:{abilities:u.rival.abilities}})}
// Source camp/type/reservation never move: they remain the one population slot.
