 if(g.vertical){x=g.x+(r.x>=g.x?cross:-cross);y=g.y;if(Math.abs(u.y-g.y)>CONFIG.rectWorld.gateWidth/2-moaBodyRadius(u)-15&&Math.abs(u.x-g.x)<cross+20)x=g.x+(u.x<g.x?-cross:cross)}
 else{x=g.x;y=g.y+(r.y>=g.y?cross:-cross);if(Math.abs(u.x-g.x)>CONFIG.rectWorld.gateWidth/2-moaBodyRadius(u)-15&&Math.abs(u.y-g.y)<cross+20)y=g.y+(u.y<g.y?-cross:cross)}return{x,y};
