function growthScaleAt(n){const C=CONFIG.exponentialGrowth,x=C.multiplier**Math.floor(n/C.purchasesPerStep);return Number.isSafeInteger(x)&&x*C.basePrice<=ECONOMY_NUMBER_LIMIT?x:null}
