growthCost=function(){const g=growthState();return g?.draft?.cost??growthCostAt(g?.choices||0)};
// A purchase adds its fixed 50-mineral card value, once per price unit.
// Never multiply the accumulated stat or a previous purchase's increment.
function growthPriceScale(cost){return cost===null?null:cost/CONFIG.exponentialGrowth.basePrice}
function growthOfferScale(g=growthState()){return g.draft?growthPriceScale(g.draft.cost):growthPriceScale(growthCostAt(g.choices))}
// Current saves start with explicit earned credits. No historical economy
