statRankSum=function(stat,g=growthState()){let total=0;for(const c of statCardsByStat[stat]||statNoCards)total+=economyPoint(g,c.id)*(CONFIG.statTiers.tiers[c.tier]?.power||1);return total};
statSpecialSum=function(stat,g=growthState()){let total=0;for(const c of statCardsByStat[stat]||statNoCards)total+=economyPoint(g,c.id)*(CONFIG.statTiers[stat]?.[c.tier]||0);return total};
growthSoftRank=function(n){return n};
