function economyAward(g,id,scale){scale=economyGain(g,id,scale);const before=economyPoint(g,id),after=before+scale;if(!Number.isFinite(after)||after<=before||after>ECONOMY_NUMBER_LIMIT/100)throw Error('numeric precision limit');g.economy.points[id]=after;}
