 if(a===b)return `${a.toLocaleString('ko-KR',{maximumSignificantDigits:17})}${suffix} · 수치 표현 정밀도 한계`;
 const digits=Math.min(20,Math.max(2,Math.ceil(-Math.log10(diff))+1));
 const format=n=>Number(n.toFixed(digits)).toLocaleString('ko-KR',{maximumFractionDigits:digits});
 let left=format(a),right=format(b);
