  if(id==='pod'){box(-.18,-.12,.33,.24,'#8fa779');box(.08,-.08,.17,.16,'#d4cf9a');oval(.235,0,.035,.066,'#525e48');box(-.12,-.07,.09,.14,'#dbce9b')}
