function gearProjectedPoint(p){return{x:p.x,y:p.y-(p.z||0)*WorldProjection.H/WorldProjection.K}}
// Direct reuse of Rally's electricArc sine envelope and three-pass stroke.
function drawGearArc(link,seed,time){const from=gearProjectedPoint(link),to=gearProjectedPoint({x:link.x2,y:link.y2,z:link.z2}),dx=to.x-from.x,dy=to.y-from.y,d=Math.hypot(dx,dy)||1,n=clamp(Math.ceil(d/28),4,14),amp=clamp(d*.085,8,26);for(const [color,w,alpha]of [['#397b94',4.8,.46],['#b8efff',2.1,.96],['#f3fcff',.72,.88]]){ctx.strokeStyle=color;ctx.lineWidth=w;ctx.globalAlpha=alpha;ctx.beginPath();ctx.moveTo(from.x,from.y);for(let i=1;i<n;i++){const q=i/n,o=(Math.sin(time*34+i*2.71+seed*.013)*.72+Math.sin(time*15+i*7.93+seed*.031)*.28)*amp*Math.sin(q*Math.PI);ctx.lineTo(from.x+dx*q-dy/d*o,from.y+dy*q+dx/d*o)}ctx.lineTo(to.x,to.y);ctx.stroke()}}
// Rally fireAntBreath uses 520 emissions/sec and .30–.48 s lifetimes (up to
// 220 packets). Analytically sample 144 overlapping packets instead: no emitter
// state, particles, RNG calls or per-frame allocations enter the simulation.
// Scratch is presentation-only, shared sequentially between visible emitters.
const gearFlameScratch=new Float64Array(144*7);
function drawGearBreath(p,time){
 const owner=gearOwner(p),tip=owner?MoaArt.muzzle(presentationPose(owner),'breath',p.angle):p;
 const H=WorldProjection.H/WorldProjection.K,K=WorldProjection.K,ground=spatialGround(tip.x,tip.y),ca=Math.cos(p.angle),sa=Math.sin(p.angle);
 const phase=time+(p.shotId%97)*.037;
 // Interpolate visual channel age with the same confirmed render clock used by
 // the owner; warmup grows out from the nozzle instead of popping a full cone.
 const elapsed=Math.max(0,bloomSeconds(p.ageMs)),warmup=clamp((elapsed+.02)/.38,0,1);
 // Thin connected tongues fill gaps at the nozzle without painting an opaque
 // cone. Outer cone stays porous so units and ground warnings remain readable.
 for(let band=0;band<3;band++){
  const reach=p.range*(band===0?.83:band===1?.67:.32)*warmup,width=band===0?10:band===1?6.5:2.8;
  ctx.fillStyle=band===0?'#d94718':band===1?'#ff9b32':'#fff09a';ctx.globalAlpha=band===0?.24:band===1?.38:.72;ctx.beginPath();
  for(let side=-1;side<=1;side+=2)for(let j=0;j<=14;j++){
   const q=(side<0?j:14-j)/14,d=reach*q,envelope=Math.sin(Math.PI*q),sway=Math.sin(q*10-phase*17)*envelope*(2+band),lateral=sway+side*(.7+width*envelope)*(1-q*.3),x=tip.x+ca*d-sa*lateral,y=tip.y+sa*d+ca*lateral,z=tip.z+(spatialGround(x,y)-ground)*q;
   const py=y-z*H;if(side<0&&j===0)ctx.moveTo(x,py);else ctx.lineTo(x,py);
  }ctx.closePath();ctx.fill();
 }
 for(let i=0;i<144;i++){
  // Stratified deterministic packet attributes, matching Rally's center-heavy
  // spread, .70–1 travel range, sine size envelope, jitter and fading tips.
  const seed=i*2.39996323,unit=((i*73%145)/144)*2-1,center=1-Math.abs(unit),life=.30+.18*(i*47%143)/142;
  const q=(phase/life+i/144)%1;
  if(q*life>elapsed+.02){gearFlameScratch[i*7+6]=-1;continue;}
  const travel=Math.pow(q,.94),off=unit*Math.abs(unit)**.48*p.halfAngle+Math.sin(q*Math.PI*2+seed+time*6)*p.halfAngle*.024*(.2+.8*q);
  const a=p.angle+clamp(off,-p.halfAngle*.995,p.halfAngle*.995),dx=Math.cos(a),dy=Math.sin(a),distance=p.range*(.70+.30*(i*31%143)/142)*travel;
  const jitter=(Math.sin(seed)*(2+6.5*travel)+Math.sin(seed*.013+q*11)*1.6)*Math.sin(Math.PI*travel);
  const x=tip.x+dx*distance-dy*jitter,y=tip.y+dy*distance+dx*jitter,z=tip.z+(spatialGround(x,y)-ground)*travel;
  const size=(3.8+5.8*Math.sin(Math.PI*q))*(.84+.34*(i*19%143)/142)*(.70+.30*center),fade=clamp(q/.05,0,1)*clamp((1-q)/.14,0,1);
  // Stretch along travel to join packets, rather than inflate the whole cone.
  const pa=WorldProjection.angle(a),ux=Math.cos(pa),uy=Math.sin(pa)/K,vx=-Math.sin(pa),vy=Math.cos(pa)/K,s=size*Math.sqrt(fade),at=i*7;
  gearFlameScratch[at]=x;gearFlameScratch[at+1]=y-z*H;gearFlameScratch[at+2]=ux*s*1.75;gearFlameScratch[at+3]=uy*s*1.75;gearFlameScratch[at+4]=vx*s*.55;gearFlameScratch[at+5]=vy*s*.55;gearFlameScratch[at+6]=q<.24?0:q<.58?1:2;
 }
 // Three batched paths, rather than save/rotate/fill/restore per packet.
 // Draw cooler plume first, retaining the hot center over the orange body.
 for(let color=2;color>=0;color--){ctx.fillStyle=color===0?'#fff09a':color===1?'#ff9b32':'#d94718';ctx.globalAlpha=color===0?.78:color===1?.72:.56;ctx.beginPath();
  for(let i=0;i<144;i++){const at=i*7;if(gearFlameScratch[at+6]!==color)continue;const x=gearFlameScratch[at],y=gearFlameScratch[at+1],ux=gearFlameScratch[at+2],uy=gearFlameScratch[at+3],vx=gearFlameScratch[at+4],vy=gearFlameScratch[at+5];ctx.moveTo(x+ux*.78,y+uy*.78);ctx.lineTo(x-ux*.48-vx,y-uy*.48-vy);ctx.lineTo(x-ux*.72,y-uy*.72);ctx.lineTo(x-ux*.48+vx,y-uy*.48+vy);ctx.closePath();}ctx.fill();
 }
 // Only four tiny embers beyond the cooling lobes; these are not the breath.
 ctx.fillStyle='#ffc16a';ctx.globalAlpha=.63;ctx.beginPath();for(let i=0;i<(warmup>=1?4:0);i++){const q=(phase*1.8+i/4)%1,d=p.range*(.72+.24*q),a=p.angle+Math.sin(i*4.7)*p.halfAngle*.8,x=tip.x+Math.cos(a)*d,y=tip.y+Math.sin(a)*d,z=tip.z+(spatialGround(x,y)-ground)*q;ctx.rect(x,y-z*H,1.1,1.1/K)}ctx.fill();
}

function drawEquippedAttack(p){return weaponDrawAdapter(p)}
drawProjectedProjectile=function(source){if(!source.equippedAttack)return equippedCore.drawProjectedProjectile(source);if(projectionVisible(source,Math.max(source.range||0,source.fieldRadius||0)+80))drawEquippedAttack(presentationPose(source,'projectile'))};
