'use strict';
// Paid growth is an army ledger. Moa's independent level/weapon progression is
// untouched. This derived cache is never serialized and has no gameplay RNG.
CONFIG.armyGrowth={attack:{silver:.10,gold:.15,prismatic:.20},hp:{silver:.10,gold:.15,prismatic:.20},speed:{silver:.05,gold:.08,prismatic:.12},range:{silver:.05,gold:.08,prismatic:.12},regen:{silver:.0025,gold:.005,prismatic:.0075}};
CONFIG.combatStats={movePercent:{silver:3,gold:5,prismatic:8},haste:{silver:5,gold:8,prismatic:12},armor:{silver:3,gold:5,prismatic:8}};
CONFIG.statTiers.critical={gold:.03,prismatic:.05};CONFIG.statTiers.lifesteal={gold:.01,prismatic:.02};CONFIG.statTiers.criticalPower={prismatic:.1};
const armyGrowthCache=new WeakMap();
function armyCardSum(stat,table,g){let n=0;for(const c of statCardsByStat[stat]||statNoCards)n+=economyPoint(g,c.id)*(table[c.tier]||0);return n}
const armyGrowthCore={attackPower,effectiveRange,effectiveSpeed,permanentMaxHP,tickUnitStatus,economyAward:combatStatsCore.economyAward,currentMoaStats};
const armyCurve={critical:moaCriticalChance,lifesteal:moaLifesteal,criticalDamage:moaCriticalMultiplier,regen:growthRecovery};
function armyBonuses(g=growthState()){
 if(!g)return null;let b=armyGrowthCache.get(g);if(b)return b;
 b=Object.freeze({attack:armyCardSum('bash',CONFIG.armyGrowth.attack,g),hp:armyCardSum('vital',CONFIG.armyGrowth.hp,g),range:armyCardSum('reach',CONFIG.armyGrowth.range,g),speed:armyCardSum('rhythm',CONFIG.armyGrowth.speed,g),regen:armyCardSum('renew',CONFIG.armyGrowth.regen,g),critical:armyCurve.critical(g),criticalDamage:armyCurve.criticalDamage(g),lifesteal:armyCurve.lifesteal(g),move:combatStat('movePercent',g),haste:combatStat('haste',g),armor:combatStat('armor',g)});armyGrowthCache.set(g,b);return b;
}
function armyGrowthFor(u){if(!u||u.type==='mother'||u.rivalLeader)return null;if(u.team==='friendly')return WorldPlayers.dataFor(u)?.campaign?.growthCards||growthState();if(u.rivalRecruit)return idMap.get(u.rivalOwner)?.rival?.growth||u.armyGrowth||null;return null}
function armyFor(u){return armyBonuses(armyGrowthFor(u))}
function armyBaseHP(u){return u.permanentRank?u.permanentBaseHP:u.armyBaseHP}
function armySyncHP(u){const b=armyFor(u);if(!b)return;CombatHealth.rescaleMaximum(u,Math.min(CONFIG.sim.unitHpLimit,armyBaseHP(u)*(1+b.hp)))}
// Purchases update live and sleeping bodies once, preserving wounds and timers.
// Detached card previews never reach this branch.
economyAward=function(g,id,scale){const old=armyBonuses(g);armyGrowthCore.economyAward(g,id,scale);armyGrowthCache.delete(g);const next=armyBonuses(g);if(g!==growthState()&&!state.units.some(u=>u.rivalLeader&&u.rival.growth===g))return;
 const apply=u=>{if(armyGrowthFor(u)!==g)return;if(u.rivalRecruit)u.armyGrowth=g;armySyncHP(u);const c=u.attackController;if(c&&old.haste!==next.haste){const ratio=(1+old.haste/100)/(1+next.haste/100);AttackPatternController.rescale(c,ratio)}};
 for(const u of state.units)apply(u);if(g===growthState())for(const r of Object.values(permanentState()?.records||{}))if(r.body)apply(r.body);
};

permanentMaxHP=function(type,rank,baseHP){return Math.min(CONFIG.sim.unitHpLimit,armyGrowthCore.permanentMaxHP(type,rank,baseHP)*(1+(armyBonuses()?.hp||0)))};
attackPower=function(u){return armyGrowthCore.attackPower(u)*(1+(armyFor(u)?.attack||0))};
effectiveRange=function(u){return armyGrowthCore.effectiveRange(u)*(1+(armyFor(u)?.range||0))};
effectiveSpeed=function(u){return armyGrowthCore.effectiveSpeed(u)*(1+(armyFor(u)?.move||0)/100)};
function armyAttackInterval(u,base=unitDef(u.type).cooldownMs/1000){const b=armyFor(u),tick=bloomSeconds(BLOOM_TIME.weapons.cardMinimumMs);return b?tick+Math.max(0,base-tick)/(1+b.speed):base}
function armyAttackWindup(u,base){const b=armyFor(u);return b?Math.max(bloomSeconds(BLOOM_TIME.weapons.cardMinimumMs),base/(1+b.speed)):base}
function armySpecialCooldown(u,base){return base/(1+(armyFor(u)?.haste||0)/100)}
tickUnitStatus=function(u,dt){armyGrowthCore.tickUnitStatus(u,dt);const b=armyFor(u);if(!state.dead&&u.hp>0&&b?.regen)applyHealing(u,Math.min(u.maxHp,u.hp+armyBaseHP(u)*b.regen*dt))};



// No mineral card is consulted by either leader's combat stats or morphology.
growthVitalBonus=()=>0;growthBashBonus=()=>0;growthRecovery=()=>0;
growthInterval=()=>CONFIG.moa.cooldown;growthReach=()=>235;
maxMotherHP=()=>CONFIG.mother.hp;statBaseMoaPower=()=>CONFIG.moa.attack;
moaCriticalChance=()=>0;moaCriticalMultiplier=()=>CONFIG.statTiers.baseCriticalMultiplier;moaLifesteal=()=>0;
moaWalkSpeed=()=>CONFIG.motion.motherSpeed;moaAbilityCooldown=base=>base;
moaArmorMultiplier=()=>1;combatGrowthFor=()=>null;
moaTargetSize=()=>CONFIG.mother.size*moaLevelScale();
// Crit-damage eligibility belongs to the army chance, not Moa's zero chance.
statCardEligible=function(c,g=growthState()){const scale=growthOfferScale(g);return !!c?.tier&&(g?.ranks?.[c.id]||0)<c.max&&scale!==null&&Number.isFinite(scale)&&scale>0&&economyPoint(g,c.id)+scale<=ECONOMY_NUMBER_LIMIT/100&&(c.stat!=='criticalPower'||armyBonuses(g).critical>0)};
for(const c of GROWTH_CARDS)if(c.stat){c.kind='army';if(c.stat==='bash')c.name='병력의 강한 일격';if(c.stat==='reach')c.name='병력의 긴 사거리';if(c.stat==='movePercent')c.name='병력의 빠른 발걸음'}
growthMilestone=function(){const g=growthState(),next=Math.max(cap(),CONFIG.progression.caps[Math.min(5,g.choices+1)]);return `병력 전체 강화 · 인구 ${cap()}${next>cap()?' → '+next:' 유지'} · 모아는 레벨업으로 성장`};
growthCardEffect=function(c){const b=armyBonuses(),n=armyBonuses(statPreviewGrowth(c)),delta=(key,scale=1,suffix='')=>statNextText(b[key],n[key],scale,suffix),prefix=c.stat==='haste'?'영구병 특수기':'병력 전체';
 const texts={bash:()=>`개체 원본 공격력 대비 +${delta('attack',100,'%')}`,vital:()=>`개체 원본 최대 체력 대비 +${delta('hp',100,'%')} · 현재 체력 비율 유지`,reach:()=>`원본 기본 공격 사거리 대비 +${delta('range',100,'%')}`,rhythm:()=>`기본 공격 가속 +${delta('speed',100,'%')} · 병종별 기본 간격·예비 동작 단축, 최소 1틱`,renew:()=>`각 병력 원본 최대 체력의 ${delta('regen',100,'%')} / 초 회복 · 최대 체력까지만`,critical:()=>`치명타 확률 ${delta('critical',100,'%')}`,criticalPower:()=>`치명타 피해 ${delta('criticalDamage',1,'배')}`,lifesteal:()=>`흡혈 ${delta('lifesteal',100,'%')} · 자기 공격의 실제 체력 피해로 자신을 회복`,movePercent:()=>`기본 이동 속도 대비 +${delta('move',1,'%')}`,haste:()=>`스킬 가속 +${delta('haste')} · 재사용 대기 ÷ (1 + 가속/100), 일반병 기본 공격·모아 제외`,armor:()=>`방어력 +${delta('armor')} · 기존 피해 × 100/(100 + 방어력)`};return `${prefix} · ${(texts[c.stat]||(()=>''))()}`;
};
currentMoaStats=function(){const s=armyGrowthCore.currentMoaStats();s.moveBonus=s.haste=s.armor=0;return s};
function currentArmyStatsHTML(){const b=armyBonuses(),rows=[['원본 공격력 대비','+'+fmt(b.attack*100)+'%'],['원본 최대 체력 대비','+'+fmt(b.hp*100)+'%'],['원본 사거리 대비','+'+fmt(b.range*100)+'%'],['기본 공격 가속',fmt(b.speed*100)+'%'],['이동 속도 추가',fmt(b.move)+'%'],['체력 재생','원본 체력의 '+fmt(b.regen*100)+'% / 초'],['치명타 확률',fmt(b.critical*100)+'%'],['치명타 피해',fmt(b.criticalDamage)+'배'],['흡혈',fmt(b.lifesteal*100)+'%'],['방어력',fmt(b.armor)],['영구병 특수기 가속',fmt(b.haste)]];return '<h3>병력 전체 · 광물 성장</h3><div class="moaStatsRows">'+rows.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')+'</div><p class="fine">일반병과 영구병에 적용되며 새로 영입한 병력도 이어받아요. 체력·공격력·사거리의 기본값은 병종·영입 지역·압축 전투력에 따라 달라요. 공격력·체력·사거리·재생 비율은 각 원본에 한 번 적용하고, 기존 강화된 수치를 재곱하지 않습니다. 스킬 가속은 영구병 특수기의 재사용 대기에만 적용됩니다.</p>'}
currentMoaStatsHTML=function(){const s=currentMoaStats(),rows=[['레벨',s.level],['체력',fmt(s.hp)+' / '+fmt(s.maxHP)],['공격력',fmt(s.attack)],['주 공격 피해',fmt(s.primaryDamage)],['이동 속도',fmt(s.speed)+' / 초'],['주 공격 사거리',fmt(s.range)],['공격 간격',fmt(s.attackInterval)+'초'],['치명타 확률',fmt(s.critical*100)+'%'],['치명타 피해',fmt(s.criticalDamage)+'배'],['체력 재생',fmt(s.regenTotal)+' / 초'],['흡혈',fmt(s.lifesteal*100)+'%'],['방어력',s.armor],['구르기 재사용',fmt(s.rollSeconds)+'초'],...s.aux.map(a=>[a.name,fmt(a.seconds)+'초'])];return '<h3>모아 · 레벨업 성장</h3><div class="moaStatsRows">'+rows.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')+'</div><p class="fine">광물 카드는 모아에게 적용되지 않아요. 레벨마다 기본 공격력이 자라며 10레벨마다 2배가 됩니다. 모든 보조 무기도 이 기본 위력을 사용해요. 최대 체력은 레벨마다 50씩 늘고 남은 체력 비율을 유지해요. 방어력은 늘지 않으며 기본 재생은 최대 체력의 0.5%입니다. 모아가 실제로 맞힌 일반 적은 7초간 ✦ 표식이 남고, 그동안 내 일반병·영구병이 처치해도 인구 한도 안에서 영입됩니다. 기본 체력 재생은 최대 체력의 0.5% / 초입니다.</p>'+currentArmyStatsHTML()};

function publishArmyGrowthUI(){Object.assign(window.__army,{armyBonuses,armyGrowthFor,armyAttackInterval,armySpecialCooldown,currentMoaStats,currentMoaStatsHTML,currentArmyStatsHTML,attackPower,effectiveRange,effectiveSpeed,damage,growthCardEffect})};

'use strict';
// Region weight is captured once. Paid cards, wounds, and current combat stats
// never enter the 25-point material ledger or its resulting base power.
function permanentCaptureWeight(u){return u?.captureWeight||1}
function permanentMaterialWeight(materials){let n=0;for(const u of materials)n+=permanentCaptureWeight(u);return n}
function permanentBatchMaterials(type){const out=[];let weight=0;for(const u of permanentMaterials(type).sort((a,b)=>a.id-b.id)){out.push(u);weight+=permanentCaptureWeight(u);if(weight>=CONFIG.permanent.batch)break}return out}
function permanentBaselinePower(type){const d=unitDef(type),C=CONFIG.challenge,g=CONFIG.campaign.grounds[0],hp=d.hp*C.enemyHp*C.recruitFraction*g.hp,attack=d.atk*C.enemyAttack*C.recruitFraction*g.attack;return hp*permanentSingleTargetDPS(type,attack,false)}
permanentBatchPower=function(materials){if(!materials.length||materials.some(u=>u.type!==materials[0].type))return NaN;const weight=permanentMaterialWeight(materials);return weight>=CONFIG.permanent.batch?permanentBaselinePower(materials[0].type)*weight/CONFIG.permanent.batch:NaN};
permanentPowerDescription=function(r){const u=r&&(r.body||state.units.find(v=>v.id===r.id));return u?`체력 ${fmt(u.maxHp)} · 공격력 ${fmt(attackPower(u))} · 기준 병력 전투력 ${fmt(u.permanentPower/permanentBaselinePower(u.type))}개분`:''};
permanentCollectionHTML=function(){const batch=CONFIG.permanent.batch;return `<section class="permanentCollection"><h3>같은 병종 가중치 ${batch} → 영구 동료 +1</h3><p>살아 있는 일반 동료만 셉니다. 영입 지역의 기본 배율 1·2·4·8·16…이 각 동료의 압축 가중치예요. 1+2+4는 7입니다. 오래된 동료부터 가중치 ${batch} 이상이 되는 최소 묶음을 자동 압축해요.</p>${friendlyTypes.map(type=>{const r=permanentRecord(type),units=permanentMaterials(type),weight=permanentMaterialWeight(units),chosen=permanentBatchMaterials(type),consumed=permanentMaterialWeight(chosen),ready=weight>=batch;return `<div class="permanentRow"><img alt="" src="${portrait(type)}"><div><strong>${unitDef(type).name}${r?' · 영구 +'+r.rank:''}</strong><small>압축 가중치 <b>${fmt(weight)} / ${batch}</b> · 실제 ${units.length}마리</small><div class="compressionProgress"><i style="width:${Math.min(100,weight*100/batch)}%"></i></div><small>${ready?`다음 압축 ${chosen.length}마리 · 가중치 ${fmt(consumed)} · 기준 전투력 +${fmt(consumed/batch)}개분`:`가중치 ${fmt(batch-weight)} 더 모으면 자동 압축`}</small><small>${r?permanentPowerDescription(r):'첫 영구 동료를 기다리고 있어요'}${r?.body?`<br>부활까지 ${Math.ceil(r.remaining)}초`:r?' · 생존 중':''}</small></div></div>`}).join('')}<details class="compressionDetails"><summary>압축·전투력·부활 규칙</summary><p>가중치 16+8+4=28이면 세 동료를 모두 소모하고 기준 병력 전투력의 28/25=1.12개분을 누적합니다. 초과분을 버리거나 별도 잔여 포인트로 남기지 않아요. 영구 +단계는 압축 횟수이며 누적 전투력 개수와 다를 수 있어요.<br>기준 전투력은 첫 구역에서 영입한 해당 병종의 원본 체력 × 기본 단일 DPS입니다. 지역 배율은 가중치로 한 번만 반영하며, 재료의 현재 체력·광물 강화·공격 속도·치명타는 압축량을 바꾸지 않습니다. 누적 전투력에 맞춰 원본 체력·DPS가 같은 비율로, 제곱근에 비례해 커져요. 광물 성장은 그 원본 위에 한 번만 적용됩니다.<br>죽은 동료·영구 동료·도감 누적 수는 재료가 아닙니다. 영구 동료는 인구 0이며 쓰러져도 제자리에서 부활해요. ${friendlyTypes.map(type=>unitDef(type).name+' '+permanentReviveSeconds(type)+'초').join(' · ')}. 모아 부활 때는 부활 자리를 모아 주변으로 옮기고 남은 대기는 유지합니다. 오프라인 시간에는 진행되지 않아요.<br>몸집·기본 사거리 배율은 기존처럼 1+0.25×√압축 횟수입니다. 강화 시 현재 체력 비율을 유지해요. Lv.${CONFIG.permanent.capacityLevel}부터 인구 최소 ${CONFIG.permanent.capacityFloor} · 현재 ${cap()}.</p></details></section>`};

