'use strict';
// Level power is derived from the owning leader at fire time. No paid army
// ledger, permanent baseline, hit-time multiplier, or mutable cache is involved.
CONFIG.moaLevelPower={doublingLevels:10,hpPerLevel:50};
CONFIG.moaRecruitMark={seconds:7,color:'#d8f2a0'};
function moaLevelMultiplier(level){return Math.min(Number.MAX_VALUE,2**((Math.max(1,level)-1)/CONFIG.moaLevelPower.doublingLevels))}
function moaLevelBasePower(){return Math.min(Number.MAX_VALUE,CONFIG.moa.attack*moaLevelMultiplier(abilityState()?.level||1))}
statBaseMoaPower=()=>moaLevelBasePower();
function moaLevelHP(base,level=1){return base+CONFIG.moaLevelPower.hpPerLevel*(Math.max(1,level)-1)}
maxMotherHP=()=>moaLevelHP(CONFIG.mother.hp,state?.campaign?.abilities?.level||1);
rivalMaxHP=u=>moaLevelHP(u.rival.baseHP,u.rival.abilities.level);
function moaSyncLevelHP(u){if(!u)return;const next=u.rivalLeader?rivalMaxHP(u):PlayerActor.maxHP(WorldPlayers.forEntity(u));if(u.maxHp===next)return;CombatHealth.rescaleMaximum(u,next)}

const moaMarkCore={rivalPower,moaReserved,drawUnit,tickUnitStatus};
rivalPower=function(u){return Math.min(Number.MAX_VALUE,moaMarkCore.rivalPower(u)*moaLevelMultiplier(u.rival.abilities.level))};
// Machine representability guard only, at ~1.8e308; no gameplay/level cap.
// Descendants and ranked auxiliary products may exceed a finite base.
launchAbilityShot=function(t,amount,opts={}){return AbilityAttack.launch(t,amount,opts)};
function moaMarkWild(t){return !!t&&t.team==='enemy'&&!t.rivalOwner&&!t.rivalLeader&&!t.elite&&!t.boss&&!isEncounterElite(t)&&t.variant==='ordinary'&&t.camp>=0&&!!(bloomRendering()?bloomRenderWorld().camps:state.camps)[t.camp]?.enabled&&friendlyTypes.includes(t.type)}
function moaMarkOwner(id){const u=bloomRendering()?bloomRenderUnit(id):idMap.get(id)||WorldPlayers.byAccount(id)?.leader;return u&&u.hp>0&&(u.type==='mother'||u.rivalLeader)?u:null}
function moaHasRecruitMark(t,leader){return !!leader&&moaMarkWild(t)&&!!t.moaRecruitMarks?.some(q=>q.ownerId===leader.id&&q.faction===factionId(leader)&&q.until>state.time)}
function moaMarkHit(source,t){
 const owner=source?.id===-1?state.mother:idMap.get(source?.id);
 if(!owner||!moaMarkOwner(owner.id)||!(owner.type==='mother'||owner.rivalLeader)||!sameFaction(owner,source)||!moaMarkWild(t))return;
 const marks=(t.moaRecruitMarks||[]).filter(q=>q.until>state.time&&moaMarkOwner(q.ownerId));let mark=marks.find(q=>q.ownerId===owner.id);
 if(mark)mark.until=state.time+CONFIG.moaRecruitMark.seconds;else marks.push({ownerId:owner.id,faction:factionId(owner),until:state.time+CONFIG.moaRecruitMark.seconds});
 t.moaRecruitMarks=marks;
}
function moaMarkedKill(t,killer,leader){return !!killer&&!!moaMarkOwner(leader?.id)&&sameFaction(killer,leader)&&moaHasRecruitMark(t,leader)}
// A valid marked army kill must not be held at 1 HP by the old finisher guard.
moaReserved=function(t){return !moaHasRecruitMark(t,moaMarkOwner(-1))&&moaMarkCore.moaReserved(t)};
tickUnitStatus=function(u,dt){moaMarkCore.tickUnitStatus(u,dt);if(u.moaRecruitMarks){u.moaRecruitMarks=u.moaRecruitMarks.filter(q=>q.until>state.time&&moaMarkOwner(q.ownerId));if(!u.moaRecruitMarks.length)delete u.moaRecruitMarks}};
// One small marker per target even if several rival leaders have touched it.
// Player ownership wins only the presentation color, never kill attribution.
drawUnit=function(u,options={}){moaMarkCore.drawUnit(u,options);if(u.hp<=0||!projectionVisible(u,unitVisualExtent(u)+35)||!moaMarkWild(u))return;const marks=u.moaRecruitMarks;if(!marks)return;const q=marks.find(q=>q.ownerId===-1&&q.until>bloomRenderWorld().time&&moaMarkOwner(q.ownerId))||marks.find(q=>q.until>bloomRenderWorld().time&&moaMarkOwner(q.ownerId));if(!q)return;WorldUI.draw('label',presentationPose(u),{text:'✦',extent:unitVisualExtent(u),gap:18,font:'bold 12px system-ui',color:q.ownerId===-1?CONFIG.moaRecruitMark.color:rivalPalette(moaMarkOwner(q.ownerId)).hex})};
function validMoaRecruitMarks(u,v){if(u.moaRecruitMarks===undefined)return true;const marks=u.moaRecruitMarks;if(!Array.isArray(marks)||new Set(marks.map(q=>q?.ownerId)).size!==marks.length)return false;return marks.every(q=>{if(!q||!Number.isSafeInteger(q.ownerId)||!Number.isFinite(q.until)||q.until<0||q.until>v.time+CONFIG.moaRecruitMark.seconds+1e-7)return false;const player=WorldPlayers.byAccount(q.ownerId,v);return player?q.faction==='player:'+player.playerId:q.ownerId===-1?q.faction==='player':q.ownerId>0&&q.ownerId<=v.nextId&&q.faction==='rival:'+q.ownerId})}


function publishMoaMarkUI(){Object.assign(window.__army,{moaLevelHP,moaSyncLevelHP,maxMotherHP,rivalMaxHP,moaLevelMultiplier,moaLevelBasePower,moaHasRecruitMark,moaMarkHit,moaMarkedKill,validMoaRecruitMarks,moaPower,statBaseMoaPower,rivalPower,moaReserved,drawUnit,load})};

