let bloomDiskFailure=null;
const bloomDiskOldKeys=['bloom-open-world-v52','bloom-rarity-v44','bloom-army-moa-v38','bloom-army-moa-v37','bloom-army-moa-v5','bloom-army-moa-v4','bloom-army-farming-v3','bloom-army-section-one-v2','bloom-army-v1'];
function bloomOldDiskAvailable(){if(globalThis.BLOOM_HEADLESS)return false;try{return bloomDiskOldKeys.some(key=>!!localStorage.getItem(key))}catch{return false}}
function bloomDiskNotice(hasSave){const failure=BloomSimulation.runtime?.metrics.persistenceFailure;return !hasSave&&(failure||bloomOldDiskAvailable())?`<p class="notice">${failure?.message||'지원하지 않는 저장 버전이에요. 새 게임으로 시작해 주세요.'}<br>기존 데이터는 그대로 보관 중이에요.</p>`:''}
function bloomShowRejectedSave(){const failure=BloomSimulation.runtime?.metrics.persistenceFailure;openModal('reset',sheetHead(failure?.code==='UNSUPPORTED_SAVE_VERSION'?'지원하지 않는 저장 버전':'기존 저장을 불러오지 못했어요')+`<p>${failure?.message||'다른 백업을 불러오거나 새 게임으로 시작해 주세요.'}<br>원본 저장은 보관 중이에요. 새 게임을 확인하면 기존 저장이 교체됩니다.</p><button class="primary danger" data-action="reset">확인 · 새 게임 시작</button><button class="primary" data-action="import">다른 백업 불러오기</button><button class="tab" data-action="pause">취소</button>`)}

