'use strict';
// Called only at genuine recovery assignments. Preserve original healing rules.
// Events carry actual floating-point HP change, never nominal or max-HP growth.
function applyHealing(u,nextHP){return CombatHealth.heal(u,nextHP)}
CONFIG.healingNumbers={maxLabels:24,mergeSpan:.65,life:1.15,font:11,color:'#85f5ac',rise:18};
const healingNumbers={time:0,labels:[],drawn:0};
function healingClear(){if(bloomInTick){bloomEmit("healingClear",Array.from(arguments));return;}if(globalThis.BLOOM_HEADLESS)return;healingNumbers.labels.length=0;healingNumbers.time=0;healingNumbers.drawn=0}
function healingFormat(amount){
 if(amount>=1)return Number(amount.toFixed(1)).toLocaleString('en-US',{maximumFractionDigits:1});
 return Number(amount.toPrecision(2)).toString();
}
function healingActor(n){const u=bloomRendering()?bloomRenderUnit(n.id):n.id===-1?state.mother:idMap.get(n.id);return u&&u.hp>0&&u.type===n.type&&u.team===n.team&&(u.permanentDiedAt||0)===(n.deathAt||0)?u:null}
function healingCredit(source,amount){
 const G=healingNumbers,C=CONFIG.healingNumbers,now=G.time;
 const live=healingActor(source),a=WorldUI.anchor(live||source,{at:live?'body':'point'}),p=WorldUI.screen(a,{at:'point'});
 if(p.x<0||p.x>innerWidth||p.y<0||p.y>innerHeight)return;
 G.labels=G.labels.filter(n=>now<n.until);
 let n=G.labels.find(n=>n.id===source.id&&n.type===source.type&&n.team===source.team&&now-n.at<=C.mergeSpan&&!n.frozen);
 // Teleports start a separate batch; a sum never jumps across the map.
 if(n&&((a.x-n.x)**2+(a.y-n.y)**2>180**2)){n.frozen=true;n=null}
 if(!n){if(G.labels.length>=C.maxLabels)return;n={id:source.id,type:source.type,team:source.team,deathAt:source.deathAt||0,x:a.x,y:a.y,z:a.z,amount:0,at:now,until:now+C.life,visible:false,frozen:!live};G.labels.push(n)}
 n.amount+=amount;n.text='✚ +'+healingFormat(n.amount);
}
function healingDraw(c=ctx){
 const G=healingNumbers,C=CONFIG.healingNumbers;G.drawn=0;
 G.labels=G.labels.filter(n=>G.time<n.until);for(const n of G.labels)n.visible=false;
 if(!playing||paused)return;
 const dpr=Math.min(CONFIG.render.dprMax,devicePixelRatio||1);c.save();c.setTransform(dpr,0,0,dpr,0,0);
 c.font='bold '+C.font+'px system-ui';c.textAlign='center';c.textBaseline='middle';c.lineWidth=3;c.strokeStyle='#163a2cf2';c.fillStyle=C.color;
 for(const n of G.labels){
  const u=!n.frozen&&healingActor(n);
  if(u){const a=WorldUI.anchor(u,{at:'body'});if((a.x-n.x)**2+(a.y-n.y)**2>180**2)n.frozen=true;else Object.assign(n,{x:a.x,y:a.y,z:a.z})}else n.frozen=true;
  const p=WorldUI.screen({x:n.x,y:n.y,z:n.z},{at:'point'});if(p.x<0||p.x>innerWidth||p.y<0||p.y>innerHeight)continue;
  const age=(G.time-n.at)/C.life,w=c.measureText(n.text).width+8;
  // One bounded layout scheduler shares all existing damage/gold/HUD exclusions.
  const blockers=[...mineralGain.blockers,...hitfeel.numbers.filter(x=>x.layoutVisible&&x.layoutBounds).map(x=>x.layoutBounds),...mineralGain.labels.filter(x=>x.visible),...G.labels.filter(x=>x.visible)];
  let clear=false;
  for(let slot=0;slot<5;slot++){
   const x=p.x+(slot%2?1:-1)*(18+Math.floor(slot/2)*12),y=p.y-15-(mineralGain.reduced?0:C.rise*age)+Math.floor(slot/2)*14;
   Object.assign(n,{left:x-w/2,right:x+w/2,top:y-8,bottom:y+8});
   if(n.left<6||n.right>innerWidth-6||n.top<6||n.bottom>innerHeight-6)continue;
   if(!blockers.some(b=>mineralGainOverlaps(n,b,3))){clear=true;break}
  }
  if(!clear)continue;n.visible=true;G.drawn++;c.globalAlpha=Math.min(1,(1-age)/.3);const x=(n.left+n.right)/2,y=(n.top+n.bottom)/2;c.strokeText(n.text,x,y);c.fillText(n.text,x,y);
 }
 c.restore();
}
const healingCore={render};
render=function(alpha=1,dt=1/60){if(WorldView.animating())healingNumbers.time+=clamp(Number(dt)||0,0,.1);const result=healingCore.render(alpha,dt);healingDraw();return result};

