 const summary=ruiSummary(account),last=account.lastFusion,result=last?.attempts?`<div class="rarityFusionResult" role="status"><strong>최근 합성 · ${ruiEscape(unitDef(last.type)?.name||last.type)} ${ruiEscape(ruiName(last.grade))}</strong><span>${fmt(last.attempts)}회 시도 · 성공 ${fmt(last.successes)} · 실패 ${fmt(last.failures)}</span><span>${fmt(last.consumed)}마리 소모 · ${ruiEscape(ruiName(last.resultGrade))} ${fmt(last.produced)}마리 획득</span></div>`:'';
