currentMoaStatsHTML=function(){
 const s=currentMoaStats(),rows=[['레벨',s.level],['체력',ruiNumber(s.hp)+' / '+ruiNumber(s.maxHP)],['주 공격 피해',ruiNumber(s.primaryDamage)],['이동 속도',ruiNumber(s.speed)+' / 초'],['주 공격 사거리',ruiNumber(s.range)],['공격 간격',ruiNumber(s.attackInterval)+'초'],['체력 재생',ruiNumber(s.regenTotal)+' / 초'],['구르기 재사용',ruiNumber(s.rollSeconds)+'초'],...s.aux.map(a=>[a.name,ruiNumber(a.seconds)+'초'])];
 return '<h3>모아 · 레벨업 성장</h3><div class="moaStatsRows">'+rows.map(([k,v])=>`<div><span>${ruiEscape(k)}</span><b>${ruiEscape(v)}</b></div>`).join('')+'</div><p class="fine">체력 재생과 회복은 최대 체력까지만 적용돼요. 피해·회복 수치는 전투 중 표시돼요. 무료 능력은 기본 공격 특성과 자동 보조 무기를 함께 강화해요.</p>'+ruiSummaryHTML();
};
