function ruiDrawBadgeShape(c,x,y,r,grade){
 c.beginPath();
 if(grade===0)c.arc(x,y,r,0,Math.PI*2);
 else if(grade===1){c.moveTo(x,y-r*1.3);c.lineTo(x+r,y);c.lineTo(x,y+r*1.3);c.lineTo(x-r,y);c.closePath()}
 else{const count=grade===2?3:grade===3?6:grade===4?10:16,star=grade>=4;for(let i=0;i<count;i++){const angle=-Math.PI/2+i*Math.PI*2/count,rr=star&&i%2?r*.5:r;const px=x+Math.cos(angle)*rr,py=y+Math.sin(angle)*rr;if(i)c.lineTo(px,py);else c.moveTo(px,py)}c.closePath()}
 c.fill();
}
