drawUnit=function(unit,options={}){rarityUICore.drawUnit(unit,options)};
function ruiQueueReserve(count){
 const stack=ruiReserve(ruiAccount(),rarityUI.type,rarityUI.grade),next=Math.max(0,Math.min(stack.count||0,Math.floor(Number(count)||0)));
 rarityRequestReserveLock(rarityUI.type,rarityUI.grade,next);
}
function bindRarityUIControls(root=document){
 GameUI.listen(root,'click',ruiHandleClick,true);
 GameUI.listen(root,'keydown',event=>{if(event.key==='Enter'&&event.target.id==='rarityReserveLocked'){event.preventDefault();ruiQueueReserve(event.target.value);ruiRefreshCollection()}});
}
function ruiHandleClick(event){
 const button=event.target.closest('button');if(!button||button.disabled)return;const d=button.dataset;
 if(d.action==='reset-confirm'){
  event.preventDefault();event.stopImmediatePropagation();openModal('reset',sheetHead('새 모험을 시작할까요?')+'<p>현재 영구 군단 · 잠금 · 합성 진행 · 모아 레벨과 능력 · 탐험 기록이 초기화됩니다. 필요한 진행은 먼저 백업하세요.</p><button class="primary danger" data-action="reset">진행 초기화</button><button class="primary secondary" data-action="pause">취소</button>');return;
 }
 if(!Object.keys(d).some(key=>key.startsWith('rarity')))return;
 event.preventDefault();event.stopImmediatePropagation();
 if(d.raritySpecies!==undefined){rarityUI.type=d.raritySpecies;rarityUI.page=0;rarityUI.notice='';ruiRefreshCollection();return}
 if(d.rarityGrade!==undefined){rarityUI.grade=Number(d.rarityGrade);rarityUI.page=0;ruiRefreshCollection();return}
 if(d.rarityPage!==undefined){rarityUI.page=Math.max(0,Number(d.rarityPage)||0);ruiRefreshCollection();return}
 if(d.rarityFuse!==undefined){
  const grade=Number(d.rarityFuse),max=d.rarityMax==='true';rarityUI.grade=grade;rarityUI.page=0;
  rarityUI.notice=`${unitDef(rarityUI.type).name} · ${ruiName(grade)} ${max?'선택 등급 최대':'1회'} 합성`;
  rarityRequestFuse(rarityUI.type,grade,max);ruiRefreshCollection();return;
 }
 if(d.rarityLock!==undefined){rarityRequestLock(Number(d.rarityLock),d.rarityLocked==='true');ruiRefreshCollection();return}
 if(d.rarityReserveDelta!==undefined){const stack=ruiReserve(ruiAccount(),rarityUI.type,rarityUI.grade);ruiQueueReserve((stack.locked||0)+Number(d.rarityReserveDelta));ruiRefreshCollection();return}
 if(d.rarityReserveSet!==undefined){ruiQueueReserve(Number(d.rarityReserveSet));ruiRefreshCollection();return}
 if(d.rarityReserveApply!==undefined){ruiQueueReserve($('rarityReserveLocked')?.value);ruiRefreshCollection();return}
}
