// A death marker is a saved world point, never a predicted respawn location.
function ruiRevivalSeconds(remaining){return Math.max(0,Math.ceil(Math.min(bloomSeconds(CONFIG.rarity.respawnMs),remaining)-1e-9))}
function ruiRevivalPoint(record){
 if(!record.body)return null;
 // Older v44 saves have no explicit anchor; their retained body is authoritative.
 return record.deathPosition || {x:record.body.x,y:record.body.y,z:spatialHeight(record.body)};
}
WorldUI.define('rarityRevival',{anchor:{at:'point'},paint(c,a,s,d){
 const z=Math.max(.0001,view.zoom),color=ruiColor(d.grade),remaining=Math.max(0,d.remaining),label=`부활 ${ruiRevivalSeconds(remaining)}초`;
 c.strokeStyle=color;c.fillStyle='#10271feb';c.lineWidth=1.6/z;
 c.beginPath();c.ellipse(a.x,a.y,12/z,6/z,0,0,Math.PI*2);c.fill();c.stroke();
 c.beginPath();c.arc(a.x,a.y-13/z,7/z,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,remaining/bloomSeconds(CONFIG.rarity.respawnMs)));c.stroke();
 c.font=`bold ${11/z}px system-ui`;c.textAlign='center';const w=c.measureText(label).width;
 c.fillRect(a.x-w/2-4/z,a.y-38/z,w+8/z,15/z);c.fillStyle=color;c.fillText(label,a.x,a.y-27/z);
}});
function ruiDrawRevivalMarkers(){
 const world=bloomRenderWorld();for(const record of world.revivals){
  const point=record.point;if(!point||!projectionVisible(point,60))continue;
  WorldUI.draw('rarityRevival',point,{grade:record.grade,remaining:Math.max(0,record.respawnAt-world.time)});
 }
}
const rarityRevivalWorld=drawCampaignWorld;
drawCampaignWorld=function(...args){rarityRevivalWorld(...args);ruiDrawRevivalMarkers()};

