function soundCue(kind,u,extra={}) {
 if(!bloomInTick||!u)return;
 const keys=bloomCurrentEffects.soundKeys||(bloomCurrentEffects.soundKeys=new Map());
 const personal=['fusion','fusionFail','level','death','revive','roll','land'].includes(kind);
 const sourcePlayer=WorldPlayers.forEntity(u),cue={kind,id:u.id,x:u.x,y:u.y,z:u.z||0,...extra};
 for(const listener of WorldPlayers.all()) {
  if(listener.lifecycle!=='active')continue;
  const self=u.id===listener.leader.id;
  if(personal&&!self)continue;
  const lane=self?'self':sourcePlayer?.playerId===listener.playerId?'allied':'hostile';
  const key=JSON.stringify([listener.playerId,kind,extra.family||'',lane]);
  const distance=(u.x-listener.leader.x)**2+(u.y-listener.leader.y)**2;
  const old=keys.get(key);
  if(old) {
   if(distance<old.distance||distance===old.distance&&u.id<old.entityId) {
    old.distance=distance;old.entityId=u.id;bloomCurrentEffects[old.index].args[0]=cue;
   }
   continue;
  }
  keys.set(key,{distance,entityId:u.id,index:bloomCurrentEffects.length});
  bloomEmitTo(listener.playerId,'soundCue',[cue]);
 }
}

const soundRoll=beginMoaRoll;beginMoaRoll=function(...args){const r=soundRoll(...args);if(r)soundCue('roll',state.mother);return r};
const soundAcquire=rarityAcquire;rarityAcquire=function(owner,type,grade,...args) {
 const result=soundAcquire(owner,type,grade,...args),player=WorldPlayers.byAccount(owner);
 if(result&&player)soundCue('recruit',player.leader,{grade});
 return result;
};
const soundRespawn=rarityRespawn;rarityRespawn=function(account,record) {
 const body=record.body,result=soundRespawn(account,record);
 if(result&&WorldPlayers.byAccount(account.owner))soundCue('unitRevive',body);
 return result;
};

