const terrainProjectionScratch=new Float32Array(9);
const terrainMeshPending=[];
function terrainProjection(){const dpr=Math.min(CONFIG.render.dprMax,devicePixelRatio||1),zx=dpr*view.zoom,zy=zx*WorldProjection.K;terrainProjectionScratch[0]=zx;terrainProjectionScratch[1]=0;terrainProjectionScratch[2]=0;terrainProjectionScratch[3]=0;terrainProjectionScratch[4]=zy;terrainProjectionScratch[5]=0;terrainProjectionScratch[6]=zx*(view.w/2-view.x);terrainProjectionScratch[7]=zy*(view.h/2-view.y);terrainProjectionScratch[8]=1;return terrainProjectionScratch}
function buildTerrainMesh(tx,ty){const painter=new TerrainMeshPainter(),x=tx*512-2,y=ty*512-152,w=516,h=666;painter.setBounds(x,y,w,h);themedDrawStatic(painter,{x,y,w,h},true);return painter.finish()}
function terrainBuildPulse(){const tile=terrainMeshPending.shift();if(!tile||themedTileCache.get(tile.key)!==tile)return;const started=BloomDiagnostics.profileEnabled()?performance.now():0,vertices=buildTerrainMesh(tile.tx,tile.ty);tile.mesh=ctx.createStaticMesh(vertices);if(started)BloomDiagnostics.profileStage('render.terrainMeshBuild',performance.now()-started,{vertices:vertices.length/6,bytes:vertices.byteLength})}
function themedTile(tx,ty){const key=tx+','+ty+','+WorldProjection.H+'/'+WorldProjection.K;if(themedTileCache.has(key)){BloomDiagnostics.profileCount('render.terrainMeshCacheHit');return themedTileCache.get(key)}const tile={key,tx,ty,mesh:null,x:tx*512-2,y:ty*512-152};themedTileCache.set(key,tile);terrainMeshPending.push(tile);ThemedTerrain.stats.tiles++;BloomDiagnostics.profileCount('render.terrainMeshCacheMiss');if(themedTileCache.size>24){const keyToDelete=themedTileCache.keys().next().value,old=themedTileCache.get(keyToDelete);themedTileCache.delete(keyToDelete);if(old?.mesh)ctx.deferDeleteStaticMesh(old.mesh)}return tile}
buildTerrain=function(){terrainMeshPending.length=0;for(const tile of themedTileCache.values())if(tile.mesh)ctx.deleteStaticMesh(tile.mesh);themedTileCache.clear()};
drawOpenWorldGround=function(){
 ctx.save();ctx.fillStyle='#14271f';ctx.fillRect(0,0,CONFIG.openWorld.width,CONFIG.openWorld.height);
 const x0=Math.max(0,Math.floor((view.x-view.w/2-20)/512)),x1=Math.min(Math.ceil(CONFIG.openWorld.width/512)-1,Math.floor((view.x+view.w/2+20)/512)),y0=Math.max(0,Math.floor((view.y-view.h/2-20)/512)),y1=Math.min(Math.ceil(CONFIG.openWorld.height/512)-1,Math.floor((view.y+view.h/2+180)/512));
 terrainBuildPulse();const projection=terrainProjection();for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const t=themedTile(x,y);if(t.mesh)ctx.drawStaticMesh(t.mesh,projection)}
 ctx.textAlign='center';for(let i=0;i<5;i++){const p=openWorldRegionSpawn(i);if(!projectionVisible(p,140))continue;WorldUI.begin(ctx,p,{at:'ground'});ctx.fillStyle='#e2e7bcc0';ctx.font='bold 16px system-ui';ctx.fillText(CONFIG.campaign.grounds[i].name,p.x,p.y-95);ctx.restore()}
 for(const c of bloomRenderWorld().camps)for(const q of c.regrowth||[]){if(!q.point||!projectionVisible(q.point,70))continue;const p=q.point,k=1-q.left/CONFIG.rectWorld.cue;ctx.strokeStyle='#e4f3a8';ctx.lineWidth=2;ctx.beginPath();terrainCirclePath(p.x,p.y,18+12*k);ctx.stroke()}ctx.restore();
};
