drawOpenWorldOverview=function(c,width,height,player=true){const W=CONFIG.openWorld.width,H=CONFIG.openWorld.height,scale=Math.min(width/W,height/H);c.clearRect(0,0,width,height);c.fillStyle='#14271f';c.fillRect(0,0,width,height);c.save();c.translate((width-W*scale)/2,(height-H*scale)/2);c.scale(scale,scale);themedDrawStatic(c,{x:0,y:0,w:W,h:H},false);const b=CONFIG.residentBoss.habitat;c.strokeStyle='#e9bc78';c.lineWidth=2/scale;c.beginPath();c.arc(b.x,b.y,b.radius,0,Math.PI*2);c.stroke();if(player){c.fillStyle='#fff6ba';c.beginPath();c.arc(WorldView.leader().x,WorldView.leader().y,3/scale,0,Math.PI*2);c.fill()}c.restore()};
