patternJumpCanStart=function(u,t,C){if(spatialAir(u)!==0)return false;const n=Math.min(1,C.distance/Math.max(1,dist(u,t))),x=u.x+(t.x-u.x)*n,y=u.y+(t.y-u.y)*n;return pointClear(x,y,moaBodyRadius(u))};
