function drawThemedRoot(c,s,projected=true){const k=WorldProjection.H/WorldProjection.K;themedPath(c,s.points,0,projected);c.fillStyle='#304b35';c.fill();themedPath(c,s.points,s.height,projected);c.fillStyle='#6b6340';c.fill();c.strokeStyle='#3c512f';c.lineWidth=7;c.stroke();const cy=s.cy-(projected?(ThemedTerrain.height(s.cx,s.cy)+s.height)*k:0);c.strokeStyle='#a59359';c.lineWidth=8;c.beginPath();for(let i=0;i<s.points.length;i+=8){const p=s.points[i];c.moveTo(s.cx,cy);c.quadraticCurveTo(s.cx+(p.x-s.cx)*.45+12,cy+(p.y-s.cy)*.4,p.x,p.y-(projected?(ThemedTerrain.height(p.x,p.y)+s.height)*k:0))}c.stroke();for(let i=0;i<5;i++){const a=i*2.4,px=s.cx+Math.cos(a)*34,py=cy+Math.sin(a)*24;c.fillStyle=['#47794a','#527f4e','#3e7045'][i%3];c.strokeStyle='#355c3a';c.lineWidth=3;c.beginPath();c.ellipse(px,py,68,57,a*.1,0,Math.PI*2);c.fill();c.stroke()}}

drawProjectedActors=function(){projectionQueue.length=0;let order=0;
 for(const u of bloomRenderUnits())if(u.hp>0&&projectionVisible(u,Math.max(120,unitVisualExtent(u)))){const p=projectionBodyPose(u);projectionEnqueue('unit',u,WorldProjection.depth(p.y,p.z),order++,p)}
 for(const p of bloomRenderLeaders())if(p.hp>0&&projectionVisible(p,Math.max(120,unitVisualExtent(p))))projectionEnqueue('mother',p,WorldProjection.depth(p.y,projectionUnitHeight(p)),order++);
 for(const d of healthJuice.dead){const p=indicatorDeathPose(d);projectionEnqueue('death',d,WorldProjection.depth(p.y,p.z),order++)}
 for(const sampled of bloomRenderProjectiles()){const v=sampled.abilityShot?sproutVisualPoint(sampled):sampled;if(!bloomProjectileVisible(sampled))continue;projectionEnqueue('projectile',sampled,WorldProjection.depth(v.y,v.z||0),order++)}
 for(const s of ThemedTerrain.shapes)if(s.kind==='root'&&s.maxX>=view.x-view.w/2-160&&s.minX<=view.x+view.w/2+160&&s.maxY>=view.y-view.h/2-160&&s.minY<=view.y+view.h/2+240)projectionEnqueue('terrain',s,WorldProjection.depth(s.maxY,0),order++);
 for(const q of projectionQueue){if(q.kind==='unit'||q.kind==='mother'){const u=presentationPose(q.source);cshadow(u.x,u.y,unitVisualRadius(u)*CONFIG.render.spriteScale*.8)}else if(q.kind==='death'){const p=indicatorDeathPose(q.source);ctx.save();if(q.source.moa)ctx.globalAlpha*=deathSample(q.source).alpha;cshadow(p.x,p.y,q.source.r*.8);ctx.restore()}}
 projectionQueue.sort((a,b)=>a.depth-b.depth||a.order-b.order);
 projectionDrawingActors=true;try{for(const q of projectionQueue){if(q.kind==='terrain')drawThemedRoot(ctx,q.source);else if(q.kind==='unit')drawUnit(q.source,q);else if(q.kind==='mother'){drawMother(q.source);if(!WorldView.isLocal(q.source))drawParticipantLabel(q.source);}else if(q.kind==='projectile')drawProjectedProjectile(q.source);else drawDeathBodies(q.source.air,q.source.pose.type==='mother',q.source)}}finally{projectionDrawingActors=false}if(WorldView.dead())drawSproutImpacts();CombatFeedback.draw();
};

'use strict';
/* A channel latch is valid only while its owning projectile exists. Defeat,
 * collection fusion and recall can discard projectiles outside gearFinish().
 * Keep legitimate channels untouched; expire latches after external disposal. */
const channelLifecycleCore={onProjectileDisposed};
onProjectileDisposed=function(p){if(p?.equippedAttack&&CONFIG.levelAbilities.cards[p.weapon]?.channel)gearFinish(p);return channelLifecycleCore.onProjectileDisposed(p)};
gearChannelActive=function(owner,id){const shotId=owner.gearChannels?.[id];return !!shotId&&projectiles.some(p=>p.shotId===shotId&&p.u===owner.id&&p.weapon===id&&p.equippedAttack&&!p.finished)};
function gearExpireChannel(owner,id){if(owner.gearChannels?.[id]&&!gearChannelActive(owner,id))delete owner.gearChannels[id]}


'use strict';
/* Is-a: attack-family adapter. Has-a: owned stats. Can-be: declared upgrade
 * capabilities. A card is data, never a JavaScript path or a weapon-name branch.
 * Legacy primary traits intentionally retain their existing compositional rules. */
CONFIG.weaponCards={schema:3,drawSize:3,seed:0x41c6ce57,
 poolWeights:{unlock:25,upgrade:75},groupWeights:{count:8,form:42,damage:50},
 displayDigits:2,percent:100,radiansToDegrees:180/Math.PI,
 families:{
  homing:{properties:['count','radius','speed','range','cadence','damage'],capabilities:['multiple','size','speed','range','cooldown','damage']},
  ballistic:{properties:['arcHeight','launchLift','count','radius','splash','speed','range','cadence','damage'],capabilities:['trajectory','multiple','size','area','speed','range','cooldown','damage']},
  sweep:{properties:['width','victims','speed','range','cadence','damage'],capabilities:['size','pierce','speed','range','cooldown','damage']},
  field:{properties:['arcHeight','count','radius','splash','speed','range','cadence','damage','duration','interval'],capabilities:['trajectory','multiple','size','area','speed','duration','interval','range','cooldown','damage']},
  focus:{properties:['range','cadence','damage','duration','interval','focusTime','focusMultiplier'],capabilities:['duration','interval','focus','range','cooldown','damage']},
  chain:{properties:['range','cadence','damage','bounces','linkRange','falloff'],capabilities:['chain','range','cooldown','damage']},
  cone:{properties:['range','cadence','damage','duration','interval','angle'],capabilities:['angle','duration','interval','range','cooldown','damage']}
 },
 // Types constrain real dimensions. The only saturation is physical: a full
 // circle, a pulse every simulation tick, or full retained chain damage.
 types:{count:{integer:true,min:1},bounces:{integer:true,min:0},distance:{min:0},seconds:{min:bloomSeconds(BLOOM_TIME.weapons.cardMinimumMs)},coefficient:{min:0},angle:{min:0,max:Math.PI*2},retention:{min:0,max:1}},
 // Shared reusable property definitions. Weapon entries override base/amount;
 // optional variants add cards without touching selection, UI, save or combat.
 properties:{
  arcHeight:{type:'distance',capability:'trajectory',label:'탄도 곡선 높이',unit:'거리',group:'form',operation:'baseAdd',amount:.15,weight:1,offer:false},
  launchLift:{type:'distance',capability:'trajectory',label:'발사 높이 보정',unit:'거리',group:'form',operation:'baseAdd',amount:.15,weight:1,offer:false},
  count:{type:'count',capability:'multiple',label:'발수',unit:'발',group:'count',operation:'add',amount:1,weight:1},
  radius:{type:'distance',capability:'size',label:'탄 반경 · 충돌 크기',unit:'거리',group:'form',operation:'baseAdd',amount:.2,weight:1},
  splash:{type:'distance',capability:'area',label:'피해 반경',unit:'거리',group:'form',operation:'baseAdd',amount:.15,weight:.8},
  width:{type:'distance',capability:'size',label:'가시 통로 반폭',unit:'거리',group:'form',operation:'baseAdd',amount:.2,weight:1},
  victims:{type:'count',capability:'pierce',label:'관통 대상',unit:'마리',group:'count',operation:'add',amount:1,weight:1.5},
  speed:{type:'distance',capability:'speed',label:'탄 이동 속도',unit:'거리/초',group:'form',operation:'baseAdd',amount:.15,weight:1},
  range:{type:'distance',capability:'range',label:'사거리',unit:'거리',group:'form',operation:'baseAdd',amount:.15,weight:1},
  cadence:{type:'seconds',capability:'cooldown',label:'재사용 시간',unit:'초',group:'form',operation:'divide',amount:.12,weight:.7},
  damage:{type:'coefficient',capability:'damage',label:'1회 피해',unit:'피해',group:'damage',operation:'baseAdd',amount:.18,weight:1},
  duration:{type:'seconds',capability:'duration',label:'지속시간',unit:'초',group:'form',operation:'baseAdd',amount:.2,weight:.8},
  interval:{type:'seconds',capability:'interval',label:'피해 간격',unit:'초',group:'form',operation:'add',amount:-bloomSeconds(BLOOM_TIME.weapons.cardMinimumMs),weight:.5},
  focusTime:{type:'seconds',capability:'focus',label:'집중 단계 간격',unit:'초',group:'form',operation:'divide',amount:.15,weight:.6},
  focusMultiplier:{type:'coefficient',capability:'focus',label:'단계당 집중 배율',unit:'배',group:'damage',operation:'add',amount:.1,weight:.4},
  bounces:{type:'bounces',capability:'chain',label:'추가 연결',unit:'회',group:'count',operation:'add',amount:1,weight:1},
  linkRange:{type:'distance',capability:'chain',label:'다음 적 연결거리',unit:'거리',group:'form',operation:'baseAdd',amount:.15,weight:1},
  falloff:{type:'retention',capability:'chain',label:'연결당 피해 유지율',unit:'%',group:'damage',operation:'add',amount:.05,weight:.6},
  angle:{type:'angle',capability:'angle',label:'분사각',unit:'°',group:'form',operation:'add',amount:Math.PI/12,weight:.7}
 },
 weapons:{
  pod:{family:'homing',stats:{count:1,radius:CONFIG.moa.seedRadius,speed:520,range:235,cadence:1.15,damage:.6}},
  lob:{family:'ballistic',stats:{arcHeight:86,launchLift:24,count:1,radius:CONFIG.moa.seedRadius,splash:60,speed:290,range:215,cadence:1.85,damage:.85}},
  thorn:{family:'sweep',stats:{width:13,victims:3,speed:500,range:290,cadence:1.55,damage:.7}},
  spore:{family:'field',stats:{arcHeight:32,count:1,radius:7,splash:70,speed:330,range:240,cadence:4.4,damage:.16,duration:4,interval:.5}},
  beam:{family:'focus',stats:{range:250,cadence:4,damage:.15,duration:3.6,interval:.25,focusTime:1.5,focusMultiplier:1.5}},
  chain:{family:'chain',stats:{range:230,cadence:1.8,damage:.78,bounces:2,linkRange:125,falloff:.65}},
  breath:{family:'cone',stats:{range:170,cadence:2.4,damage:.3375,duration:1,interval:.25,angle:Math.PI/3}}
 }
};
const WeaponCardRegistry=new Map();
const weaponSpecCache=new WeakMap();let weaponDefinitionRevision=0;
function weaponProperty(id,key){const w=CONFIG.weaponCards.weapons[id];return w&&Object.hasOwn(w.stats,key)?{...CONFIG.weaponCards.properties[key],...(w.overrides?.[key]||{}),base:w.stats[key]}:null}
function weaponBuildRegistry(){
 WeaponCardRegistry.clear();weaponDefinitionRevision++;const C=CONFIG.weaponCards;
 for(const [id,c]of Object.entries(CONFIG.levelAbilities.cards))WeaponCardRegistry.set(id,{id,weapon:id,kind:c.kind==='trait'?'trait':'unlock',group:c.kind==='trait'?(id==='pierce'?'count':'damage'):null,weight:1});
 for(const [id,w]of Object.entries(C.weapons)){
  const family=C.families[w.family];if(!family)throw new TypeError('Unknown weapon family '+w.family);
  for(const key of Object.keys(w.stats)){
   const p=weaponProperty(id,key);if(!p||!C.types[p.type]||!family.properties.includes(key)||!family.capabilities.includes(p.capability))throw new TypeError('Unsupported weapon property '+id+':'+key);
   if(!Number.isFinite(p.base)||p.base<0)throw new TypeError('Invalid weapon base '+id+':'+key);if(p.offer===false)continue;
   const variants=p.variants||[{operation:p.operation,amount:p.amount,weight:p.weight}];
   for(const v of variants){const card={id:id+':'+key+(v.id?':'+v.id:''),weapon:id,property:key,kind:'modifier',group:p.group,operation:v.operation??p.operation,amount:v.amount??p.amount,weight:v.weight??p.weight};
    if(WeaponCardRegistry.has(card.id)||!['add','baseAdd','divide'].includes(card.operation)||!Number.isFinite(card.amount)||!Number.isFinite(card.weight)||card.weight<=0)throw new TypeError('Invalid weapon card '+card.id);
    WeaponCardRegistry.set(card.id,card);
   }
  }
 }
}
weaponBuildRegistry();CONFIG.levelAbilities.schema=CONFIG.weaponCards.schema;
function weaponNewState(){return{schema:CONFIG.weaponCards.schema,xp:0,level:1,chosen:0,ranks:{},mods:{},draft:null,rng:CONFIG.weaponCards.seed}}
function weaponOwnerState(owner=state.mother){return owner?.rivalLeader?owner.rival.abilities:WorldPlayers.dataFor(owner).campaign.abilities}
function weaponOwnerGrowth(owner=state.mother){return owner?.rivalLeader?rivalGrowth(owner):WorldPlayers.dataFor(owner).campaign.growthCards}
function weaponBasePower(owner=state.mother){return owner?.rivalLeader?rivalPower(owner):PlayerActor.basePower(WorldPlayers.forEntity(owner))}
function weaponStats(id,owner=state.mother,a=weaponOwnerState(owner)){
 const w=CONFIG.weaponCards.weapons[id];if(!w)return null;
 let cached=a&&weaponSpecCache.get(a);if(!cached||cached.chosen!==a.chosen||cached.revision!==weaponDefinitionRevision){cached={chosen:a.chosen,revision:weaponDefinitionRevision,specs:{}};weaponSpecCache.set(a,cached)}if(cached.specs[id])return cached.specs[id];
 const result={...CONFIG.levelAbilities.cards[id],family:w.family};
 for(const [key,base]of Object.entries(w.stats)){
  let added=0,divisor=1;
  for(const [cardId,n]of Object.entries(a?.mods||{})){const c=WeaponCardRegistry.get(cardId);if(c?.weapon!==id||c.property!==key)continue;if(c.operation==='divide')divisor+=c.amount*n;else added+=(c.operation==='baseAdd'?base:1)*c.amount*n;}
  const p=weaponProperty(id,key),type=CONFIG.weaponCards.types[p.type];let value=(base+added)/divisor;
  value=Math.max(type.min,value);if(type.max!==undefined)value=Math.min(type.max,value);if(type.integer)value=Math.round(value);
  result[key]=value;
 }
 cached.specs[id]=Object.freeze(result);return cached.specs[id];
}
function weaponCanChoose(c,a,owner=state.mother){
 if(!c)return false;
 if(c.kind==='unlock')return !a.ranks[c.weapon];
 if(c.kind==='trait')return true;
 if(!a.ranks[c.weapon])return false;
 const before=weaponStats(c.weapon,owner,a)[c.property],next={...a,mods:{...a.mods,[c.id]:(a.mods[c.id]||0)+1}},after=weaponStats(c.weapon,owner,next)[c.property];
 return Number.isFinite(after)&&after!==before;
}
