/* v58 session contract. Gameplay duration definitions are milliseconds; one SDK tick is one
 * world update. There is no hidden 30 Hz inner physics loop. Discrete AI phase
 * transitions round up by less than one chosen tick; swept movement and weapon
 * pulses integrate the actual elapsed interval. */
const BLOOM_TPS_OPTIONS=Object.freeze([10,20,30]);
CONFIG.sim.tickRate=30;
CONFIG.sim.renderTargetFPS=60;
CONFIG.sim.timeUnit=BLOOM_TIME.unit;
function bloomApplyTickRate(rate){
 if(!BLOOM_TPS_OPTIONS.includes(rate))throw new RangeError('Simulation TPS must be 10, 20, or 30');
 CONFIG.sim.tickRate=rate;CONFIG.sim.fixedStep=1/rate;CONFIG.qa.maxStep=1/rate;
}
function bloomConfiguredTickRate(){let rate=Number(globalThis.BLOOM_SIM_TPS);if(!BLOOM_TPS_OPTIONS.includes(rate)&&!globalThis.BLOOM_HEADLESS)try{rate=Number(localStorage.getItem('bloom-simulation-tps'))}catch{}return BLOOM_TPS_OPTIONS.includes(rate)?rate:10}
bloomApplyTickRate(bloomConfiguredTickRate());
// Millisecond roll integration preserves exact 128-unit / 266.6667 ms motion,
// including the final partial interval at 10 TPS. World sweeps remain analytic.

moaRollRechargeMs=function(g=growthState()){return Math.max(0,moaAbilityCooldown(CONFIG.moaRoll.cooldownMs,g))};
// Changing the budget is a paused session boundary, never a live speed switch.
// All peers negotiate the same SDK tickRate and simulationVersion.
// Changing TPS cannot change ms timers or event identity. SDK indices are not durations.
function bloomSetTickRate(rate){
 rate=Number(rate);if(!BLOOM_TPS_OPTIONS.includes(rate))throw new RangeError('Unsupported simulation budget');
 if(bloomInTick||typeof BloomSimulation!=='undefined'&&BloomSimulation.multiplayer||playing&&!paused)throw new Error('Change TPS only at a paused single-player session boundary');
 const old=CONFIG.sim.tickRate;if(old===rate)return rate;
 bloomApplyTickRate(rate);
 if(!globalThis.BLOOM_HEADLESS)try{localStorage.setItem('bloom-simulation-tps',String(rate))}catch{}
 if(typeof bloomSession!=='undefined'&&bloomSession)bloomStartDriver();resetPresentation();return rate;
}
