/* Shared world authority. A participant is a human-controlled faction; its
 * leader has movement/combat capabilities and owns progression/controller data.
 * Before session admission, bootstrap queries read the newly initialized root
 * actor. No tick swaps state.mother or selects authority from the local camera. */
function worldEntityReferenceValid(id,source){return Number.isSafeInteger(id)&&id>=(source?.participants?(source.nextPlayerEntity+1):-1)&&id<=(source?.nextId??0)}
const WorldPlayers=globalThis.WorldPlayers=(()=>{
 let localPlayerId='solo';
 function bootstrap(source){return source?.mother&&!source.participants?{playerId:'solo',accountOwner:-1,leader:source.mother,data:null,lifecycle:'active',auto:autoHunt,navigation:pointNav}:null}
 function all(source=state){return source?.participants?Object.values(source.participants).sort((a,b)=>a.playerId<b.playerId?-1:a.playerId>b.playerId?1:0):bootstrap(source)?[bootstrap(source)]:[]}
 function data(player,source=state){return player?.data||source}
 function get(playerId,source=state){return source?.participants?.[playerId]||(playerId==='solo'?bootstrap(source):null)}
 function byAccount(owner,source=state){return all(source).find(p=>p.accountOwner===owner)||null}
 function forEntity(entity,source=state){if(!entity)return null;return entity.playerId?get(entity.playerId,source):entity===source?.mother?byAccount(-1,source):entity.rarityOwner!==undefined?byAccount(entity.rarityOwner,source):entity.team==='friendly'?byAccount(-1,source):null}
 function bindInitial(playerId='solo'){
  if(state.participants)return get(playerId);
  state.participants={};state.membershipEpoch=-1;state.nextPlayerEntity=-2;
  const player={playerId,accountOwner:-1,leader:state.mother,data:null,lifecycle:'active',admission:0,auto:{...autoHunt},navigation:JSON.parse(JSON.stringify(pointNav))};
  state.participants[playerId]=player;player.leader.playerId=playerId;
  for(const u of state.units){if(u.team==='friendly')u.playerId=playerId;for(const mark of u.moaRecruitMarks||[])if(mark.ownerId===-1)mark.faction='player:'+playerId;}
  return player;
 }
 function local(){return get(localPlayerId)||(!state?.participants?byAccount(-1):null)}
 return Object.freeze({validate:worldPlayersValidate,all,get,byAccount,forEntity,data,dataFor:(u,source=state)=>data(forEntity(u,source),source),bindInitial,
  interests:()=>all().filter(p=>p.lifecycle==='active'&&p.leader.hp>0).map(p=>({...p,huntView:data(p).campaign.huntView})),
  local,setLocalPlayerId(id){localPlayerId=id;if(!bloomInTick&&!globalThis.BLOOM_HEADLESS&&presentation.runtime){const active=presentation.active;presentation.active=false;try{capturePresentation(true)}finally{presentation.active=active}}},get localPlayerId(){return localPlayerId}});
})();
